if(typeof T!=='function'){ window.T=function(s){return s;}; window.tt=function(a){return a;}; window.getAppLang=function(){return 'fa';}; window.setAppLang=function(){}; }
/* ============================================================
   STATE & API
============================================================ */
let ME = null;
// Master lists (warehouses, groups, …) must be null — NOT [] — so `if(!CACHE.warehouses)`
// actually fetches. Empty array is truthy and used to block reload until you open that section.
let CACHE = { customers:[], products:[], allProducts:[], _invProducts:[], users:[], orders:[], followups:[], invoices:[], settings:{}, productCategories:null, warehouses:null, productCats:null, partyGroups:null, _prodWarehouses:null, _prodCats:null, _prodMetaLoaded:false };
let mChart = null;
let APP_INFO = null, PENDING_UPDATE = null;
const _apiCache = {};
let _dashHtmlCache = { key:'', html:'', t:0 };
function cacheGet(key, ttlMs=45000){ const h=_apiCache[key]; return h && Date.now()-h.t<ttlMs ? h.v : null; }
function cacheSet(key,v){ _apiCache[key]= { t:Date.now(), v }; }
function clearPageCache(){ Object.keys(_apiCache).forEach(k=>delete _apiCache[k]); _dashHtmlCache={key:'',html:'',t:0}; }
/** Drop stale master-data caches after sync / mutations so all screens see fresh lists. */
function invalidateMasterCaches(){
  CACHE.warehouses=null; CACHE._prodWarehouses=null; CACHE._prodCats=null; CACHE._prodMetaLoaded=false;
  CACHE.productCategories=null; CACHE.productCats=null; CACHE.partyGroups=null;
  CACHE.customerGroups=null; CACHE.banks=null; CACHE.cashBoxes=null; CACHE.checkCategories=null;
  CACHE.persons=null; CACHE.personCategories=null; CACHE.costCenters=null;
  CACHE.suppliers=null; CACHE.parties=null; CACHE.chartOfAccounts=null;
  clearPageCache();
}
async function ensureWarehouses(force){
  // Access/ACL UIs pass force=true for live master data (no stale CACHE).
  if(force || !CACHE.warehouses?.length){
    try{
      CACHE.warehouses = await api('GET','/warehouses')||[];
      CACHE._prodWarehouses = CACHE.warehouses;
    }catch(_){
      CACHE.warehouses = null;
      CACHE._prodWarehouses = null;
      return [];
    }
  }
  return CACHE.warehouses||[];
}
async function ensurePartyGroups(force){
  if(force || !CACHE.partyGroups?.length){
    try{ CACHE.partyGroups = await api('GET','/party-groups')||[]; }
    catch(_){ CACHE.partyGroups=null; return []; }
  }
  return CACHE.partyGroups||[];
}
async function ensureProductCategories(force){
  if(force || !CACHE.productCategories?.length){
    try{ CACHE.productCategories = await api('GET','/product-categories')||[]; }
    catch(_){ CACHE.productCategories=null; return []; }
  }
  return CACHE.productCategories||[];
}
/** Live master lists for access dropdowns / ACL (always refetch). */
async function loadLiveProductGroupsForAccess(){
  try{
    const rows = await api('GET','/product-categories?for=access')||[];
    CACHE.productCategories = rows;
    return rows;
  }catch(_){
    return await ensureProductCategories(true);
  }
}
async function loadLiveWarehousesForAccess(){
  return ensureWarehouses(true);
}
function warehouseOptionsHtml(selectedId, emptyLabel){
  const sel = selectedId==null||selectedId==='' ? '' : String(selectedId);
  const rows = (CACHE.warehouses||[]).filter(w=>w.active!==0);
  return `<option value="">${esc(emptyLabel||'— انتخاب انبار —')}</option>` +
    rows.map(w=>`<option value="${w.id}" ${sel===String(w.id)?'selected':''}>${esc(w.name)}${w.code?' ('+esc(w.code)+')':''}</option>`).join('');
}
async function apiCached(method,path,ttlMs=45000){
  const k=method+':'+path;
  const hit=cacheGet(k,ttlMs);
  if(hit!==null) return hit;
  const r=await api(method,path);
  cacheSet(k,r);
  return r;
}

// Product image URLs — device builds pull missing files from central on demand
function prodImgUrl(name){ return name ? '/uploads/products/'+encodeURIComponent(name) : ''; }
function prodImgTag(name, extra=''){
  if(!name) return '🧥';
  const safe = String(name).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
  return `<img src="${prodImgUrl(name)}" loading="lazy" decoding="async" ${extra} data-csp-error="${CSP.bind('error',function(event){retryProdImg(this,`${String((safe) ?? '')}`)})}">`;
}
async function retryProdImg(img, name){
  if(img.dataset.retried){ img.replaceWith(document.createTextNode('🧥')); return; }
  img.dataset.retried='1';
  if(SYNC_MODE){
    try{
      const token=localStorage.getItem('crm_token');
      await fetch('/api/sync/pull-files',{method:'POST',headers:{'Authorization':'Bearer '+token}});
    }catch(e){}
  }
  img.src=prodImgUrl(name)+'?t='+Date.now();
}

