/* ============================================================
   JALALI DATE CONVERSION
============================================================ */
function _g2j(gy,gm,gd){
  var g2=[0,31,59,90,120,151,181,212,243,273,304,334];
  var gy2=(gm>2)?(gy+1):gy;
  var days=355666+(365*gy)+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)+gd+g2[gm-1];
  var jy=-1595+(33*Math.floor(days/12053));
  days%=12053; jy+=4*Math.floor(days/1461); days%=1461;
  if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365;}
  var jm,jd;
  if(days<186){jm=1+Math.floor(days/31);jd=1+(days%31);}
  else{jm=7+Math.floor((days-186)/30);jd=1+((days-186)%30);}
  return[jy,jm,jd];
}
function _jIsLeap(y){return((((y-474)%2820)+474+38)*682)%2816<682;}
function _jDIM(m,y){return m<=6?31:m<=11?30:_jIsLeap(y)?30:29;}
function _j2g(jy,jm,jd){
  jy+=1595;
  var days=-355668+(365*jy)+(Math.floor(jy/33)*8)+Math.floor(((jy%33)+3)/4)+jd+((jm<7)?(jm-1)*31:((jm-7)*30+186));
  var gy=400*Math.floor(days/146097); days%=146097;
  if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++;}
  gy+=4*Math.floor(days/1461); days%=1461;
  if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365;}
  var gd=days+1;
  var sal=[0,31,((gy%4===0&&gy%100!==0)||(gy%400===0))?29:28,31,30,31,30,31,31,30,31,30,31];
  var gm;for(gm=0;gm<13&&gd>sal[gm];gm++)gd-=sal[gm];
  return[gy,gm,gd];
}
const J_MONTHS = ['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
const J_WEEK = ['ش','ی','د','س','چ','پ','ج'];
let _srvOffset = 0; // ms offset between server clock and client clock
function _serverNow(){ return new Date(Date.now() + _srvOffset); }
function todayJalali(){
  const d=_serverNow();
  const ds=d.toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'});
  const [gy,gm,gdd]=ds.split('-').map(Number);
  const [y,m,dd]=_g2j(gy,gm,gdd);
  return y+'/'+String(m).padStart(2,'0')+'/'+String(dd).padStart(2,'0');
}
async function syncServerTime(){
  try{
    const t0=Date.now();
    const r=await fetch('/api/system/time'); if(!r.ok) return;
    const j=await r.json(); const rtt=Date.now()-t0;
    if(j.ts) _srvOffset=(j.ts+rtt/2)-Date.now();
  }catch(e){}
}
const _jfmt=(y,m,d)=>y+'/'+String(m).padStart(2,'0')+'/'+String(d).padStart(2,'0');
// Preset Jalali date ranges: week (Saturday-start), month, lastMonth → [from, to]
function jPresetRange(preset){
  const today=todayJalali();
  const [jy,jm]=today.split('/').map(Number);
  if(preset==='week'){
    const ds=_serverNow().toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'});
    const [gy,gm,gd]=ds.split('-').map(Number);
    const dow=new Date(gy,gm-1,gd).getDay();     // Sun=0 … Sat=6
    const sinceSat=(dow+1)%7;                    // days since Saturday (Iranian week start)
    const st=new Date(gy,gm-1,gd); st.setDate(st.getDate()-sinceSat);
    const [sy,sm,sd]=_g2j(st.getFullYear(),st.getMonth()+1,st.getDate());
    return [_jfmt(sy,sm,sd), today];
  }
  if(preset==='month') return [_jfmt(jy,jm,1), today];
  if(preset==='lastMonth'){
    const py=jm===1?jy-1:jy, pm=jm===1?12:jm-1;
    return [_jfmt(py,pm,1), _jfmt(py,pm,_jDIM(pm,py))];
  }
  return ['',''];
}
// Shared preset <select> for date toolbars; onPick(from,to,preset) fires on change
function presetSelect(id,current,handler){
  const opts=[['month','ماه جاری'],['week','هفته جاری'],['lastMonth','ماه قبل'],['all','همه'],['custom','بازه دلخواه']];
  return `<select id="${id}" data-csp-change="${CSP.bind('change',function(event){CSP.resolve(handler)(this.value)})}" data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;font-family:inherit;font-size:12px`)}">
    ${opts.map(([v,l])=>`<option value="${v}" ${current===v?'selected':''}>${l}</option>`).join('')}
  </select>`;
}

/* ---- Searchable Customer Select ---- */
function custSelect(id, selectedId, optional=false){
  const sel=selectedId?CACHE.customers.find(c=>c.id===+selectedId):null;
  const ph=optional?'مشتری مرتبط (اختیاری)...':'جستجو: نام، موبایل، کد...';
  return `<div class="cust-sw" data-cs-id="${esc(id)}">
    <input type="hidden" id="${esc(id)}" value="${selectedId||''}" data-optional="${optional?1:0}">
    <input type="text" id="${esc(id)}-input" class="cust-si" placeholder="${ph}" value="${sel?esc(sel.biz):''}">
    <div id="${esc(id)}-drop" class="cust-si-drop" data-csp-style="${CSP.style(`display:none;position:fixed;width:280px;max-height:220px`)}"></div>
  </div>`;
}
function initCustSearches(scope){
  (scope||document).querySelectorAll('.cust-sw').forEach(sw=>{
    const id=sw.dataset.csId;
    const kind=sw.dataset.kind||'customer';
    const inp=el(id+'-input');
    if(!inp||inp.dataset.csBound) return;
    inp.dataset.csBound='1';
    inp.addEventListener('focus',()=>kind==='supplier'?showSupplierDrop(id,''):showCustDrop(id,''));
    inp.addEventListener('input',()=>kind==='supplier'?showSupplierDrop(id,inp.value):showCustDrop(id,inp.value));
    inp.addEventListener('keydown',e=>{
      if(e.key==='Escape'){kind==='supplier'?hideSupplierDrop(id):hideCustDrop(id);}
    });
  });
}
// Supplier search initializer — alias so purchase/return modals can call either name
function initSupplierSearches(scope){ initCustSearches(scope); }
function supplierSelect(id, selectedId){
  const sel=selectedId?(CACHE.suppliers||[]).find(s=>s.id===+selectedId):null;
  return `<div class="cust-sw supp-sw" data-cs-id="${esc(id)}" data-kind="supplier">
    <input type="hidden" id="${esc(id)}" value="${selectedId||''}">
    <input type="text" id="${esc(id)}-input" class="cust-si" placeholder="جستجو: نام تأمین‌کننده..." value="${sel?esc(sel.name):''}">
    <div id="${esc(id)}-drop" class="cust-si-drop" data-csp-style="${CSP.style(`display:none;position:fixed;width:280px;max-height:220px`)}"></div>
  </div>`;
}
function showSupplierDrop(id, q){
  const drop=el(id+'-drop'); const inp=el(id+'-input'); if(!drop||!inp) return;
  const term=(q||'').trim().toLowerCase();
  let list=CACHE.suppliers||[];
  if(term){ const words=term.split(/\s+/); list=list.filter(s=>{const hay=((s.name||'')+' '+(s.phone||'')).toLowerCase(); return words.every(w=>hay.includes(w));}); }
  const rect=inp.getBoundingClientRect();
  drop.style.top=(rect.bottom+2)+'px'; drop.style.left=rect.left+'px'; drop.style.width=rect.width+'px'; drop.style.display='block';
  drop.innerHTML = list.slice(0,40).map(s=>`
    <div class="cust-si-item" data-csp-click="${CSP.bind('click',function(event){pickSupplier(`${String((id) ?? '')}`,(s.id))})}">
      <span>${esc(s.name)}</span><span class="cust-si-meta">${esc(s.phone||'')}</span>
    </div>`).join('') || '<div class="cust-si-empty">تأمین‌کننده یافت نشد</div>';
}
function pickSupplier(id, supId){
  const h=el(id); if(h){ h.value=supId||''; h.dispatchEvent(new Event('change')); }
  const inp=el(id+'-input');
  if(inp){ const s=(CACHE.suppliers||[]).find(x=>x.id===+supId); inp.value=s?s.name:''; }
  hideSupplierDrop(id);
}
function hideSupplierDrop(id){ const drop=el(id+'-drop'); if(drop) drop.style.display='none'; }
function showCustDrop(id, q){
  const drop=el(id+'-drop'); if(!drop) return;
  const inp=el(id+'-input'); if(!inp) return;
  const optional=el(id)?.dataset?.optional==='1';
  const term=(q||'').trim().toLowerCase();
  let list=CACHE.customers;
  if(term){
    const words=term.split(/\s+/);
    list=list.filter(c=>{
      const hay=((c.biz||'')+' '+(c.phone||'')+' '+(c.owner||'')).toLowerCase();
      return words.every(w=>hay.includes(w));
    });
  }
  const rect=inp.getBoundingClientRect();
  drop.style.top=(rect.bottom+2)+'px';
  drop.style.left=rect.left+'px';
  drop.style.width=rect.width+'px';
  drop.style.display='block';
  let html='';
  if(optional) html+=`<div class="cust-si-item" data-csp-click="${CSP.bind('click',function(event){pickCust(`${String((id) ?? '')}`,0)})}"><span>بدون مشتری</span></div>`;
  html+=list.slice(0,80).map(c=>`
    <div class="cust-si-item" data-csp-click="${CSP.bind('click',function(event){pickCust(`${String((id) ?? '')}`,(c.id))})}">
      <span>${esc(c.biz)}${c.owner?` <span class="muted">(${esc(c.owner)})</span>`:''}</span>
      <span class="cust-si-meta">${esc(c.phone||'')}</span>
    </div>`).join('');
  if(!html) html='<div class="cust-si-empty">مشتری یافت نشد</div>';
  drop.innerHTML=html;
}
function pickCust(id, custId){
  const h=el(id); if(h){ h.value=custId||''; h.dispatchEvent(new Event('change')); }
  const inp=el(id+'-input');
  if(inp){
    if(custId){
      const c=CACHE.customers.find(x=>x.id===+custId);
      inp.value=c?(c.biz+(c.owner?' — '+c.owner:'')):'';
    } else { inp.value=''; }
  }
  hideCustDrop(id);
}
function hideCustDrop(id){
  const drop=el(id+'-drop'); if(drop) drop.style.display='none';
}

/* ---- Datepicker popup ---- */
let DP = { input:null, y:0, m:0, sel:null };
function attachDatepickers(scope){
  (scope||document).querySelectorAll('input[data-jdate]').forEach(inp=>{
    if(inp.dataset.dpBound) return;
    inp.dataset.dpBound='1';
    inp.readOnly = true;
    inp.style.cursor='pointer';
    inp.addEventListener('click', (e)=>{ e.stopPropagation(); openDP(inp); });
    inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter'||e.key===' ') openDP(inp); });
  });
}
function openDP(inp){
  DP.input = inp;
  const today = todayJalali().split('/');
  const parts = (inp.value||'').split('/').map(x=>parseInt(x));
  if(parts.length===3 && parts[0]>=1300 && parts[0]<=1500 && parts[1]>=1 && parts[1]<=12){
    DP.y=parts[0]; DP.m=parts[1]; DP.sel=inp.value;
  } else {
    DP.y=+today[0]; DP.m=+today[1]; DP.sel=null;
  }
  DP.y=Math.max(1300,Math.min(1500,DP.y));
  DP.m=Math.max(1,Math.min(12,DP.m));
  el('dpOverlay').classList.add('open');
  renderDP();
  positionDP(inp);
}
function closeDP(){
  const dp=el('dpRoot').querySelector('.dp');
  if(dp) dp.classList.remove('open');
  el('dpOverlay').classList.remove('open');
  DP.input=null;
}
function renderDP(){
  const firstG = _j2g(DP.y, DP.m, 1);
  const fd = new Date(firstG[0], firstG[1]-1, firstG[2]);
  const startW = (fd.getDay()+1)%7; // Jalali week: Sat=0
  const dim = _jDIM(DP.m, DP.y);
  const tj = todayJalali();
  let cells='';
  for(let i=0;i<startW;i++) cells+='<button class="empty" aria-hidden="true"></button>';
  for(let d=1;d<=dim;d++){
    const val = DP.y+'/'+String(DP.m).padStart(2,'0')+'/'+String(d).padStart(2,'0');
    let cls=''; if(val===tj) cls+=' today'; if(val===DP.sel) cls+=' sel';
    cells+=`<button class="${cls.trim()}" data-csp-click="${CSP.bind('click',function(event){pickDay((d))})}" aria-label="${J_MONTHS[DP.m-1]} ${d}">${toFa(d)}</button>`;
  }
  const yearOpts = [];
  const _ty=+todayJalali().split('/')[0]||1425;
  for(let y=1300;y<=_ty;y++) yearOpts.push(`<option value="${y}" ${y===DP.y?'selected':''}>${toFa(y)}</option>`);
  el('dpRoot').innerHTML = `<div class="dp open" data-csp-click="${CSP.bind('click',function(event){event.stopPropagation()})}">
    <div class="dp-nav">
      <button data-csp-click="${CSP.bind('click',function(event){dpNav(-1)})}" title="ماه قبل">‹</button>
      <span class="dp-month-lbl">${J_MONTHS[DP.m-1]}</span>
      <select data-csp-change="${CSP.bind('change',function(event){DP.y=parseInt(this.value);renderDP()})}" title="انتخاب سال">${yearOpts.join('')}</select>
      <button data-csp-click="${CSP.bind('click',function(event){dpNav(1)})}" title="ماه بعد">›</button>
    </div>
    <div class="dp-week">${J_WEEK.map(w=>`<span>${w}</span>`).join('')}</div>
    <div class="dp-days">${cells}</div>
    <div class="dp-foot">
      <button class="today-btn" data-csp-click="${CSP.bind('click',function(event){pickToday()})}">امروز</button>
      <button class="clear-btn" data-csp-click="${CSP.bind('click',function(event){pickClear()})}">پاک</button>
    </div>
  </div>`;
  positionDP(DP.input);
}
function positionDP(inp){
  const dp=el('dpRoot').querySelector('.dp'); if(!dp) return;
  if(window.innerWidth<=480){ dp.style.cssText=''; return; }
  if(!inp){ dp.style.right='50%'; dp.style.top='50%'; return; }
  const r=inp.getBoundingClientRect();
  const dpW=224, dpH=dp.offsetHeight||260;
  let right=Math.max(8, window.innerWidth-r.right);
  if(right+dpW>window.innerWidth-8) right=Math.max(8, window.innerWidth-dpW-8);
  let top = (r.bottom+dpH+6>window.innerHeight && r.top-dpH-6>0) ? r.top-dpH-6 : r.bottom+4;
  if(top<8) top=8;
  dp.style.right=right+'px'; dp.style.top=top+'px'; dp.style.left='auto'; dp.style.bottom='auto';
}
function dpNav(dir){
  DP.m+=dir;
  if(DP.m>12){DP.m=1;DP.y=Math.min(1420,DP.y+1);}
  if(DP.m<1){DP.m=12;DP.y=Math.max(1390,DP.y-1);}
  renderDP();
}
function pickDay(d){
  const val = DP.y+'/'+String(DP.m).padStart(2,'0')+'/'+String(d).padStart(2,'0');
  if(DP.input){ DP.input.value=val; DP.input.dispatchEvent(new Event('change')); }
  closeDP();
}
function pickToday(){ if(DP.input){ DP.input.value=todayJalali(); DP.input.dispatchEvent(new Event('change')); } closeDP(); }
function pickClear(){ if(DP.input){ DP.input.value=''; DP.input.dispatchEvent(new Event('change')); } closeDP(); }
document.addEventListener('click',(e)=>{ const dp=el('dpRoot').querySelector('.dp'); if(dp && dp.classList.contains('open') && !e.target.closest('.dp') && e.target!==DP.input) closeDP(); });
// Single global handler for customer search dropdowns — avoids accumulation per modal open
document.addEventListener('click',e=>{ if(!e.target.closest('.cust-sw')) document.querySelectorAll('.cust-si-drop').forEach(d=>{d.style.display='none';}); },true);

/* ============================================================
   AUTH
============================================================ */
el('loginForm').addEventListener('submit', async (e)=>{
  e.preventDefault();
  el('loginErr').textContent='';
  const username = el('loginUser').value.trim();
  const password = el('loginPass').value;
  if(!username || !password){ el('loginErr').textContent='نام کاربری و رمز را وارد کنید'; return; }
  try{
    const devicePayload = getLoginDevicePayload();
    const attemptLogin = async (force)=>{
      const body={username,password,...devicePayload};
      if(force) body.force_logout_other=true;
      const r = await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
      const ct = r.headers.get('content-type')||'';
      let j = null, raw = '';
      try { raw = await r.text(); j = raw ? JSON.parse(raw) : null; } catch(parseErr){ j = null; }
      return {r,j};
    };
    let {r,j} = await attemptLogin(false);
    if(!j){
      el('loginErr').textContent = 'پاسخ نامعتبر از سرور ('+r.status+')';
      return;
    }
    if(r.status===409 && j.code==='DEVICE_SESSION_ACTIVE'){
      const other=j.other_device||{};
      const slotFa={mobile:'موبایل',desktop:'دسکتاپ/ویندوز',web:'وب'}[other.device_slot]||'';
      const ok=confirm((j.error||'نشست دیگری فعال است')+'\n\nدستگاه قبلی'+(slotFa?' ('+slotFa+')':'')+': '+(other.device_name||other.device_kind||'نامشخص')+'\n\nقطع نشست قبلی همین نوع دستگاه و ورود در این دستگاه؟');
      if(!ok){ el('loginErr').textContent=j.error||'ورود لغو شد'; return; }
      ({r,j} = await attemptLogin(true));
      if(!j){ el('loginErr').textContent='پاسخ نامعتبر از سرور'; return; }
    }
    if(!r.ok){
      let msg = j.error || 'خطا در ورود';
      if(APP_INFO && APP_INFO.role==='device'){
        msg += ' — اگر اتصال خراب است، لینک «قطع اتصال و اتصال مجدد» پایین همین صفحه را بزنید';
      }
      el('loginErr').textContent = msg;
      return;
    }
    if(j.twofa_required){ show2FALogin(j.pre_token); return; }
    localStorage.setItem('crm_token', j.token);
    localStorage.setItem('crm_user', JSON.stringify(j.user));
    ME = j.user;
    if(j.must_change_password){
      el('login').style.display='none'; openForcePassChange(); return;
    }
    await boot();
  }catch(err){
    el('loginErr').textContent='خطای ارتباط با سرور';
  }
});
function getLoginDevicePayload(){
  let fp=localStorage.getItem('crm_device_fp');
  if(!fp){
    fp='web-'+Math.random().toString(36).slice(2)+'-'+Date.now().toString(36);
    localStorage.setItem('crm_device_fp', fp);
  }
  let kind='web', name='مرورگر وب';
  if(APP_INFO && APP_INFO.role==='device'){
    if(APP_INFO.platform==='android' || /Android/i.test(navigator.userAgent||'')){ kind='android'; name=APP_INFO.device_name||'اپ اندروید'; }
    else { kind='desktop'; name=APP_INFO.device_name||'نسخه ویندوز'; }
  }
  return { device_fingerprint: fp, device_name: name, device_kind: kind };
}

/* تغییر اجباری رمز عبور (رمز پیش‌فرض/موقت) — مودال بدون راه فرار به‌جز خروج */
function openForcePassChange(){
  // Login screen is z-index 1000 — hide it so the force-change modal is visible
  if(el('login')) el('login').style.display='none';
  el('modalRoot').innerHTML = `<div class="overlay open">
    <div class="modal">
      <div class="modal-head"><h3>🔐 تغییر اجباری رمز عبور</h3></div>
      <div class="modal-body">
        <p class="muted" data-csp-style="${CSP.style(`font-size:13px;margin-bottom:12px;line-height:1.9`)}">
          رمز فعلی شما پیش‌فرض یا توسط مدیر تعیین شده است و به دلایل امنیتی باید همین حالا عوض شود.
          رمز جدید باید حداقل ۸ کاراکتر و شامل حرف و عدد باشد.</p>
        <div class="form-grid">
          <div class="fg full"><label>رمز فعلی</label><input id="fc-old" type="password" dir="ltr" autocomplete="current-password"></div>
          <div class="fg full"><label>رمز جدید</label><input id="fc-new" type="password" dir="ltr" autocomplete="new-password"></div>
          <div class="fg full"><label>تکرار رمز جدید</label><input id="fc-new2" type="password" dir="ltr" autocomplete="new-password"></div>
        </div>
        <div id="fc-err" class="login-err" data-csp-style="${CSP.style(`margin-top:8px`)}"></div>
      </div>
      <div class="modal-foot">
        <button class="btn" data-csp-click="${CSP.bind('click',function(event){doForcePassChange()})}">💾 ذخیره رمز جدید</button>
        <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal();logout()})}">خروج</button>
      </div>
    </div></div>`;
}
async function doForcePassChange(){
  const err=el('fc-err'); if(err) err.textContent='';
  const oldPass=el('fc-old').value, newPass=el('fc-new').value;
  if(!newPass){ if(err) err.textContent='رمز جدید را وارد کنید'; return; }
  if(newPass!==el('fc-new2').value){ if(err) err.textContent='تکرار رمز جدید یکسان نیست'; return; }
  try{ await api('POST','/auth/change-password',{oldPass,newPass}); }
  catch(e){
    if(err) err.textContent=e.message||'خطا'; return;
  }
  closeModal();
  showToast('رمز عبور با موفقیت تغییر کرد');
  if(el('app').style.display!=='block') await boot();
}

/* ---- 2FA login step (TOTP) ---- */
let _pre2faToken = null;
function show2FALogin(preToken){
  _pre2faToken = preToken;
  openModal(`
    <div class="modal-head"><h3>🔐 کد تأیید دو مرحله‌ای</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <p class="muted" data-csp-style="${CSP.style(`font-size:13px;margin-bottom:12px`)}">کد ۶ رقمی برنامه Authenticator را وارد کنید.</p>
      <div class="form-grid">
        <div class="fg full"><label>کد تأیید</label>
          <input id="tfa-code" dir="ltr" maxlength="6" inputmode="numeric" autocomplete="one-time-code"
                 data-csp-keydown="${CSP.bind('keydown',function(event){if(event.key==='Enter')verify2FALogin()})}"></div>
        <div class="fg full" id="tfa-rec-wrap" data-csp-style="${CSP.style(`display:none`)}"><label>کد بازیابی (۸ کاراکتری)</label>
          <input id="tfa-recovery" dir="ltr" maxlength="8"
                 data-csp-keydown="${CSP.bind('keydown',function(event){if(event.key==='Enter')verify2FARecovery()})}"></div>
      </div>
      <div id="tfa-err" class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:8px;color:#dc2626`)}"></div>
    </div>
    <div class="modal-foot">
      <button class="btn" id="tfa-btn" data-csp-click="${CSP.bind('click',function(event){verify2FALogin()})}">تأیید و ورود</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){toggle2FARecovery()})}">استفاده از کد بازیابی</button>
    </div>`);
  setTimeout(()=>el('tfa-code')?.focus(), 100);
}
function toggle2FARecovery(){
  const w = el('tfa-rec-wrap');
  const showing = w.style.display!=='none';
  w.style.display = showing ? 'none' : 'block';
  CSP.bindElement(el('tfa-btn'), 'click', showing ? verify2FALogin : verify2FARecovery);
  if(!showing) el('tfa-recovery').focus();
}
async function finish2FALogin(r){
  const j = await r.json();
  if(!r.ok){ el('tfa-err').textContent = j.error || 'خطا'; return; }
  closeModal();
  localStorage.setItem('crm_token', j.token);
  localStorage.setItem('crm_user', JSON.stringify(j.user));
  ME = j.user;
  if(j.remaining_codes !== undefined) showToast(`ورود با کد بازیابی — ${j.remaining_codes} کد باقی مانده`, 'warn');
  if(j.must_change_password){ el('login').style.display='none'; openForcePassChange(); return; }
  await boot();
}
async function verify2FALogin(){
  const code = el('tfa-code').value.trim();
  if(!code){ el('tfa-err').textContent='کد را وارد کنید'; return; }
  try{
    const r = await fetch('/api/auth/2fa/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pre_token:_pre2faToken, code})});
    await finish2FALogin(r);
  }catch{ el('tfa-err').textContent='خطای ارتباط با سرور'; }
}
async function verify2FARecovery(){
  const code = el('tfa-recovery').value.trim();
  if(!code){ el('tfa-err').textContent='کد بازیابی را وارد کنید'; return; }
  try{
    const r = await fetch('/api/auth/2fa/recovery-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pre_token:_pre2faToken, code})});
    await finish2FALogin(r);
  }catch{ el('tfa-err').textContent='خطای ارتباط با سرور'; }
}

function openForgotPass(){
  openModal(`
    <div class="modal-head"><h3>🔑 بازیابی رمز عبور</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <p class="muted" data-csp-style="${CSP.style(`font-size:13px;margin-bottom:12px`)}">نام کاربری و شماره موبایل ثبت‌شده در سیستم را وارد کنید. کد ۶ رقمی به موبایل شما ارسال می‌شود.</p>
      <div class="form-grid">
        <div class="fg"><label>نام کاربری</label><input id="fp-user" dir="ltr" autocomplete="username"></div>
        <div class="fg"><label>شماره موبایل</label><input id="fp-phone" dir="ltr" placeholder="0912..." inputmode="numeric"></div>
        <div class="fg" id="fp-code-wrap" data-csp-style="${CSP.style(`display:none`)}"><label>کد پیامک</label><input id="fp-code" dir="ltr" maxlength="6" inputmode="numeric"></div>
        <div class="fg" id="fp-pass-wrap" data-csp-style="${CSP.style(`display:none`)}"><label>رمز جدید (حداقل ۸ کاراکتر، حرف+عدد)</label><input id="fp-new" type="password" dir="ltr"></div>
      </div>
      <div id="fp-msg" class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:8px`)}"></div>
    </div>
    <div class="modal-foot">
      <button class="btn" id="fp-btn" data-csp-click="${CSP.bind('click',function(event){doForgotStep()})}">ارسال کد</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
    </div>`, true);
  window._fpStep = 1;
}
async function doForgotStep(){
  const msg = el('fp-msg');
  const user = el('fp-user').value.trim();
  const phone = el('fp-phone').value.trim();
  if(window._fpStep===1){
    if(!user||!phone){ if(msg) msg.textContent='نام کاربری و موبایل الزامی است'; return; }
    const r = await fetch('/api/auth/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:user,phone})});
    const j = await r.json().catch(()=>({}));
    if(!r.ok){ if(msg) msg.textContent=j.error||'خطا'; return; }
    if(msg) msg.textContent=j.message||'کد ارسال شد';
    el('fp-code-wrap').style.display=''; el('fp-pass-wrap').style.display='';
    el('fp-btn').textContent='ذخیره رمز جدید';
    window._fpStep=2;
    return;
  }
  const code = el('fp-code').value.trim();
  const newPass = el('fp-new').value;
  const r = await fetch('/api/auth/forgot-reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:user,code,newPass})});
  const j = await r.json().catch(()=>({}));
  if(!r.ok){ if(msg) msg.textContent=j.error||'خطا'; return; }
  showToast(j.message||'رمز ذخیره شد');
  closeModal();
}

function logout(){
  closeAcctDrawer();
  localStorage.removeItem('crm_token');
  localStorage.removeItem('crm_user');
  ME=null;
  el('app').style.display='none';
  el('login').style.display='flex';
}

