/* ===== Command Palette (Ctrl+K) ===== */
let _omniboxIdx = 0, _omniboxResults = [];
function initOmnibox(){
  document.addEventListener('keydown', e=>{
    if((e.ctrlKey||e.metaKey) && e.key==='k'){ e.preventDefault(); openOmnibox(); }
    if(e.key==='Escape') closeOmnibox();
  });
  const inp = el('omniboxInput');
  if(inp) inp.addEventListener('input', debounceOmnibox);
  if(inp) inp.addEventListener('keydown', omniboxKeyNav);
}
let _omniboxTimer;
function debounceOmnibox(){ clearTimeout(_omniboxTimer); _omniboxTimer=setTimeout(runOmniboxSearch,200); }
function openOmnibox(){
  el('omniboxOverlay').classList.add('open');
  const inp=el('omniboxInput'); if(inp){ inp.value=''; inp.focus(); }
  el('omniboxResults').innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:12px 16px`)}">حداقل ۲ حرف تایپ کنید...</div>`;
  _omniboxResults=[]; _omniboxIdx=0;
}
function closeOmnibox(){ el('omniboxOverlay').classList.remove('open'); }
// Normalize Persian text for tolerant matching (Arabic ي/ك, ZWNJ, punctuation, digits).
function _omniNorm(s){
  return String(s||'')
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g,'')
    .replace(/ي/g,'ی').replace(/ى/g,'ی').replace(/ك/g,'ک')
    .replace(/ۀ/g,'ه').replace(/ة/g,'ه').replace(/ؤ/g,'و').replace(/[أإآ]/g,'ا')
    .replace(/[\u064B-\u065F\u0670]/g,'')
    .replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
    .replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))
    .replace(/[()[\]{}«»""''،,.;:!?؟\-_/\\|+*=<>@#$%^&~`]/g,' ')
    .toLowerCase().replace(/\u200c/g,' ').replace(/\s+/g,' ').trim();
}
function textMatchesQuery(haystack, query){
  const q=_omniNorm(query);
  if(!q) return true;
  const hay=_omniNorm(haystack);
  const tokens=q.split(/\s+/).filter(Boolean);
  if(tokens.every(t=>hay.includes(t))) return true;
  return String(haystack||'').toLowerCase().includes(String(query||'').trim().toLowerCase());
}
function _omniScore(text,q){
  const t=_omniNorm(text), n=_omniNorm(q);
  if(!t||!n) return 0;
  if(t===n) return 100;
  if(t.startsWith(n)) return 85;
  if(t.includes(n)) return 65;
  const words=n.split(' ').filter(Boolean);
  if(words.length>1 && words.every(w=>t.includes(w))) return 50;
  return 0;
}
// Build a navigable index of EVERY section/subsection/group the current user can
// reach: main sidebar pages + all accounting sub-modules (respecting module flags).
function buildOmniboxPageIndex(){
  const idx=[];
  try{
    (navItems()||[]).forEach(it=>{ if(it&&it.id&&it.id!=='exit-acc-shell') idx.push({type:'page',label:it.label,sub:'صفحه',route:it.id}); });
  }catch(_){}
  try{
    const secs=(typeof ACC_NAV_SECTIONS!=='undefined')?ACC_NAV_SECTIONS:[];
    secs.forEach(sec=>{
      const items=sec.items||(sec.subgroups||[]).flatMap(sg=>sg.items||[]);
      items.forEach(it=>{
      if(!it||!it.id||it.id==='exit-acc-shell') return;
      if(typeof filterAccNavItem==='function' && !filterAccNavItem(it)) return;
      idx.push({type:'page',label:it.label,sub:'حسابداری › '+(sec.title||''),route:it.id});
    });});
  }catch(_){}
  return idx;
}
async function runOmniboxSearch(){
  const q=(el('omniboxInput')?.value||'').trim();
  const box=el('omniboxResults');
  if(q.length<2){ box.innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:12px 16px`)}">حداقل ۲ حرف...</div>`; return; }
  box.innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:12px 16px`)}">جستجو...</div>`;
  let server=[]; try{ server=await api('GET','/search?q='+encodeURIComponent(q))||[]; }catch(_){ server=[]; }
  // Keep entity hits (customers/products/invoices…) from the server; replace its
  // limited hard-coded page list with the full client-side navigation index.
  const entities=(server||[]).filter(r=>r.type!=='page').map(e=>({...e,score:e.score||60}));
  const pages=buildOmniboxPageIndex().map(p=>({...p,score:_omniScore(p.label,q)})).filter(p=>p.score>0);
  const merged=[...pages,...entities].sort((a,b)=>(b.score||0)-(a.score||0)).slice(0,40);
  _omniboxResults=merged;
  _omniboxIdx=0;
  renderOmniboxResults();
}
function renderOmniboxResults(){
  const box=el('omniboxResults');
  if(!_omniboxResults.length){ box.innerHTML=`<div class="empty" data-csp-style="${CSP.style(`padding:16px`)}">نتیجه‌ای یافت نشد</div>`; return; }
  box.innerHTML=_omniboxResults.map((r,i)=>`<div class="omnibox-item ${i===_omniboxIdx?'active':''}" data-csp-click="${CSP.bind('click',function(event){pickOmnibox((i))})}">
    <span>${esc(r.label)}</span><span class="sub">${esc(r.sub||r.type||'')}</span></div>`).join('');
}
function omniboxKeyNav(e){
  if(!_omniboxResults.length) return;
  if(e.key==='ArrowDown'){ e.preventDefault(); _omniboxIdx=(_omniboxIdx+1)%_omniboxResults.length; renderOmniboxResults(); }
  if(e.key==='ArrowUp'){ e.preventDefault(); _omniboxIdx=(_omniboxIdx-1+_omniboxResults.length)%_omniboxResults.length; renderOmniboxResults(); }
  if(e.key==='Enter'){ e.preventDefault(); pickOmnibox(_omniboxIdx); }
}
function pickOmnibox(i){
  const r=_omniboxResults[i]; if(!r) return;
  closeOmnibox();
  if(r.type==='customer'){ go('customers'); setTimeout(()=>{ const s=el('cSearch'); if(s){ s.value=r.label; s.dispatchEvent(new Event('input')); }},300); }
  else if(r.type==='product'){
    // P5: open accounting products with group filter + highlight search
    PRODUCT_CAT_FILTER=r.category_id?String(r.category_id):'';
    PRODUCT_ACC_SEARCH=r.label||'';
    enterAccountingShell().then(()=>{
      go('acc-products');
      setTimeout(()=>{
        const btn=document.querySelector(`#accProdCatFilter button[data-product-category-id="${CSS.escape(String(PRODUCT_CAT_FILTER))}"]`);
        if(btn) btn.scrollIntoView({block:'nearest',behavior:'smooth'});
        const row=document.querySelector(`#accProductsTbl tr[data-id="${r.id}"]`);
        if(row){ row.style.outline='2px solid var(--purple)'; row.scrollIntoView({block:'center',behavior:'smooth'}); }
      },400);
    });
  }
  else if(r.type==='person'){
    enterAccountingShell().then(()=>{
      go('acc-parties');
      setTimeout(()=>{
        const rows=[...document.querySelectorAll('table.tbl tbody tr')];
        const hit=rows.find(tr=>tr.textContent&&tr.textContent.includes(r.label));
        if(hit){ hit.style.outline='2px solid var(--purple)'; hit.scrollIntoView({block:'center',behavior:'smooth'}); }
      },400);
    });
  }
  else if(r.type==='invoice'){ go('invoices'); setTimeout(()=>openInvBuilder(r.id),300); }
  else if(r.route==='accounting'||String(r.route||'').startsWith('acc-')){ enterAccountingShell().then(()=>go(r.route)); }
  else if(r.route){ go(r.route); }
  if(r.entity_type&&r.entity_id) api('POST','/notifications/entity-viewed',{entity_type:r.entity_type,entity_id:r.entity_id}).catch(()=>{});
}

/* ===== Notifications (polling + optional SSE) ===== */
function initNotifications(){
  const bell=el('notifBell');
  if(!bell) return;
  // همه کاربران اعلان می‌بینند (حداقل برای آپدیت نرم‌افزار)
  bell.style.display='block';
  refreshPendingBadge();
  pollNotifications();
  setInterval(pollNotifications, 45000);
}
async function pollNotifications(){
  try{
    const d=await api('GET','/notifications/pending-actions')||{};
    const n=(d.notifications||[]).length;
    const badge=el('notifBadge');
    if(badge){ badge.textContent=n; badge.classList.toggle('hide',!n); }
    window._pendingActions=d.actions||[];
    window._notifications=d.notifications||[];
  }catch{}
}
function refreshPendingBadge(){ pollNotifications(); }
function toggleNotifPanel(){
  const items=(window._notifications||[]);
  openModal(`<div class="modal-head"><h3>🔔 اعلان‌ها</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">${items.length?items.map(n=>`<div class="pending-action-item" data-csp-click="${CSP.bind('click',function(event){notifClick((n.id),`${String((CSP.htmlDecode(String(esc(n.entity_type||'')))) ?? '')}`,`${String((n.entity_id||0) ?? '')}`,`${String((CSP.htmlDecode(String(esc(n.kind||'')))) ?? '')}`)})}">
      <b>${esc(n.title)}</b><div class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">${esc(n.body||'')}</div></div>`).join(''):'<div class="empty">اعلان جدیدی نیست</div>'}
    </div><div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
async function notifClick(id, entityType, entityId, kind){
  await api('POST','/notifications/'+id+'/resolve').catch(()=>{});
  closeModal(); refreshPendingBadge();
  if(kind==='app_update' || entityType==='app_update'){
    if(isDesktopApp()||detectClientPlatform()==='android') go(isAdmin()?'settings':'desktop-settings');
    else if(typeof go==='function') go(isAdmin()?'settings':'dash');
    return;
  }
  if(entityType==='invoice'&&entityId){ enterAccountingShell().then(()=>go('acc-sales-invoices')); }
  else if(entityType==='followup'&&entityId) go('followups');
  else if(kind==='invoice_approval') enterAccountingShell().then(()=>go('acc-commissions'));
  else if(entityType==='op_parameter'||entityType==='op_department'||String(kind||'').startsWith('portal_')){
    enterAccountingShell().then(()=>{
      if(ME?.role==='department_manager') go('acc-portal-my-dept');
      else go('acc-portal-units');
    });
  }
}

async function loadInitial(){
  try{
    CACHE.reminders = [];
    // Defer heavy lists: customers/products load on first page that needs them (invoice, CRM, …).
    // Previously admin/sales blocked boot on full /products + /customers payloads.
    CACHE.customers=[]; CACHE.products=[]; CACHE.allProducts=[]; CACHE.users=[];
    invalidateMasterCaches();
    if(ME.role==='admin'){
      CACHE.settings = {};
      api('GET','/settings').then(s=>{ CACHE.settings=s||{}; }).catch(()=>{});
      api('GET','/auth/users').then(u=>{ CACHE.users=u||[]; }).catch(()=>{});
    }
  }catch(e){ console.error(e); }
}
async function ensureCustomersCache(){
  if(CACHE.customers?.length) return CACHE.customers;
  CACHE.customers = await api('GET','/customers')||[];
  return CACHE.customers;
}
async function ensureProductsCache(){
  if(CACHE.allProducts?.length) return CACHE.allProducts;
  const list = await api('GET','/products')||[];
  CACHE.products = list; CACHE.allProducts = list;
  return list;
}

async function reloadCustomers(){ CACHE.customers = await api('GET','/customers')||[]; }
async function reloadProducts(q=''){ CACHE.products = await api('GET','/products'+q)||[]; }

/* ============================================================
   OFFLINE SYNC UI (device builds only)
   The desktop/mobile apps run an embedded local server (SYNC_ROLE=device)
   that exposes /api/sync/status. On the central web server that endpoint
   doesn't exist, so this whole UI stays dormant there.
============================================================ */
let SYNC_MODE = false, SYNC_STATUS = null;

async function fetchSyncStatus(){
  const token = localStorage.getItem('crm_token');
  const r = await fetch('/api/sync/status',{headers:{'Authorization':'Bearer '+token}});
  if(!r.ok) return null;
  return await r.json();
}

let _lastDataVersion = null;
async function initSyncUI(){
  try{
    SYNC_STATUS = await fetchSyncStatus();
    if(!SYNC_STATUS || SYNC_STATUS.role!=='device') return;
    SYNC_MODE = true;
    _lastDataVersion = SYNC_STATUS.data_version;
    renderSyncBadge();
    bindOnlineFirstSync();
    setInterval(async ()=>{ try{
      SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge();
      maybeRefreshAfterSync();
      // Online-First: اگر قبلاً آفلاین بودیم و الان آنلاین شدیم، فوری همگام کن
      if(SYNC_STATUS && SYNC_STATUS.online && window._syncWasOffline){
        window._syncWasOffline=false;
        bgSyncSilent();
      }
      if(SYNC_STATUS && !SYNC_STATUS.online) window._syncWasOffline=true;
    }catch(e){} }, 10000);
    if(SYNC_STATUS.pairing_broken && isAdmin()) openSyncPairModal({repair:true});
    else if(!SYNC_STATUS.paired && isAdmin()) openSyncPairModal();
    else if(SYNC_STATUS.paired && SYNC_STATUS.initial_sync_running) openSyncPairProgressModal();
    else if(SYNC_STATUS.paired && SYNC_STATUS.files_missing>0) pullProductImages(true);
  }catch(e){ /* central server — no sync UI */ }
}

/** Online-First: بمحض وصل اینترنت / برگشت به تب، همگام خودکار */
function bindOnlineFirstSync(){
  if(window._onlineFirstBound) return;
  window._onlineFirstBound = true;
  window.addEventListener('online', ()=>{
    window._syncWasOffline = false;
    try{ showToast('اینترنت وصل شد — همگام‌سازی خودکار…'); }catch(_){}
    bgSyncSilent();
    setTimeout(bgSyncSilent, 2500);
  });
  window.addEventListener('offline', ()=>{
    window._syncWasOffline = true;
    if(SYNC_STATUS){ SYNC_STATUS.online=false; SYNC_STATUS.connection_mode='offline'; }
    try{ renderSyncBadge(); }catch(_){}
  });
  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState==='visible' && SYNC_MODE) bgSyncSilent();
  });
}

async function pullProductImages(silent){
  const token = localStorage.getItem('crm_token');
  const r = await fetch('/api/sync/pull-files',{method:'POST',headers:{'Authorization':'Bearer '+token}});
  const j = await r.json().catch(()=>({}));
  if(j.ok && j.pulled>0){
    if(!silent) showToast(`${fmt(j.pulled)} فایل از سرور مرکزی دریافت شد`);
    SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge();
    maybeRefreshAfterSync();
  } else if(j.ok && j.failed>0){
    if(!silent) showToast(`${fmt(j.failed)} فایل روی سرور مرکزی یافت نشد — از پنل همگام‌سازی جزئیات را ببینید`,'error');
    SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge();
  } else if(!silent && !j.ok) showToast(j.error||'دریافت تصاویر ناموفق بود','error');
  else if(!silent && j.ok && !j.pulled) showToast('همه فایل‌های موجود همگام شدند');
}
async function skipSyncMissingFile(subdir,name){
  if(!confirm('این فایل روی سرور مرکزی موجود نیست. از لیست انتظار حذف شود؟ (تصویر شکسته می‌ماند)')) return;
  const token=localStorage.getItem('crm_token');
  const r=await fetch('/api/sync/skip-file',{method:'POST',headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({subdir,name})});
  const j=await r.json().catch(()=>({}));
  if(r.ok){ showToast('از لیست انتظار حذف شد'); SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge(); openSyncPanel(); }
  else showToast(j.error||'خطا','error');
}

// When a background sync changed local data (id remap, pulled rows/deletes),
// drop stale caches and re-render the current view — otherwise the browser
// keeps showing old ids (delete → "یافت نشد") or already-deleted rows.
function maybeRefreshAfterSync(){
  if(!SYNC_STATUS || SYNC_STATUS.data_version==null) return;
  if(_lastDataVersion===null){ _lastDataVersion=SYNC_STATUS.data_version; return; }
  if(SYNC_STATUS.data_version===_lastDataVersion) return;
  _lastDataVersion = SYNC_STATUS.data_version;
  // invalidate cached lists so the next render re-fetches from the local DB
  CACHE.customers=[]; CACHE.products=[]; CACHE.allProducts=[]; CACHE.invoices=[];
  CACHE.followups=[]; _followupsFetched=false; _invoicesFetched=false; _accRecvCache=null;
  invalidateMasterCaches();
  if(document.querySelector('.overlay.open')) return; // don't yank a modal the user is filling
  if(IN_ACC_SHELL){ if(typeof accTab!=='undefined' && accTab) loadAccTab(accTab); }
  else { reloadCustomers().then(()=>{ if(CURRENT_PAGE) go(CURRENT_PAGE); }).catch(()=>{ if(CURRENT_PAGE) go(CURRENT_PAGE); }); }
}

function isNarrowUI(){ return window.matchMedia('(max-width:900px)').matches; }
function renderSyncBadge(){
  const b = el('syncBadge'); if(!b || !SYNC_STATUS) return;
  b.style.display='inline-block';
  const s = SYNC_STATUS;
  const m = isNarrowUI();
  if(s.pairing_broken){
    b.textContent=m?'⚠️ خراب':'⚠️ اتصال خراب — لمس کنید'; b.style.background='#fee2e2'; b.style.color='#b91c1c';
  } else if(!s.paired){
    b.textContent=m?'🔗 اتصال':'🔗 اتصال به سرور مرکزی'; b.style.background='#fef3c7'; b.style.color='#b45309';
  } else if(s.initial_sync_running || (s.syncing && !s.initial_sync_done)){
    b.textContent=m?'⬇️ دریافت...':'⬇️ دریافت اولیه از مرکز...'; b.style.background='#dbeafe'; b.style.color='#1d4ed8';
  } else if(s.conflicts>0){
    b.textContent=`⚠️ ${fmt(s.conflicts)}`; b.style.background='#fee2e2'; b.style.color='#b91c1c';
  } else if(s.syncing){
    b.textContent=m?'🔄…':'🔄 در حال همگام‌سازی...'; b.style.background='#dbeafe'; b.style.color='#1d4ed8';
  } else if(!s.online){
    b.textContent=m?`📡 آفلاین`:`📡 حالت آفلاین${s.pending?` · ${fmt(s.pending)} در صف`:''}`; b.style.background='#f3f4f6'; b.style.color='#6b7280';
  } else if(s.pending>0){
    b.textContent=m?`🔄 ${fmt(s.pending)}`:`🔄 ${fmt(s.pending)} در انتظار ارسال`; b.style.background='#fef3c7'; b.style.color='#b45309';
  } else if(s.files_missing>0){
    b.textContent=m?`🖼️ ${fmt(s.files_missing)}`:`🖼️ ${fmt(s.files_missing)} تصویر در انتظار`; b.style.background='#fef3c7'; b.style.color='#b45309';
  } else {
    b.textContent=m?'● آنلاین':'🟢 آنلاین — همگام با مرکز'; b.style.background='#dcfce7'; b.style.color='#15803d';
  }
}

async function openSyncPanel(){
  SYNC_STATUS = await fetchSyncStatus() || SYNC_STATUS;
  renderSyncBadge();
  const s = SYNC_STATUS || {};
  if(s.pairing_broken){ if(isAdmin()) openSyncPairModal({repair:true}); else showToast('اتصال دستگاه خراب است — از مدیر بخواهید قطع و اتصال مجدد کند','error'); return; }
  if(!s.paired){ if(isAdmin()) openSyncPairModal(); else showToast('دستگاه هنوز متصل نشده — از مدیر سیستم بخواهید اتصال را انجام دهد','error'); return; }
  if(s.initial_sync_running || (s.syncing && !s.initial_sync_done)){ openSyncPairProgressModal(); return; }
  const token = localStorage.getItem('crm_token');
  const [pending, conflicts, missingFiles] = await Promise.all([
    fetch('/api/sync/pending',{headers:{'Authorization':'Bearer '+token}}).then(r=>r.ok?r.json():[]),
    fetch('/api/sync/conflicts',{headers:{'Authorization':'Bearer '+token}}).then(r=>r.ok?r.json():[]),
    fetch('/api/sync/missing-files',{headers:{'Authorization':'Bearer '+token}}).then(r=>r.ok?r.json():[])
  ]);
  const opLabel = o=>{
    const act = o.method==='POST'?'ثبت':o.method==='DELETE'?'حذف':'ویرایش';
    const ent = {invoices:'فاکتور',customers:'مشتری',settlements:'تسویه',sales_returns:'برگشت از فروش',purchase_invoices:'فاکتور خرید',purchase_returns:'برگشت از خرید',supplier_payments:'پرداخت تأمین‌کننده',expense_payments:'هزینه',account_transfers:'انتقال وجه',followups:'پیگیری',products:'کالا',suppliers:'تأمین‌کننده',persons:'شخص',journal_entries:'سند دستی',payroll_records:'حقوق'}[o.entity_table]||o.entity_table||o.path;
    return `${act} ${ent}`;
  };
  openModal(`
    <div class="modal-head"><h3>🔄 همگام‌سازی با سرور مرکزی</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <div data-csp-style="${CSP.style(`display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px`)}">
        <span class="tag ${s.online?'t-done':'t-cancel'}">${s.online?'🟢 متصل به مرکز':'📡 آفلاین'}</span>
        <span class="tag">${fmt(s.pending)} عملیات در صف</span>
        <span class="tag ${s.conflicts?'t-cancel':'t-done'}">${fmt(s.conflicts)} تعارض</span>
        ${s.files_missing?`<span class="tag t-pending">🖼️ ${fmt(s.files_missing)} تصویر محلی نیست</span>`:''}
        ${s.last_sync_at?`<span class="tag">آخرین همگام‌سازی: ${new Date(s.last_sync_at*1000).toLocaleTimeString('fa-IR')}</span>`:''}
      </div>
      <div data-csp-style="${CSP.style(`background:var(--bg2,#f9fafb);border:1px solid var(--border);border-radius:8px;padding:10px 12px;font-size:12px;margin-bottom:12px;line-height:1.8`)}">
        <div><b>آدرس سرور:</b> <span class="mono" dir="ltr">${esc(s.central_url||'—')}</span></div>
        <div><b>شناسه دستگاه:</b> <span class="mono" dir="ltr">${esc(String(s.device_id||'—'))}</span></div>
      </div>
      ${s.last_error?`<div data-csp-style="${CSP.style(`background:#fee2e2;color:#b91c1c;border-radius:8px;padding:8px 12px;font-size:12px;margin-bottom:12px`)}">${esc(s.last_error)}</div>`:''}
      <div data-csp-style="${CSP.style(`display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px`)}">
        <button class="btn" data-csp-click="${CSP.bind('click',function(event){syncNowUI()})}">🔄 همگام‌سازی اکنون</button>
        ${s.files_missing?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){pullProductImages()})}">🖼️ دریافت فایل‌ها</button>`:''}
        ${isAdmin()?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){editCentralUrlUI()})}">✏️ تغییر آدرس سرور</button>`:''}
        ${isAdmin()?`<button class="btn red" data-csp-click="${CSP.bind('click',function(event){resetPairingUI()})}">🔌 قطع اتصال و اتصال مجدد</button>`:''}
      </div>
      ${(missingFiles||[]).length?`
        <h4 data-csp-style="${CSP.style(`margin:10px 0 6px`)}">🖼️ فایل‌های محلی نیست (${fmt(missingFiles.length)})</h4>
        <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">اگر فایل روی سرور مرکزی وجود ندارد، می‌توانید آن را از لیست انتظار حذف کنید.</p>
        <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>نوع</th><th>نام فایل</th><th></th></tr></thead><tbody>
          ${missingFiles.map(f=>`<tr>
            <td>${esc(f.subdir)}</td><td class="mono">${esc(f.name)}</td>
            <td><button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){skipSyncMissingFile((f.subdir), (f.name))})}">✕ حذف از لیست</button></td>
          </tr>`).join('')}
        </tbody></table></div>`:''}
      ${pending.filter(p=>p.status==='pending').length?`
        <h4 data-csp-style="${CSP.style(`margin:10px 0 6px`)}">⏳ در صف ارسال</h4>
        <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><tbody>
          ${pending.filter(p=>p.status==='pending').map(o=>`<tr><td>${esc(opLabel(o))}</td><td class="mono muted">${new Date((o.created_at||0)*1000).toLocaleString('fa-IR')}</td></tr>`).join('')}
        </tbody></table></div>`:''}
      ${conflicts.length?`
        <h4 data-csp-style="${CSP.style(`margin:14px 0 6px;color:var(--red)`)}">⚠️ تعارض‌ها — نیاز به تصمیم شما</h4>
        <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:8px`)}">این عملیات‌ها روی سرور مرکزی پذیرفته نشدند (مثلاً موجودی کافی نبود). می‌توانید آن‌ها را «لغو» کنید تا اثر محلی‌شان برگردد، و در صورت نیاز عملیات را با شرایط جدید دوباره ثبت کنید.</p>
        <div class="tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr><th>عملیات</th><th>علت رد شدن</th><th></th></tr></thead><tbody>
          ${conflicts.map(c=>`<tr>
            <td>${esc(opLabel(c))}</td>
            <td data-csp-style="${CSP.style(`color:var(--red)`)}">${esc(c.reason||'-')}</td>
            <td><button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){discardSyncConflict((c.id))})}">🗑️ لغو عملیات</button></td>
          </tr>`).join('')}
        </tbody></table></div>`:''}
    </div>`, true);
}

async function syncNowUI(){
  const token = localStorage.getItem('crm_token');
  showToast('همگام‌سازی شروع شد...');
  const r = await fetch('/api/sync/now',{method:'POST',headers:{'Authorization':'Bearer '+token}});
  const j = await r.json().catch(()=>({}));
  if(j.ok){
    const extra = j.pulled ? ` · ${fmt(j.pulled)} فایل` : '';
    showToast(`همگام‌سازی انجام شد (${fmt(j.confirmed||0)} عملیات تأیید شد${extra})`);
  }
  else showToast(j.error||'همگام‌سازی ناموفق بود','error');
  SYNC_STATUS = await fetchSyncStatus(); renderSyncBadge();
  closeModal();
  // Always drop master caches after explicit sync — version may be unchanged on no-op pulls
  // but warehouses/groups might still have been updated locally from another path.
  invalidateMasterCaches();
  CACHE.customers=[]; CACHE.products=[]; CACHE.allProducts=[]; CACHE.invoices=[];
  CACHE.followups=[]; _followupsFetched=false; _invoicesFetched=false; _accRecvCache=null;
  if(SYNC_STATUS?.data_version!=null) _lastDataVersion=SYNC_STATUS.data_version;
  if(!document.querySelector('.overlay.open')){
    if(IN_ACC_SHELL && typeof accTab!=='undefined' && accTab) loadAccTab(accTab);
    else if(CURRENT_PAGE) go(CURRENT_PAGE);
  }
}

let _bgSyncTimer=null;
async function bgSyncSilent(){
  if(!SYNC_MODE) return;
  const token=localStorage.getItem('crm_token');
  try{
    const r=await fetch('/api/sync/now',{method:'POST',headers:{'Authorization':'Bearer '+token}});
    const j=await r.json().catch(()=>({}));
    if(j.ok){ SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge(); maybeRefreshAfterSync(); }
  }catch(e){}
}
function scheduleBgSync(){
  if(!SYNC_MODE) return;
  clearTimeout(_bgSyncTimer);
  // Online-First: flush outbox quickly after local mutations
  _bgSyncTimer=setTimeout(bgSyncSilent, 800);
}

async function discardSyncConflict(outboxId){
  if(!confirm('این عملیات به‌طور کامل لغو و اثر محلی آن برگردانده شود؟')) return;
  const token = localStorage.getItem('crm_token');
  const r = await fetch('/api/sync/conflicts/'+outboxId+'/discard',{method:'POST',headers:{'Authorization':'Bearer '+token}});
  const j = await r.json().catch(()=>({}));
  if(j.ok){ showToast('عملیات لغو شد'); SYNC_STATUS=await fetchSyncStatus(); renderSyncBadge(); closeModal(); openSyncPanel(); }
  else showToast(j.error||'لغو ناموفق بود','error');
}

