let _bcScanner=null, _bcOnScan=null, _bcLibLoading=null;
let _bcLastScanAt=0, _bcProcessing=false, _bcOpening=false;
let _bcWedgeState=null, _bcWedgeHandler=null, _bcWedgeBound=false;
const _bcDebounceMs=(typeof BarcodeInput!=='undefined'&&BarcodeInput.DEFAULT_DEBOUNCE_MS)||400;

function _bcNorm(raw){
  return (typeof BarcodeInput!=='undefined'&&BarcodeInput.normalizeBarcode)
    ? BarcodeInput.normalizeBarcode(raw) : String(raw||'').trim();
}
function bindBarcodeWedgeListener(){
  if(_bcWedgeBound) return;
  _bcWedgeBound=true;
  _bcWedgeState=(typeof BarcodeInput!=='undefined'&&BarcodeInput.createWedgeState)?BarcodeInput.createWedgeState():{chars:'',lastKeyAt:0};
  document.addEventListener('keydown', onBarcodeWedgeKeydown, true);
}
function onBarcodeWedgeKeydown(e){
  if(e.ctrlKey||e.altKey||e.metaKey) return;
  const tgt=e.target;
  const typing=(typeof BarcodeInput!=='undefined'&&BarcodeInput.isWedgeTypingTarget)
    ? BarcodeInput.isWedgeTypingTarget(tgt)
    : (tgt&&(tgt.tagName==='TEXTAREA'||(tgt.tagName==='INPUT'&&tgt.id!=='bcManual'&&tgt.type!=='button'&&tgt.type!=='checkbox')));
  if(typing && tgt?.id!=='bcManual') return;
  if(typeof BarcodeInput==='undefined'||!BarcodeInput.feedWedgeKey) return;
  const r=BarcodeInput.feedWedgeKey(_bcWedgeState, e.key);
  _bcWedgeState=r.state;
  if(!r.code) return;
  e.preventDefault();
  const handler=_bcOnScan||_bcWedgeHandler;
  if(handler) queueBarcodeScan(r.code, handler);
}
function loadBarcodeLib(){
  if(typeof Html5Qrcode!=='undefined') return Promise.resolve('library');
  if(typeof BarcodeDetector!=='undefined' && navigator.mediaDevices?.getUserMedia) return Promise.resolve('native');
  return Promise.resolve(false);
}
function createNativeBarcodeScanner(containerId){
  let active=false, stream=null, frame=0, detecting=false, lastDetect=0, video=null;
  return {
    async start(_camera, _config, onSuccess, onError){
      const container=el(containerId);
      if(!container) throw new Error('محل نمایش دوربین پیدا نشد');
      const detector=new BarcodeDetector();
      stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'}}});
      video=document.createElement('video');
      video.autoplay=true; video.muted=true; video.playsInline=true;
      video.setAttribute('aria-label','پیش‌نمایش دوربین بارکد');
      video.style.width='100%'; video.style.borderRadius='10px';
      video.srcObject=stream;
      container.replaceChildren(video);
      await video.play();
      active=true;
      const scan=async timestamp=>{
        if(!active) return;
        frame=requestAnimationFrame(scan);
        if(detecting || timestamp-lastDetect<160 || video.readyState<2) return;
        lastDetect=timestamp; detecting=true;
        try{
          const found=await detector.detect(video);
          const code=found?.[0]?.rawValue;
          if(code) onSuccess(code);
        }catch(error){ if(onError) onError(error); }
        finally{ detecting=false; }
      };
      frame=requestAnimationFrame(scan);
    },
    async stop(){
      active=false;
      if(frame) cancelAnimationFrame(frame);
      if(stream) stream.getTracks().forEach(track=>track.stop());
      stream=null;
      if(video) video.srcObject=null;
    },
    clear(){ el(containerId)?.replaceChildren(); }
  };
}
async function openBarcodeScanner(onScan){
  if(_bcOpening) return;
  _bcOpening=true;
  try{
    _bcOnScan=onScan;
    bindBarcodeWedgeListener();
    closeBarcodeOverlay();
    const ov=document.createElement('div');
    ov.id='bcOverlay';
    ov.className='overlay open';
    ov.style.zIndex='10050';
    ov.onclick=e=>{ if(e.target===ov) closeBarcodeOverlay(); };
    ov.innerHTML=`<div class="modal" data-csp-style="${CSP.style(`max-width:420px`)}">
      <div class="modal-head"><h3>📷 اسکن بارکد</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeBarcodeOverlay()})}">×</button></div>
      <div class="modal-body" data-csp-style="${CSP.style(`text-align:center`)}">
        <div id="bcReader" data-csp-style="${CSP.style(`max-width:340px;margin:0 auto`)}"></div>
        <p id="bcCamHint" class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:8px`)}">در حال راه‌اندازی دوربین...</p>
        <div data-csp-style="${CSP.style(`display:flex;gap:8px;margin-top:10px`)}">
          <input id="bcManual" dir="ltr" placeholder="یا کد را دستی وارد کنید" data-csp-style="${CSP.style(`flex:1;padding:9px 12px;border:1.5px solid var(--border);border-radius:9px`)}" data-csp-keydown="${CSP.bind('keydown',function(event){if(event.key==='Enter'){event.preventDefault();submitManualBarcode();}})}">
          <button class="btn sm" data-csp-click="${CSP.bind('click',function(event){submitManualBarcode()})}">جستجو</button>
        </div>
        <p class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:8px`)}">اسکنر USB (wedge) هم پشتیبانی می‌شود — کد را اسکن کنید یا در فیلد بالا Enter بزنید.</p>
      </div></div>`;
    document.body.appendChild(ov);
    const scannerMode=await loadBarcodeLib();
    const hint=el('bcCamHint');
    if(!scannerMode){
      if(hint) hint.textContent='اسکنر دوربین در دسترس نیست — کد را دستی وارد کنید یا از اسکنر USB استفاده کنید';
      return;
    }
    try{
      _bcScanner=scannerMode==='native' ? createNativeBarcodeScanner('bcReader') : new Html5Qrcode('bcReader');
      await _bcScanner.start(
        {facingMode:'environment'},
        {fps:8,qrbox:{width:250,height:150},disableFlip:true},
        code=>queueBarcodeScan(code, onScan),
        ()=>{}
      );
      if(el('bcCamHint')) el('bcCamHint').textContent='دوربین فعال — بارکد را مقابل دوربین بگیرید';
    }catch(e){
      if(el('bcCamHint')) el('bcCamHint').textContent='دوربین در دسترس نیست — کد را دستی وارد کنید یا از اسکنر USB استفاده کنید';
    }
  }finally{
    _bcOpening=false;
  }
}
async function stopBarcodeScanner(){
  if(!_bcScanner) return;
  const sc=_bcScanner;
  _bcScanner=null;
  try{ await sc.stop(); }catch(e){}
  try{ sc.clear(); }catch(e){}
}
function closeBarcodeOverlay(){
  stopBarcodeScanner();
  _bcOnScan=null;
  document.getElementById('bcOverlay')?.remove();
}
function submitManualBarcode(){
  const code=el('bcManual')?.value?.trim();
  if(code) queueBarcodeScan(code, _bcOnScan||_bcWedgeHandler);
}
function queueBarcodeScan(raw, handler){
  const code=_bcNorm(raw);
  if(!code||!handler) return;
  const now=Date.now();
  const accept=(typeof BarcodeInput!=='undefined'&&BarcodeInput.shouldAcceptScan)
    ? BarcodeInput.shouldAcceptScan(_bcLastScanAt, now, _bcDebounceMs)
    : (!_bcLastScanAt || (now-_bcLastScanAt)>=_bcDebounceMs);
  if(!accept||_bcProcessing) return;
  _bcLastScanAt=now;
  _bcProcessing=true;
  closeBarcodeOverlay();
  setTimeout(async()=>{
    try{ await handler(code); }
    catch(e){ showToast('خطا در پردازش بارکد','error'); }
    finally{ _bcProcessing=false; }
  }, 0);
}
async function scanBarcodeToCart(code){
  try{
    const p=await api('GET','/products/by-barcode/'+encodeURIComponent(code));
    if(p&&p.id){
      if(!(CACHE.products||[]).find(x=>x.id===p.id)) (CACHE.products=CACHE.products||[]).push(p);
      addToCart(p.id); showToast('افزوده شد: '+p.name);
    }
  }catch(e){ showToast('کالایی با این بارکد یافت نشد','error'); }
}

