function exportExcel(entity){
  if(!isAdmin()){ showToast('فقط مدیر سیستم می‌تواند خروجی اکسل بگیرد','error'); return; }
  downloadAuth('/'+entity+'/export/excel', entity+'.xlsx');
}
async function downloadAuth(path,filename){
  const token=localStorage.getItem('crm_token');
  try{
    const r=await fetch('/api'+path,{headers:{'Authorization':'Bearer '+token}});
    if(!r.ok){ showToast('خطا در دانلود','error'); return; }
    const blob=await r.blob();
    const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=filename; a.click();
    URL.revokeObjectURL(a.href);
  }catch(e){ showToast('خطا در دانلود','error'); }
}

