async function deleteParty(id){
  if(!confirm('این شخص غیرفعال/حذف شود؟')) return;
  try{ await api('DELETE','/parties/'+id); showToast('حذف شد'); loadAccTab('parties'); }catch(e){}
}
function exportPartiesExcel(){
  downloadAuth('/parties/export/excel','parties.csv');
}
function importPartiesExcel(){
  const inp=document.createElement('input'); inp.type='file'; inp.accept='.csv,.xlsx,.xls,text/csv';
  inp.onchange=async()=>{
    const f=inp.files[0]; if(!f) return;
    const text=await f.text();
    const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);
    if(lines.length<2){ showToast('فایل خالی است','error'); return; }
    const sep=lines[0].includes(';')?';':',';
    const headers=lines[0].split(sep).map(h=>h.replace(/^"|"$/g,'').trim());
    const rows=[];
    for(let i=1;i<lines.length;i++){
      const cols=lines[i].split(sep).map(c=>c.replace(/^"|"$/g,'').trim());
      const obj={};
      headers.forEach((h,idx)=>obj[h]=cols[idx]||'');
      rows.push({
        full_name: obj['نام']||obj['نام*']||obj.full_name||obj.name,
        phone: obj['تلفن']||obj['تلفن*']||obj.phone,
        prefix: obj['پیشوند']||obj.prefix,
        mobile: obj['موبایل']||obj.mobile,
        city: obj['شهر']||obj.city,
        party_group_name: obj['گروه']||obj.party_group_name,
        party_roles: (obj['سمت‌ها']||obj.roles||'customer').split(/[|,،]/).map(x=>x.trim()).filter(Boolean),
        email: obj['ایمیل']||obj.email,
        national_id: obj['کد ملی']||obj.national_id
      });
    }
    try{
      const r=await api('POST','/parties/import',{rows});
      showToast(`ورود انجام شد — جدید: ${r.created||0}، رد شده: ${r.skipped||0}`);
      loadAccTab('parties');
    }catch(e){}
  };
  inp.click();
}
async function saveParty(id){
  const full_name=el('pty-name').value.trim();
  const phone=el('pty-phone').value.trim();
  if(!full_name||!phone){ showToast('نام و تلفن الزامی است','error'); return; }
  const roles=[...document.querySelectorAll('.pty-role:checked')].map(x=>x.value);
  if(!roles.length){ showToast('حداقل یک سمت انتخاب کنید','error'); return; }
  const party_group_id=el('pty-party_group_id').value;
  if(!party_group_id){ showToast('انتخاب گروه اشخاص الزامی است','error'); return; }
  const data={
    person_code:el('pty-code').value.trim()||undefined,
    coa_code:el('pty-coa').value.trim(),
    prefix:el('pty-prefix').value,
    full_name, company_name:el('pty-company').value,
    phone, secondary_phone:el('pty-phone2').value, mobile:el('pty-mobile').value,
    fax:el('pty-fax').value, email:el('pty-email').value,
    national_id:el('pty-national_id').value, economic_code:el('pty-economic_code').value,
    postal_code:el('pty-postal_code').value, birth_date:el('pty-birth_date').value,
    referrer:el('pty-referrer').value, city:el('pty-city').value, province:el('pty-province').value,
    address:el('pty-address').value,
    party_group_id,
    party_roles:roles,
    credit_limit_rial:moneyVal('pty-credit'), opening_balance_rial:(()=>{const a=Math.abs(moneyVal('pty-opening')||0); const side=el('pty-open-credit')?.checked?'credit':'debit'; return side==='credit'?-a:a;})(),
    account_nature:el('pty-nature').value, notes:el('pty-note').value,
    user_id:+el('pty-expert')?.value||undefined,
    assigned_to:+el('pty-expert')?.value||undefined,
    biz:full_name
  };
  try{
    const saved=id?await api('PUT','/parties/'+id,data):await api('POST','/parties',data);
    const partyId=id||saved?.data?.id||saved?.id;
    const portalRole=el('pty-portal-role')?.value||'none';
    try{
      await api('PUT','/portal/access',{
        party_id:partyId||undefined,
        phone,
        name:full_name,
        portal_role:portalRole,
        send_sms:!!el('pty-portal-sms')?.checked
      });
    }catch(pe){
      showToast('شخص ذخیره شد ولی دسترسی پورتال: '+(pe.message||'خطا'),'error');
      closeModal(); loadAccTab('parties'); return;
    }
    closeModal(); showToast('ذخیره شد'); loadAccTab('parties');
  }catch(e){}
}

async function renderSuppliersTab(body){
  const [suppliers,balances]=await Promise.all([api('GET','/suppliers'),api('GET','/suppliers/balances/list')]);
  CACHE.suppliers=suppliers||[];
  const balMap={}; (balances||[]).forEach(b=>balMap[b.id]=b.payable);
  const total=Object.values(balMap).reduce((a,v)=>a+v,0);
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){supplierModal()})}">➕ تأمین‌کننده جدید</button></div>
    <div class="tbl-wrap"><table class="tbl" data-bulk-delete="/suppliers" data-bulk-label="حذف" data-bulk-confirm="{n} تأمین‌کننده حذف شود؟"><thead><tr>
      <th>نام</th><th>تلفن</th><th>آدرس</th><th>مانده پرداختنی (ت)</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${(suppliers||[]).map(s=>`<tr data-id="${s.id}">
      <td>${esc(s.name)}</td><td class="mono">${esc(s.phone||'-')}</td>${tdClip(s.address||'-', 200, true)}
      <td class="mono" data-csp-style="${CSP.style(`font-weight:700;color:${(balMap[s.id]||0)>0?'var(--red)':'var(--green)'}`)}">${fmt(balMap[s.id]||0)}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){supplierModal((s.id))})}">✏️</button>
        <button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){supplierPaymentModal((s.id),`${String((CSP.htmlDecode(String(esc(s.name)))) ?? '')}`)})}">💵 پرداخت</button>
        <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){showSupplierLedger((s.id),`${String((CSP.htmlDecode(String(esc(s.name)))) ?? '')}`)})}">📋 دفتر معین</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteSupplier((s.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(5)}</tbody>
    <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
      <td colspan="3">جمع کل مانده پرداختنی</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:800;color:var(--red)`)}">${fmt(total)}</td><td></td>
    </tr></tfoot></table></div>`;
}
async function supplierModal(id){
  if(canAccounting()&&!CACHE.partyGroups) CACHE.partyGroups=await api('GET','/party-groups')||[];
  const s=id?(CACHE.suppliers||[]).find(x=>x.id===id):{};
  const supPartyGroups=(CACHE.partyGroups||[]).filter(g=>g.entity_type==='supplier'||g.entity_type==='all');
  openModal(`
    <div class="modal-head"><h3>${id?'ویرایش تأمین‌کننده':'تأمین‌کننده جدید'}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>نام * ${hlp('نام شرکت یا تولیدی تأمین‌کننده کالا.')}</label><input id="sup-name" value="${esc(s.name||'')}"></div>
      <div class="fg"><label>تلفن</label><input id="sup-phone" value="${esc(s.phone||'')}"></div>
      <div class="fg full"><label>آدرس</label><input id="sup-address" value="${esc(s.address||'')}"></div>
      ${!id?`<div class="fg"><label>مانده اولیه ${moneyColLabel()} ${hlp('مبلغی که از قبل به این تأمین‌کننده بدهکاریم.')}</label><input id="sup-balance" type="text" inputmode="numeric" class="money" value="0"></div>`:''}
      <div class="fg full"><label>گروه اشخاص</label><select id="sup-party_group_id">
        <option value="">-- بدون گروه --</option>
        ${supPartyGroups.map(g=>`<option value="${g.id}" ${s.party_group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}
      </select></div>
      <div class="fg full"><label>یادداشت</label><textarea id="sup-note">${esc(s.note||'')}</textarea></div>
      ${coaCodeFieldHtml('supplier', id, s.coa_code)}
      ${supplierExtraFieldsHtml(s)}
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveSupplier((id||0))})}">💾 ذخیره</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}
async function saveSupplier(id){
  const name=el('sup-name').value.trim();
  if(!name){ showToast('نام الزامی است','error'); return; }
  const data={name,phone:el('sup-phone').value,address:el('sup-address').value,note:el('sup-note').value};
  if(el('sup-party_group_id')) data.party_group_id=+el('sup-party_group_id').value||null;
  if(usesExtendedCoa()) Object.assign(data,collectPartyExtraData('sup'));
  if(!id) data.balance=moneyVal('sup-balance');
  try{
    if(id) await api('PUT','/suppliers/'+id,data); else await api('POST','/suppliers',data);
    closeModal(); showToast('ذخیره شد'); loadAccTab('suppliers');
  }catch(e){}
}
async function deleteSupplier(id){
  if(!confirm('این تأمین‌کننده حذف شود؟')) return;
  try{ await api('DELETE','/suppliers/'+id); showToast('حذف شد'); loadAccTab('suppliers'); }catch(e){}
}
async function showSupplierLedger(id,name){
  const d=await api('GET','/purchases/ledger/'+id)||{entries:[]};
  const entries=d.entries||[];
  openModal(`
    <div class="modal-head"><h3>📋 دفتر معین تأمین‌کننده: ${esc(name)}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body" data-csp-style="${CSP.style(`padding:0`)}">
      <div class="tbl-wrap" data-csp-style="${CSP.style(`max-height:70vh`)}">
        <table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
          <th>تاریخ</th><th>شرح</th><th>بدهکار (ریال)</th><th>بستانکار (ریال)</th><th>مانده (ریال)</th>
        </tr></thead><tbody>
        ${entries.map(e=>`<tr>
          <td class="mono">${esc(e.date||'-')}</td><td>${esc(e.description||'-')}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${e.debit>0?fmt(e.debit):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${e.credit>0?fmt(e.credit):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(Math.abs(e.running_balance||0))}</td>
        </tr>`).join('')||'<tr><td colspan="5" class="empty">سابقه‌ای ثبت نشده</td></tr>'}
        </tbody></table>
      </div>
      <div data-csp-style="${CSP.style(`padding:12px 16px;border-top:1px solid var(--border);font-weight:700`)}">
        مانده نهایی: <span data-csp-style="${CSP.style(`color:${(d.balance||0)>0?'var(--red)':'var(--green)'}`)}">${fmt(Math.abs(d.balance||0))} ریال ${(d.balance||0)>0?'(بدهکار به تأمین‌کننده)':'(بستانکار)'}</span>
      </div>
    </div>
    <div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
/* ============================================================
   PERSONS (اشخاص) — general-purpose counterparties who aren't already a
   customer or supplier: employees, partners, investors, contractors,
   service providers, or any custom category the user defines.
   Ledger convention matches customer_ledger: debit = person owes us,
   credit = we owe the person.
============================================================ */
async function renderPersonsTab(body){
  const reqs=[api('GET','/persons')||[],api('GET','/persons/categories')||[]];
  if(canAccounting()) reqs.push(api('GET','/party-groups')||[]);
  const [persons,cats,partyGroups]=await Promise.all(reqs);
  if(partyGroups) CACHE.partyGroups=partyGroups;
  CACHE.persons=persons; CACHE.personCategories=cats;
  const balT=balTotals(persons);
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;display:flex;gap:8px;flex-wrap:wrap`)}">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){personModal()})}">➕ شخص جدید</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){personCategoriesModal()})}">🏷️ مدیریت دسته‌ها</button>
    </div>
    <div class="tbl-wrap tbl-scroll"><table class="tbl" data-bulk-delete="/persons" data-bulk-label="حذف" data-bulk-confirm="{n} شخص حذف شود؟"><thead><tr>
      <th>نام</th><th>دسته</th><th>تلفن</th>
      <th data-col-kind="debit">بدهکار</th><th data-col-kind="credit">بستانکار</th>
      <th>وضعیت</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${persons.map(p=>`<tr data-id="${p.id}">
      <td>${esc(p.name)}</td><td>${esc(p.category_name||'-')}</td><td class="mono">${esc(p.phone||'-')}</td>
      ${balDebitTd(p.balance)}${balCreditTd(p.balance)}
      <td>${p.active?'<span class="tag t-done">فعال</span>':'<span class="tag t-cancel">غیرفعال</span>'}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){personModal((p.id))})}">✏️</button>
        <button class="btn sm" data-csp-click="${CSP.bind('click',function(event){invitePersonUser((p.id))})}">دعوت ورود</button>
        <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){showPersonLedger((p.id),`${String((CSP.htmlDecode(String(esc(p.name)))) ?? '')}`)})}">📋 دفتر معین</button>
        <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deletePerson((p.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(7)}</tbody>
    <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
      <td colspan="3">جمع (${fmt(persons.length)} نفر)</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:800;color:#dc2626`)}">${balT.debit?fmt(balT.debit):'-'}</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:800;color:var(--green)`)}">${balT.credit?fmt(balT.credit):'-'}</td>
      <td colspan="2"></td>
    </tr></tfoot></table></div>`;
}
async function personModal(id){
  const p=id?(CACHE.persons||[]).find(x=>x.id===id):{active:1};
  const cats=CACHE.personCategories||[];
  const personPartyGroups=(CACHE.partyGroups||[]).filter(g=>g.entity_type==='person'||g.entity_type==='all');
  let positions=[];
  try{ positions=await api('GET','/person-positions')||[]; }catch(e){ positions=[]; }
  let portalAccess={ portal_role:null, has_access:false };
  try{
    if(id) portalAccess=await api('GET','/portal/access?person_id='+id)||portalAccess;
    else if(p?.phone) portalAccess=await api('GET','/portal/access?phone='+encodeURIComponent(p.phone))||portalAccess;
  }catch(_){}
  const prPortal=portalAccess.has_access?(portalAccess.portal_role||''):'';
  openModal(`
    <div class="modal-head"><h3>${id?'ویرایش شخص':'شخص جدید'}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>نام * ${hlp('نام کامل شخص (کارمند، شریک، سرمایه‌گذار، پیمانکار و ...).')}</label><input id="pr-name" value="${esc(p?.name||'')}"></div>
      <div class="fg"><label>دسته ${hlp('دسته‌بندی این شخص — از «مدیریت دسته‌ها» قابل تعریف است.')}</label><select id="pr-category">
        <option value="">-- بدون دسته --</option>
        ${cats.map(c=>`<option value="${c.id}" ${p?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}
      </select></div>
      <div class="fg"><label>سمت/جایگاه</label><select id="pr-position">
        <option value="">-- بدون سمت --</option>
        ${positions.map(pos=>`<option value="${pos.id}" ${p?.position_id===pos.id?'selected':''}>${esc(pos.name)}</option>`).join('')}
      </select></div>
      <div class="fg"><label>گروه اشخاص</label><select id="pr-party_group_id">
        <option value="">-- بدون گروه --</option>
        ${personPartyGroups.map(g=>`<option value="${g.id}" ${p?.party_group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}
      </select></div>
      <div class="fg"><label>تلفن</label><input id="pr-phone" value="${esc(p?.phone||'')}"></div>
      <div class="fg full" data-csp-style="${CSP.style(`border:1px solid var(--border);border-radius:10px;padding:12px;background:var(--purple-light,#f5f3ff)`)}">
        <label data-csp-style="${CSP.style(`font-weight:700;margin-bottom:8px;display:block`)}">🏭 دسترسی پورتال عملیاتی ${hlp('با انتخاب نقش، کاربر ورود با تلفن ساخته می‌شود. در اولین ورود تغییر رمز اجباری است. ارسال پیامک رمز موقت اختیاری است.')}</label>
        <select id="pr-portal-role">
          <option value="none" ${!prPortal?'selected':''}>بدون دسترسی پورتال</option>
          <option value="unit_manager" ${prPortal==='unit_manager'?'selected':''}>مدیر واحد عملیاتی</option>
          <option value="department_manager" ${prPortal==='department_manager'?'selected':''}>مدیر بخش (کف کارگاه)</option>
        </select>
        <label data-csp-style="${CSP.style(`display:flex;align-items:center;gap:8px;margin-top:10px;font-size:13px`)}">
          <input type="checkbox" id="pr-portal-sms" data-csp-style="${CSP.style(`width:auto`)}"> ارسال رمز موقت با پیامک
        </label>
        <div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:6px;line-height:1.6`)}">نام کاربری = تلفن · رمز اولیه همیشه تصادفی است. بدون پیامک، کاربر باید از بازیابی رمز تأییدشده یا بازنشانی توسط مدیر استفاده کند.</div>
      </div>
      <div class="fg"><label>شماره پرسنلی (فراننکو)</label><input id="pers-employee-no" value="${esc(p?.employee_no||'')}"></div>
      <div class="fg"><label>شماره کارت (فراننکو)</label><input id="pers-card-no" value="${esc(p?.card_no||'')}"></div>
      <div class="fg"><label>نرخ ساعتی (ریال)</label><input id="pers-hourly-rate" class="money" type="text" inputmode="numeric" value="${moneyInit(p?.hourly_rate)}"></div>
      <div class="fg"><label>نرخ اضافه‌کاری (ریال)</label><input id="pers-ot-rate" class="money" type="text" inputmode="numeric" value="${moneyInit(p?.overtime_rate)}"></div>
      <div class="fg"><label>کسر بیمه (٪)</label><input id="pers-insurance" type="number" min="0" step="0.1" value="${p?.insurance_percent||0}"></div>
      <div class="fg"><label>کسر مالیات (٪)</label><input id="pers-tax" type="number" min="0" step="0.1" value="${p?.tax_percent||0}"></div>
      <div class="fg full"><label>آدرس</label><input id="pr-address" value="${esc(p?.address||'')}"></div>
      ${!id?`<div class="fg"><label>مانده اولیه (ریال)</label><input id="pr-opening" type="number" min="0" value="0"></div>
      <div class="fg"><label>نوع مانده</label><div data-csp-style="${CSP.style(`display:flex;gap:12px;padding-top:8px;font-size:13px`)}">
        <label><input type="radio" name="pr-open-side" id="pr-open-debit" value="debit" data-csp-style="${CSP.style(`width:auto`)}" checked> بدهکار</label>
        <label><input type="radio" name="pr-open-side" id="pr-open-credit" value="credit" data-csp-style="${CSP.style(`width:auto`)}"> بستانکار</label>
      </div></div>`:''}
      <div class="fg"><label>سقف بستانکاری (ریال)</label><input id="pr-credit-limit" type="number" value="${p?.credit_limit||0}"></div>
      <div class="fg"><label>سقف بدهکاری (ریال)</label><input id="pr-debit-limit" type="number" value="${p?.debit_limit||0}"></div>
      ${id?`<div class="fg"><label>وضعیت</label><select id="pr-active">
        <option value="1" ${p.active?'selected':''}>فعال</option><option value="0" ${!p.active?'selected':''}>غیرفعال</option>
      </select></div>`:''}
      <div class="fg full"><label>یادداشت</label><textarea id="pr-note">${esc(p?.note||'')}</textarea></div>
      ${coaCodeFieldHtml('person', id, p?.coa_code)}
      ${personExtraFieldsHtml(p)}
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){savePerson((id||0))})}">💾 ذخیره</button>
      ${id?`<button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){invitePersonUser((id))})}">دعوت به ورود</button>`:''}
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}
async function savePerson(id){
  const name=el('pr-name').value.trim();
  if(!name){ showToast('نام الزامی است','error'); return; }
  const data={
    name, category_id:+el('pr-category').value||null, phone:el('pr-phone').value,
    address:el('pr-address').value, note:el('pr-note').value,
    credit_limit:+el('pr-credit-limit').value||0, debit_limit:+el('pr-debit-limit').value||0,
    employee_no:el('pers-employee-no')?.value||'',
    card_no:el('pers-card-no')?.value||'',
    hourly_rate:moneyVal('pers-hourly-rate'),
    overtime_rate:moneyVal('pers-ot-rate'),
    insurance_percent:+el('pers-insurance')?.value||0,
    tax_percent:+el('pers-tax')?.value||0,
    position_id:+el('pr-position')?.value||null,
    party_group_id:+el('pr-party_group_id')?.value||null
  };
  if(el('pr-party_group_id')) data.party_group_id=+el('pr-party_group_id').value||null;
  if(usesExtendedCoa()) Object.assign(data,collectPartyExtraData('pm'));
  if(!id){ const a=Math.abs(+el('pr-opening')?.value||0); data.opening_balance=el('pr-open-credit')?.checked?-a:a; }
  else data.active=+el('pr-active').value;
  try{
    const saved=id?await api('PUT','/persons/'+id,data):await api('POST','/persons',data);
    const personId=id||saved?.id||saved?.data?.id;
    const portalRole=el('pr-portal-role')?.value||'none';
    try{
      await api('PUT','/portal/access',{
        person_id:personId||undefined,
        phone:data.phone,
        name,
        portal_role:portalRole,
        send_sms:!!el('pr-portal-sms')?.checked
      });
    }catch(pe){
      showToast('شخص ذخیره شد ولی دسترسی پورتال: '+(pe.message||'خطا'),'error');
      closeModal(); loadAccTab('persons'); return;
    }
    closeModal(); showToast('ذخیره شد'); loadAccTab('persons');
  }catch(e){}
}
async function deletePerson(id){
  if(!confirm('این شخص حذف شود؟')) return;
  try{ await api('DELETE','/persons/'+id); showToast('حذف شد'); loadAccTab('persons'); }catch(e){}
}
