async function savePersonCategory(){
  const name=el('pc-name').value.trim();
  if(!name){ showToast('نام دسته الزامی است','error'); return; }
  try{
    await api('POST','/persons/categories',{name,nature:el('pc-nature').value});
    showToast('دسته اضافه شد');
    CACHE.personCategories=await api('GET','/persons/categories')||[];
    personCategoriesModal();
  }catch(e){}
}
async function deletePersonCategory(id){
  if(!confirm('این دسته حذف شود؟')) return;
  try{
    await api('DELETE','/persons/categories/'+id);
    CACHE.personCategories=await api('GET','/persons/categories')||[];
    personCategoriesModal();
  }catch(e){}
}
/* ============================================================
   SALES INVOICES LIST (فاکتورهای فروش) — accounting-shell view of every
   sales invoice; supports issuing new invoices via the same builder/modal
   used on the main Invoices page (openInvBuilder/saveInvoice).
============================================================ */
async function renderSalesInvoicesTab(body, typeLock){
  if(!CACHE.customers?.length) CACHE.customers=await api('GET','/customers')||[];
  if(!CACHE.allProducts?.length){ CACHE.allProducts=await api('GET','/products')||[]; CACHE.products=CACHE.allProducts; }
  const lock = (typeLock==='proforma' || typeLock==='final' || typeLock==='normal') ? typeLock : '';
  const qType = lock ? ('?type='+lock) : '';
  CACHE.invoices=await api('GET','/invoices'+qType)||[];
  _invoicesFetched=true;
  const filterType = lock || (el('accInvTypeFilter')?.value || '');
  const rows=CACHE.invoices.filter(i=>{
    if(i.deleted_at) return false;
    if(String(i.status||'')==='reversed') return false;
    if(lock && i.type!==lock) return false;
    if(!lock && filterType && i.type!==filterType) return false;
    if(accDateFrom && (i.date||'')<accDateFrom) return false;
    if(accDateTo && (i.date||'')>accDateTo) return false;
    return true;
  }).sort((a,b)=>(b.created_at||0)-(a.created_at||0));
  const typeLabel={proforma:'پیش‌فاکتور',normal:'فاکتور معمولی',final:'فاکتور رسمی'};
  const typeBadge=(t)=>t==='final'?'t-done':(t==='normal'?'t-active':'t-pending');
  const payLabel={cash:'نقد',cheque:'چک',credit:'نسیه',bank_transfer:'واریز بانکی'};
  const canDel=canPerm('invoices','delete')||ME.role==='admin'||ME.role==='accounting';
  const titleBtn = lock==='proforma' ? '➕ پیش‌فاکتور جدید' : (lock==='normal' ? '➕ فاکتور معمولی' : '➕ فاکتور جدید');
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;flex-wrap:wrap;gap:8px`)}">
      ${canCreateInvoice()?`<button class="btn" data-csp-click="${CSP.bind('click',function(event){openInvBuilder()})}">${titleBtn}</button>`:''}
      ${!lock?`<select id="accInvTypeFilter" data-csp-change="${CSP.bind('change',function(event){renderSalesInvoicesTab(body,'')})}">
        <option value="">همه</option>
        <option value="proforma">پیش‌فاکتور</option>
        <option value="normal">معمولی</option>
        <option value="final">رسمی</option>
      </select>`:''}
      <input id="accInvSearch" class="search" placeholder="جستجو شماره/مشتری..." data-csp-style="${CSP.style(`min-width:180px`)}" data-csp-input="${CSP.bind('input',function(event){filterAccInvTable()})}">
    </div>
    <div class="tbl-wrap"><table class="tbl" id="accSalesInvTbl" data-bulk-delete="/invoices" data-bulk-label="ابطال" data-bulk-perm="invoices" data-bulk-confirm="{n} فاکتور ابطال شود؟ سند معکوس ثبت می‌شود."><thead><tr>
      <th>شماره</th><th>سند مرجع</th><th>مشتری</th><th>نوع</th><th>تاریخ</th><th>مبلغ نهایی ${moneyColLabel()}</th><th>نوع پرداخت</th><th>فروشنده</th><th class="no-sort">عملیات</th>
    </tr></thead><tbody>${rows.map(i=>`<tr data-id="${i.id}" data-search="${esc((i.num||'')+' '+(i.cust_biz||'')+' '+(typeLabel[i.type]||i.type||''))}">
      <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${invNumCell(i.num)}</td>
      <td>${refDocCell(i.ref_doc_no,i.ref_doc_type)}</td>
      <td>${esc(i.cust_biz||'-')}</td>
      <td><span class="tag ${typeBadge(i.type)}" data-csp-style="${CSP.style(`font-size:11px`)}">${typeLabel[i.type]||i.type}</span>${i.type==='final'?` <span class="tag ${i.approved?'t-done':'t-pending'}" data-csp-style="${CSP.style(`font-size:10px`)}">${i.approved?'✓ تأیید شده':'⏳ در انتظار'}</span>`:''}</td>
      <td class="mono">${escDate(i.date)}</td><td class="mono">${fmt(i.final)}</td>
      <td>${payLabel[i.pay_type]||i.pay_type||'-'}</td>
      <td class="muted">${esc(i.seller_name||i.salesperson||'-')}</td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){printInvoice((i.id))})}" title="چاپ">🖨️</button>
        <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){openInvBuilder((i.id))})}" title="ویرایش">✏️</button>
        ${canDel?`<button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){voidInvoiceDoc((i.id),`${String((CSP.htmlDecode(String(esc(i.num||'')))) ?? '')}`)})}" title="ابطال">⛔</button>`:''}
      </td>
    </tr>`).join('')||emptyRow(9)}</tbody>
    <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
      <td colspan="5">جمع (${fmt(rows.length)} فاکتور)</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:800`)}">${fmt(rows.reduce((a,i)=>a+(i.final||0),0))}</td>
      <td colspan="3"></td>
    </tr></tfoot></table></div>`;
  if(typeof enhanceDataTable==='function'){
    const t=el('accSalesInvTbl');
    enhanceDataTable(t,{selectable:true, bulkDelete:typeof tblInferBulkDelete==='function'?tblInferBulkDelete(t):null});
  }
}
function filterAccInvTable(){
  const q=(el('accInvSearch')?.value||'').toLowerCase();
  document.querySelectorAll('#accSalesInvTbl tbody tr').forEach(tr=>{
    const hay=(tr.dataset.search||tr.textContent||'').toLowerCase();
    tr.style.display=!q||hay.includes(q)?'':'none';
  });
}
async function captureInvoicePrintImage(id){
  if(typeof html2canvas==='undefined') return null;
  try{
    const printUrl='/api/invoices/'+id+'/print';
    const resp=await fetch(printUrl,{headers:{Authorization:'Bearer '+localStorage.getItem('crm_token')}});
    if(!resp.ok) return null;
    const verifiedFrame=await CSP.createVerifiedServerFrame(resp,{width:800,height:1100});
    try{
      await new Promise(r=>setTimeout(r,300));
      const canvas=await CSP.capture(verifiedFrame.element.contentDocument.body,{backgroundColor:'#fff',scale:1.5,useCORS:true});
      return await new Promise(res=>canvas.toBlob(res,'image/png'));
    }finally{ verifiedFrame.dispose(); }
  }catch(_){ return null; }
}

async function cancelFormalInvoice(id,num){
  if(ME.role!=='admin'&&ME.role!=='accounting'){ showToast('فقط مدیر یا حسابداری می‌توانند لغو کنند','error'); return; }
  if(!confirm(`فاکتور رسمی «${num||id}» لغو شود؟\n\nهمهٔ اسناد حسابداری، موجودی، انگیزه فروش و تسویه‌های وابسته برمی‌گردند.\nاگر از پیش‌فاکتور تبدیل شده باشد، دوباره به پیش‌فاکتور فعال برمی‌گردد.`)) return;
  showToast('در حال لغو فاکتور...');
  try{
    const blob=await captureInvoicePrintImage(id);
    const fd=new FormData();
    if(blob) fd.append('image',blob,'invoice-cancel.png');
    const r=await api('POST','/accounting/invoices/'+id+'/cancel',fd,true);
    showToast(r?.title||(r?.restoredToProforma?'لغو شد — برگشت به پیش‌فاکتور':'فاکتور لغو شد'));
    _invoicesFetched=false;
    CACHE.invoices=await api('GET','/invoices')||[];
    _invoicesFetched=true;
    if(typeof refreshMsgBadge==='function') refreshMsgBadge();
    if(IN_ACC_SHELL) loadAccTab('commissions');
    else if(CURRENT_PAGE==='invoices') renderInvTable();
  }catch(e){}
}

async function voidInvoiceDoc(id,num){
  if(!canPerm('invoices','delete')&&ME.role!=='admin'&&ME.role!=='accounting'){ showToast('دسترسی ابطال ندارید','error'); return; }
  if(!confirm(`فاکتور «${num||id}» ابطال/لغو شود؟\nسند معکوس ثبت می‌شود، موجودی برمی‌گردد و تسویه‌های وابسته هم ابطال می‌شوند.\nاگر از پیش‌فاکتور تبدیل شده باشد به پیش‌فاکتور برمی‌گردد.`)) return;
  try{
    if(ME.role==='admin'||ME.role==='accounting'){
      const blob=await captureInvoicePrintImage(id);
      const fd=new FormData();
      if(blob) fd.append('image',blob,'invoice-cancel.png');
      const r=await api('POST','/accounting/invoices/'+id+'/cancel',fd,true);
      showToast(r?.title||(r?.restoredToProforma?'لغو شد — برگشت به پیش‌فاکتور':'فاکتور ابطال شد'));
      if(typeof refreshMsgBadge==='function') refreshMsgBadge();
    }else{
      const r=await api('DELETE','/invoices/'+id);
      showToast(r?.restoredToProforma?'ابطال شد — برگشت به پیش‌فاکتور':'فاکتور ابطال شد');
    }
    _invoicesFetched=false;
    CACHE.invoices=await api('GET','/invoices')||[];
    _invoicesFetched=true;
    if(IN_ACC_SHELL) loadAccTab(CURRENT_PAGE==='acc-commissions'?'commissions':'sales-invoices');
    else if(CURRENT_PAGE==='invoices') renderInvTable();
  }catch(e){}
}

/* ============================================================
   ITEM KARDEX (کاردکس کالا) — per-product stock movement ledger with a
   running balance, reconstructed from stock_logs.
============================================================ */
async function renderItemKardexTab(body){
  if(!CACHE.allProducts?.length) CACHE.allProducts=await api('GET','/products')||[];
  if(!CACHE.products?.length) CACHE.products=CACHE.allProducts;
  const products=CACHE.products||CACHE.allProducts||[];
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}">
      <select id="kardexProduct" data-csp-style="${CSP.style(`padding:8px 12px;border:1.5px solid var(--border);border-radius:8px;font-family:inherit;min-width:260px`)}" data-csp-change="${CSP.bind('change',function(event){loadItemKardex(this.value)})}">
        <option value="">-- انتخاب کالا (${fmt(products.length)}) --</option>
        ${products.map(p=>`<option value="${p.id}">${esc(p.name)} (${esc(p.code||'-')})</option>`).join('')}
      </select>
    </div>
    <div id="kardexBody">${products.length?'':'<div class="empty">کالایی یافت نشد — دسترسی گروه کالا یا کاتالوگ را بررسی کنید</div>'}</div>`;
}
async function loadItemKardex(productId){
  const box=el('kardexBody'); if(!box) return;
  if(!productId){ box.innerHTML=''; return; }
  box.innerHTML='<div class="muted">در حال بارگذاری...</div>';
  const d=await api('GET','/products/'+productId+'/kardex');
  if(!d){ box.innerHTML='<div class="empty">خطا در دریافت کاردکس</div>'; return; }
  const logs=d.logs||[];
  box.innerHTML=`
    <div class="panel">
      <div class="panel-head"><h4>${esc(d.product.name)} <span class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">(${esc(d.product.code||'-')})</span></h4>
        <span class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">موجودی فعلی: ${fmt(d.product.stock||0)} ${esc(d.product.unit||'')}
          ${d.source==='inventory_ledger'?' · دفتر کل انبار':''}
          ${d.product.average_cost_rial!=null&&window.__canSeeCost?' · میانگین: '+fmt(d.product.average_cost_rial||0)+' ریال':''}
        </span>
      </div>
      <div class="panel-body tbl-wrap">
        <table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
          <th>تاریخ</th><th>شماره/نوع</th><th>شرح</th><th>انبار</th><th>ورود</th><th>خروج</th><th>موجودی</th>
          ${window.__canSeeCost?'<th>بهای واحد</th><th>مبلغ</th>':''}
          <th>ثبت‌کننده</th>
        </tr></thead><tbody>
        ${logs.map(l=>{
          const dt=l.date||(l.created_at?new Date((l.created_at||0)*1000).toLocaleDateString('fa-IR'):'-');
          const ch=l.change!=null?l.change:((l.qty_in||0)-(l.qty_out||0));
          return `<tr data-csp-style="${CSP.style(`${l.status==='reversed'?'opacity:.55':''}`)}">
          <td class="mono">${esc(dt)}</td>
          <td class="mono" data-csp-style="${CSP.style(`font-size:11px`)}">${esc(l.tx_no||l.event_type||'-')}</td>
          <td>${esc(l.note||'-')}</td>
          <td class="muted">${esc(l.warehouse_name||'-')}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${ch>0?fmt(ch):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--red)`)}">${ch<0?fmt(-ch):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(l.running_balance||0)}</td>
          ${window.__canSeeCost?`<td class="mono">${l.unit_cost_rial!=null?fmt(l.unit_cost_rial):('-')}</td>
          <td class="mono">${l.amount_rial!=null?fmt(l.amount_rial):('-')}</td>`:''}
          <td class="muted">${esc(l.user_name||'-')}</td>
        </tr>`;
        }).join('')||'<tr><td colspan="10" class="empty">تراکنشی ثبت نشده</td></tr>'}
        </tbody></table>
      </div>
    </div>`;
}
