  const from_warehouse_id=+el('wt-from').value, to_warehouse_id=+el('wt-to').value;
  const lines=whDocLines.map(l=>({product_id:+l.product_id, qty:+l.qty||0})).filter(l=>l.product_id&&l.qty>0);
