async function saveFixedAsset(id){
  const name=el('fa-name').value.trim();
  const costRial=moneyVal('fa-cost');
  if(!name||!costRial){ showToast('نام و بهای دارایی الزامی است','error'); return; }
  const data={
    code:el('fa-code').value.trim()||undefined,
    name, category:el('fa-category').value,
    purchase_date:el('fa-date').value,
    cost_rial:Math.round(costRial),
    salvage_rial:Math.round(moneyVal('fa-salvage')),
    useful_life_months:+el('fa-life').value||60,
    coa_asset_code:el('fa-coa').value||'1201',
    location:el('fa-location').value,
    notes:el('fa-note').value
  };
  try{
    if(id) await api('PUT','/fixed-assets/'+id,data); else await api('POST','/fixed-assets',data);
    closeModal(); showToast('ذخیره شد'); loadAccTab('fixed-assets');
  }catch(e){}
}
async function runDepreciation(){
  if(!confirm('استهلاک ماه جاری برای همه دارایی‌های فعال ثبت شود؟')) return;
  const r=await api('POST','/fixed-assets/run-depreciation',{});
  showToast('استهلاک: '+fmt(r.data?.total_depreciation_rial||0)+' ریال');
  loadAccTab('fixed-assets');
}

