async function prodCloseExecute(){
  const period=el('pc-period')?.value||window._prodClosePeriod;
  if(!confirm('بستن دوره '+period+' — ادامه؟')) return;
  try{
    await api('POST','/production/close/'+encodeURIComponent(period)+'/execute',{method:'proration'});
    showToast('دوره بسته شد'); loadAccTab('production-close');
  }catch(e){ showToast(e.message||e.code||'خطا','error'); }
}
async function prodCloseReopen(){
  const period=el('pc-period')?.value||window._prodClosePeriod;
  const reason=prompt('دلیل بازگشایی دوره (الزامی):');
  if(reason==null) return;
  if(!String(reason).trim()){ showToast('دلیل الزامی است','error'); return; }
  try{
    await api('POST','/production/close/'+encodeURIComponent(period)+'/reopen',{reason:String(reason).trim()});
    showToast('دوره بازگشایی شد'); loadAccTab('production-close');
  }catch(e){ showToast(e.message||e.code||'خطا','error'); }
}

