async function renderVouchersTab(body){
  const [d,drafts]=await Promise.all([
    api('GET','/accounting/journal?ref_type=manual_voucher,account_payment,account_receipt')||{entries:[]},
    api('GET','/accounting/vouchers/drafts')||[]
  ]);
  const typeLabel={manual_voucher:'سند دستی',account_payment:'پرداخت به حساب',account_receipt:'دریافت از حساب'};
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){voucherModal()})}">➕ سند دستی جدید</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){voucherTemplatesModal()})}">📑 قالب‌های سند</button>
    </div>
    ${drafts.length?`<div class="panel" data-csp-style="${CSP.style(`margin-bottom:14px`)}">
      <div class="panel-head"><h4>📋 پیش‌نویس‌ها (${drafts.length})</h4></div>
      <div class="panel-body tbl-wrap"><table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
        <th>تاریخ</th><th>شرح</th><th>ثبت‌کننده</th><th>عملیات</th>
      </tr></thead><tbody>${drafts.map(dr=>`<tr>
        <td class="mono">${escDate(dr.date)}</td><td>${esc(dr.description||'-')}</td><td class="muted">${esc(dr.created_by_name||'-')}</td>
        <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
          <button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){postVoucherDraft((dr.id))})}">▶️ ثبت نهایی</button>
          <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteVoucherDraft((dr.id))})}">🗑️</button>
        </td>
      </tr>`).join('')}</tbody></table></div>
    </div>`:''}
    <div class="muted" data-csp-style="${CSP.style(`margin-bottom:10px;font-size:12px`)}">${d.total||0} سند (دستی / پرداخت به حساب / دریافت از حساب)</div>
    ${(d.entries||[]).map(e=>`
      <div data-csp-style="${CSP.style(`border:1px solid var(--border);border-radius:10px;margin-bottom:10px;overflow:hidden`)}">
        <div data-csp-style="${CSP.style(`background:var(--purple-light);padding:8px 12px;display:flex;justify-content:space-between;align-items:center;font-size:12px`)}">
          <span data-csp-style="${CSP.style(`font-weight:700`)}">📝 <span class="tag" data-csp-style="${CSP.style(`margin-left:6px`)}">${esc(typeLabel[e.ref_type]||e.ref_type||'سند')}</span> <span class="mono">${esc(e.entry_date||'-')}</span> — ${esc(e.description||'-')}</span>
          <span data-csp-style="${CSP.style(`display:flex;align-items:center;gap:8px`)}">
            ${journalOriginBadgeHtml(e)}
            <span class="muted">${esc(e.created_by_name||'-')}</span>
            ${e.attachment_url?`<button type="button" class="btn sm blue icon" title="مشاهده پیوست" data-csp-click="${CSP.bind('click',function(event){openPrivateFile(e.attachment_url)})}">📎</button>`:''}
            ${e.ref_type==='manual_voucher'?`<button class="btn sm ghost icon" title="افزودن/تعویض پیوست" data-csp-click="${CSP.bind('click',function(event){uploadVoucherAttachment((e.id))})}">📎</button>`:''}
            <button class="btn sm red icon" data-csp-click="${CSP.bind('click',function(event){deleteVoucher((e.id))})}" title="ابطال کامل">⛔ ابطال</button>
          </span>
        </div>
        <table class="tbl" data-csp-style="${CSP.style(`font-size:12px;margin:0`)}"><thead><tr><th>کد حساب</th><th>نام حساب</th><th>بدهکار (ریال)</th><th>بستانکار (ریال)</th></tr></thead>
        <tbody>${(e.lines||[]).map(l=>`<tr>
          <td class="mono">${esc(l.account_code)}</td><td>${esc(l.account_name)}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${(l.debit_rial||l.debit)>0?fmt(l.debit_rial||l.debit):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${(l.credit_rial||l.credit)>0?fmt(l.credit_rial||l.credit):'-'}</td>
        </tr>`).join('')}</tbody></table>
      </div>`).join('')||'<div class="empty">سندی ثبت نشده</div>'}`;
}
let voucherLines=[];
function accountOptions(selectedCode){
  return `<option value="">-- انتخاب --</option>` + (CACHE.chartOfAccounts||[]).map(a=>`<option value="${a.code}" ${a.code===selectedCode?'selected':''}>${a.code} — ${esc(a.name)}</option>`).join('');
}
// Searchable account picker for manual-voucher lines (spec item 8).
// Mirrors the product-search dropdown: a text input filters the chart of
// accounts by code or name as you type, and picking sets the line's code.
function vcCoaChildren(parent){
  const all=CACHE.chartOfAccounts||[];
  if(!parent) return all.filter(a=>!a.parent_code);
  return all.filter(a=>a.parent_code===parent);
}
function vcCoaIsLeaf(code){
  return !!(code && !vcCoaChildren(code).length);
}
function vcCoaChain(code){
  const by={};
  (CACHE.chartOfAccounts||[]).forEach(a=>{ by[a.code]=a; });
  const chain=[];
  let cur=by[code];
  while(cur){ chain.unshift(cur.code); cur=cur.parent_code?by[cur.parent_code]:null; }
  return chain;
}
function vcSyncCascadeFromCode(L){
  if(!L||!L.code) return;
  const ch=vcCoaChain(L.code);
  L.c_group=ch[0]||''; L.c_kol=ch[1]||''; L.c_moin=ch[2]||''; L.c_tafsili=ch[3]||'';
}
function acctSearchHtml(i, code){
  const L=voucherLines[i]||{};
  if(code && !L.c_group) vcSyncCascadeFromCode(L);
  const a=(CACHE.chartOfAccounts||[]).find(x=>x.code===code);
  const g=L.c_group||'', k=L.c_kol||'', m=L.c_moin||'', t=L.c_tafsili||'';
  const opt=(rows,sel)=>`<option value="">—</option>`+(rows||[]).map(x=>`<option value="${esc(x.code)}" ${x.code===sel?'selected':''}>${esc(x.code)} — ${esc(x.name)}</option>`).join('');
  return `<div>
    <div class="vc-cascade">
      <select title="گروه" data-csp-change="${CSP.bind('change',function(event){vcCascadePick((i),'g',this.value)})}">${opt(vcCoaChildren(null),g)}</select>
      <select title="کل" ${g?'':'disabled'} data-csp-change="${CSP.bind('change',function(event){vcCascadePick((i),'k',this.value)})}">${opt(g?vcCoaChildren(g):[],k)}</select>
      <select title="معین" ${k?'':'disabled'} data-csp-change="${CSP.bind('change',function(event){vcCascadePick((i),'m',this.value)})}">${opt(k?vcCoaChildren(k):[],m)}</select>
      <select title="تفصیلی" ${m?'':'disabled'} data-csp-change="${CSP.bind('change',function(event){vcCascadePick((i),'t',this.value)})}">${opt(m?vcCoaChildren(m):[],t)}</select>
    </div>
    <div data-csp-style="${CSP.style(`position:relative`)}">
      <input type="text" id="vc-acct-${i}" class="search" data-csp-style="${CSP.style(`width:100%`)}" autocomplete="off"
        placeholder="جستجوی حساب برگ: کد یا نام..." value="${a?esc(a.code+' — '+a.name):''}"
        data-csp-input="${CSP.bind('input',function(event){vcAcctShow((i),this.value)})}" data-csp-focus="${CSP.bind('focus',function(event){vcAcctShow((i),this.value)})}"
        data-csp-blur="${CSP.bind('blur',function(event){setTimeout(()=>{const d=el(`vc-acctdrop-${String((i) ?? '')}`);if(d)d.style.display='none'},200)})}">
      <div id="vc-acctdrop-${i}" class="cust-si-drop" data-csp-style="${CSP.style(`display:none;position:fixed;width:280px;max-height:220px`)}"></div>
    </div>
  </div>`;
}
function vcCascadePick(i, level, code){
  const L=voucherLines[i];
  if(!L) return;
  if(level==='g'){ L.c_group=code; L.c_kol=L.c_moin=L.c_tafsili=''; }
  else if(level==='k'){ L.c_kol=code; L.c_moin=L.c_tafsili=''; }
  else if(level==='m'){ L.c_moin=code; L.c_tafsili=''; }
  else L.c_tafsili=code;
  const pick=L.c_tafsili||L.c_moin||L.c_kol||L.c_group||'';
  L.code=vcCoaIsLeaf(pick)?pick:'';
  renderVoucherLines();
}
function vcAcctShow(i, q){
  const drop=el('vc-acctdrop-'+i), inp=el('vc-acct-'+i); if(!drop||!inp) return;
  const term=(q||'').trim().toLowerCase();
  const parentCodes=new Set((CACHE.chartOfAccounts||[]).map(a=>a.parent_code).filter(Boolean));
  let list=(CACHE.chartOfAccounts||[]).filter(a=>!parentCodes.has(a.code));
  if(!list.length && (CACHE.chartOfAccounts||[]).length){
    list=CACHE.chartOfAccounts||[];
  }
  if(!list.length){ drop.style.display='block'; drop.innerHTML='<div class="cust-si-item muted">کدینگ بارگذاری نشده</div>'; return; }
  if(term){ const words=term.split(/\s+/); list=list.filter(a=>{const hay=((a.code||'')+' '+(a.name||'')).toLowerCase(); return words.every(w=>hay.includes(w));}); }
  const rect=inp.getBoundingClientRect();
  drop.style.top=(rect.bottom+2)+'px'; drop.style.left=rect.left+'px'; drop.style.width=Math.max(rect.width,280)+'px'; drop.style.display='block'; drop.style.zIndex='9999';
  drop.innerHTML = list.slice(0,80).map(a=>`
    <div class="cust-si-item" data-csp-mousedown="${CSP.bind('mousedown',function(event){vcAcctPick((i),(a.code))})}">
      <span>${esc(a.name)}</span><span class="cust-si-meta">${esc(a.code)}${a.type?' · '+esc(ACC_TYPE_FA[a.type]||a.type):''}</span>
    </div>`).join('') || '<div class="cust-si-item muted">حساب برگ (قابل ثبت) یافت نشد — گروه/کل را انتخاب نکنید</div>';
}
function vcAcctPick(i, code){
  voucherLines[i].code=code;
  vcSyncCascadeFromCode(voucherLines[i]);
  renderVoucherLines();
}
const ACC_TYPE_FA={asset:'دارایی',liability:'بدهی',equity:'سرمایه',revenue:'درآمد',cogs:'بهای تمام‌شده',expense:'هزینه'};
function personOptions(selectedId){
  return `<option value="">-- انتخاب شخص --</option>` + (CACHE.persons||[]).map(p=>`<option value="${p.id}" ${p.id===selectedId?'selected':''}>${esc(p.name)}${p.category_name?' ('+esc(p.category_name)+')':''}</option>`).join('');
}
async function voucherModal(){
  if(!CACHE.chartOfAccounts) CACHE.chartOfAccounts=await api('GET','/accounting/chart-of-accounts')||[];
  if(!CACHE.persons) CACHE.persons=await api('GET','/persons')||[];
  if(!CACHE.costCenters) CACHE.costCenters=await api('GET','/accounting/cost-centers')||[];
  if(!CACHE.voucherTemplates) CACHE.voucherTemplates=await api('GET','/accounting/vouchers/templates')||[];
  voucherLines=[{target_type:'account',code:'',person_id:'',debit:0,credit:0,description:'',tafsili2_code:''},{target_type:'account',code:'',person_id:'',debit:0,credit:0,description:'',tafsili2_code:''}];
  openModal(`
    <div class="modal-head"><h3>📝 سند حسابداری دستی</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <div class="form-grid" data-csp-style="${CSP.style(`margin-bottom:14px`)}">
        <div class="fg"><label>تاریخ</label><input id="vc-date" data-jdate value="${todayJalali()}"></div>
        <div class="fg full"><label>شرح سند * ${hlp('توضیح کلی سند، مثال: پرداخت اجاره دفتر، ثبت هزینه تبلیغات.')}</label><input id="vc-desc"></div>
        ${CACHE.voucherTemplates.length?`<div class="fg full"><label>بارگذاری از قالب</label><select data-csp-change="${CSP.bind('change',function(event){loadVoucherTemplate(this.value)})}">
          <option value="">-- بدون قالب --</option>
          ${CACHE.voucherTemplates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}
        </select></div>`:''}
        ${(CACHE.costCenters||[]).length?`<div class="fg full"><label>مرکز هزینه (اختیاری)</label><select id="vc-cc">
          <option value="">-- بدون مرکز هزینه --</option>
          ${CACHE.costCenters.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
        </select></div>`:''}
      </div>
      <div id="vcLines"></div>
      <button class="btn sm ghost" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(event){addVoucherLine()})}">➕ ردیف جدید</button>
      <div id="vcBalance" data-csp-style="${CSP.style(`margin-top:12px;font-weight:700;font-size:13px`)}"></div>
    </div>
    <div class="modal-foot">
      <button class="btn green" data-csp-click="${CSP.bind('click',function(event){saveVoucher()})}">💾 ثبت سند</button>
      <button class="btn orange" data-csp-click="${CSP.bind('click',function(event){saveVoucherAsDraft()})}">📋 ذخیره به‌عنوان پیش‌نویس</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){saveVoucherAsTemplate()})}">📑 ذخیره به‌عنوان قالب</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button>
    </div>`,true);
  attachDatepickers(el('modalRoot'));
  renderVoucherLines();
}
function loadVoucherTemplate(id){
  if(!id) return;
  const t=(CACHE.voucherTemplates||[]).find(x=>x.id===+id);
  if(!t) return;
  voucherLines=t.lines.map(l=>({target_type:l.person_id?'person':'account',code:l.code||'',person_id:l.person_id||'',debit:l.debit||0,credit:l.credit||0,description:l.description||''}));
  if(t.description) el('vc-desc').value=t.description;
  if(t.cost_center_id && el('vc-cc')) el('vc-cc').value=t.cost_center_id;
  renderVoucherLines();
}
function renderVoucherLines(){
  el('vcLines').innerHTML = voucherLines.map((l,i)=>{
    const sideLabel = i===0 ? '① طرف اول سند' : (i===1 ? '② طرف دوم سند' : `ردیف ${i+1}`);
    return `
    <div class="panel" data-csp-style="${CSP.style(`margin-bottom:10px;border:1px solid var(--border);border-radius:10px;padding:10px`)}">
      <div data-csp-style="${CSP.style(`font-weight:700;font-size:13px;margin-bottom:8px;color:var(--purple)`)}">${sideLabel}</div>
      <div class="form-grid">
      <div class="fg"><label>نوع طرف حساب</label><select data-csp-change="${CSP.bind('change',function(event){voucherLines[(i)].target_type=this.value;renderVoucherLines()})}">
        <option value="account" ${l.target_type!=='person'?'selected':''}>حساب (کدینگ)</option>
        <option value="person" ${l.target_type==='person'?'selected':''}>شخص</option>
      </select></div>
      <div class="fg">${l.target_type==='person'
        ?`<label>شخص</label><select data-csp-change="${CSP.bind('change',function(event){voucherLines[(i)].person_id=+this.value})}">${personOptions(l.person_id)}</select>`
        :`<label>حساب</label>${acctSearchHtml(i,l.code)}`}</div>
      <div class="fg"><label>بدهکار</label><input type="text" inputmode="numeric" class="money" value="${moneyInit(l.debit)}" data-csp-input="${CSP.bind('input',function(event){voucherLines[(i)].debit=(+this.value.replace(/[^\d]/g,''))||0;voucherLines[(i)].credit=0;updateVoucherBalance()})}"></div>
      <div class="fg"><label>بستانکار</label><input type="text" inputmode="numeric" class="money" value="${moneyInit(l.credit)}" data-csp-input="${CSP.bind('input',function(event){voucherLines[(i)].credit=(+this.value.replace(/[^\d]/g,''))||0;voucherLines[(i)].debit=0;updateVoucherBalance()})}"></div>
      <div class="fg"><label>تفصیلی سطح ۲</label><input value="${esc(l.tafsili2_code||'')}" placeholder="اختیاری — پروژه/مرکز" data-csp-input="${CSP.bind('input',function(event){voucherLines[(i)].tafsili2_code=this.value})}"></div>
      <div class="fg full"><label>شرح ردیف</label><div data-csp-style="${CSP.style(`display:flex;gap:6px`)}">
        <input value="${esc(l.description||'')}" data-csp-input="${CSP.bind('input',function(event){voucherLines[(i)].description=this.value})}" data-csp-style="${CSP.style(`flex:1`)}">
        ${voucherLines.length>2?`<button class="btn sm red icon" data-csp-click="${CSP.bind('click',function(event){removeVoucherLine((i))})}">🗑️</button>`:''}
      </div></div>
      </div>
    </div>`;
  }).join('');
  updateVoucherBalance();
}
function addVoucherLine(){ voucherLines.push({target_type:'account',code:'',person_id:'',debit:0,credit:0,description:'',tafsili2_code:''}); renderVoucherLines(); }
function removeVoucherLine(i){ voucherLines.splice(i,1); renderVoucherLines(); }
function updateVoucherBalance(){
  const totD=voucherLines.reduce((a,l)=>a+(l.debit||0),0);
  const totC=voucherLines.reduce((a,l)=>a+(l.credit||0),0);
  const bal=el('vcBalance'); if(!bal) return;
  const balanced=Math.abs(totD-totC)<0.01;
  bal.innerHTML=`بدهکار: ${fmt(totD)} ریال &nbsp;|&nbsp; بستانکار: ${fmt(totC)} ریال &nbsp;—&nbsp;
    <span data-csp-style="${CSP.style(`color:${balanced?'var(--green)':'var(--red)'}`)}">${balanced?'✓ متوازن':'✗ نامتوازن — سند قابل ثبت نیست'}</span>`;
}
function buildVoucherLinesPayload(){
  return voucherLines
    .filter(l=>(l.target_type==='person'?l.person_id:l.code)&&(l.debit||l.credit))
    .map(l=>l.target_type==='person'
      ?{person_id:l.person_id,debit:l.debit,credit:l.credit,description:l.description,tafsili2_code:l.tafsili2_code||null}
      :{code:l.code,debit:l.debit,credit:l.credit,description:l.description,tafsili2_code:l.tafsili2_code||null});
}
async function saveVoucher(){
  const desc=el('vc-desc').value.trim();
  if(!desc){ showToast('شرح سند الزامی است','error'); return; }
  const totD=voucherLines.reduce((a,l)=>a+(l.debit||0),0);
  const totC=voucherLines.reduce((a,l)=>a+(l.credit||0),0);
  if(Math.abs(totD-totC)>0.01){ showToast('سند نامتوازن است — بدهکار باید با بستانکار برابر باشد','error'); return; }
  const lines=buildVoucherLinesPayload();
  if(lines.length<2){ showToast('حداقل دو ردیف معتبر لازم است','error'); return; }
  try{
    await api('POST','/accounting/vouchers',{date:el('vc-date').value,description:desc,cost_center_id:+el('vc-cc')?.value||null,lines});
    closeModal(); showToast('سند ثبت شد'); loadAccTab('vouchers');
  }catch(e){}
}
async function saveVoucherAsDraft(){
  const desc=el('vc-desc').value.trim();
  const lines=buildVoucherLinesPayload();
  if(!lines.length){ showToast('حداقل یک ردیف معتبر لازم است','error'); return; }
  try{
    await api('POST','/accounting/vouchers/drafts',{date:el('vc-date').value,description:desc,cost_center_id:+el('vc-cc')?.value||null,lines});
    closeModal(); showToast('پیش‌نویس ذخیره شد'); loadAccTab('vouchers');
  }catch(e){}
}
async function saveVoucherAsTemplate(){
  const name=prompt('نام قالب را وارد کنید:');
  if(!name) return;
  const lines=buildVoucherLinesPayload();
  if(lines.length<2){ showToast('حداقل دو ردیف معتبر لازم است','error'); return; }
  try{
    await api('POST','/accounting/vouchers/templates',{name,description:el('vc-desc').value,cost_center_id:+el('vc-cc')?.value||null,lines});
    showToast('قالب ذخیره شد');
    CACHE.voucherTemplates=await api('GET','/accounting/vouchers/templates')||[];
  }catch(e){}
}
async function postVoucherDraft(id){
  try{ await api('POST','/accounting/vouchers/drafts/'+id+'/post'); showToast('سند ثبت شد'); loadAccTab('vouchers'); }catch(e){}
}
async function deleteVoucherDraft(id){
  if(!confirm('این پیش‌نویس حذف شود؟')) return;
  try{ await api('DELETE','/accounting/vouchers/drafts/'+id); showToast('حذف شد'); loadAccTab('vouchers'); }catch(e){}
}
function voucherTemplatesModal(){
  const templates=CACHE.voucherTemplates||[];
  openModal(`
    <div class="modal-head"><h3>📑 قالب‌های سند</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body">
      <div class="tbl-wrap"><table class="tbl"><thead><tr><th>نام قالب</th><th>شرح</th><th>تعداد ردیف</th><th>عملیات</th></tr></thead>
      <tbody>${templates.map(t=>`<tr>
        <td>${esc(t.name)}</td><td class="muted">${esc(t.description||'-')}</td><td class="mono">${t.lines.length}</td>
        <td><button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteVoucherTemplate((t.id))})}">🗑️</button></td>
      </tr>`).join('')||emptyRow(4)}</tbody></table></div>
    </div>
    <div class="modal-foot"><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">بستن</button></div>`);
}
async function deleteVoucherTemplate(id){
  if(!confirm('این قالب حذف شود؟')) return;
  await api('DELETE','/accounting/vouchers/templates/'+id);
  CACHE.voucherTemplates=await api('GET','/accounting/vouchers/templates')||[];
  voucherTemplatesModal();
}
async function uploadVoucherAttachment(id){
  const inp=document.createElement('input');
  inp.type='file'; inp.accept='image/*,.pdf';
  inp.onchange=async()=>{
    if(!inp.files[0]) return;
    const fd=new FormData(); fd.append('file',inp.files[0]);
    try{
      const token=localStorage.getItem('crm_token');
      const res=await fetch('/api/accounting/vouchers/'+id+'/attachment',{method:'POST',headers:{Authorization:'Bearer '+token},body:fd});
      if(!res.ok) throw new Error();
      showToast('پیوست اضافه شد'); loadAccTab('vouchers');
    }catch(e){ showToast('خطا در آپلود پیوست','error'); }
  };
  inp.click();
}
async function deleteVoucher(id){
  if(!confirm('این سند ابطال شود؟ سند معکوس ثبت می‌شود و همه اثرهای حسابداری برمی‌گردد.')) return;
  try{ await api('DELETE','/accounting/vouchers/'+id); showToast('ابطال شد'); loadAccTab('vouchers'); }catch(e){}
}

/* ============================================================
   GENERAL LEDGER (account-level) — embedded in acc-dash; loadGeneralLedger below
============================================================ */
async function loadGeneralLedger(code){
  const box=el('glBody'); if(!box||!code) return;
  box.innerHTML='<div class="muted">در حال بارگذاری...</div>';
  const params=[];
  if(accDateFrom) params.push('from='+encodeURIComponent(accDateFrom));
  if(accDateTo) params.push('to='+encodeURIComponent(accDateTo));
  const gq=el('glSearch')?.value?.trim();
  if(gq) params.push('q='+encodeURIComponent(gq));
  const qp=params.length?'?'+params.join('&'):'';
  const dq=(accDateFrom||accDateTo)?'?'+(accDateFrom?'from='+encodeURIComponent(accDateFrom):'')+(accDateFrom&&accDateTo?'&':'')+(accDateTo?'to='+encodeURIComponent(accDateTo):''):'';
  const [d, dash]=await Promise.all([
    api('GET','/accounting/general-ledger/'+encodeURIComponent(code)+qp),
    api('GET','/accounting/account-dashboard/'+encodeURIComponent(code)+dq).catch(()=>null)
  ]);
  if(!d){ box.innerHTML='<div class="empty">خطا در بارگذاری دفتر کل</div>'; return; }
  const period=dash?.period||{};
  const last=(dash?.recent||dash?.last_entries||[]).slice(0,10);
  const opening=d.opening_rial??0;
  const periodDr=d.period_debit_rial??period.debit_rial??period.total_debit??0;
  const periodCr=d.period_credit_rial??period.credit_rial??period.total_credit??0;
  const closing=d.closing_rial??d.balance??0;
  box.innerHTML=`
    <div data-csp-style="${CSP.style(`display:flex;flex-wrap:wrap;gap:10px;margin-bottom:12px`)}">
      <div class="panel" data-csp-style="${CSP.style(`margin:0;padding:10px 14px;min-width:140px`)}"><div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">مانده ابتدا</div><div class="mono" data-csp-style="${CSP.style(`font-weight:800`)}">${fmt(Math.abs(opening))} ریال</div></div>
      <div class="panel" data-csp-style="${CSP.style(`margin:0;padding:10px 14px;min-width:140px`)}"><div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">گردش بدهکار دوره</div><div class="mono" data-csp-style="${CSP.style(`color:var(--orange);font-weight:700`)}">${fmt(periodDr)}</div></div>
      <div class="panel" data-csp-style="${CSP.style(`margin:0;padding:10px 14px;min-width:140px`)}"><div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">گردش بستانکار دوره</div><div class="mono" data-csp-style="${CSP.style(`color:var(--green);font-weight:700`)}">${fmt(periodCr)}</div></div>
      <div class="panel" data-csp-style="${CSP.style(`margin:0;padding:10px 14px;min-width:140px`)}"><div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">مانده انتها</div><div class="mono" data-csp-style="${CSP.style(`font-weight:800`)}">${fmt(Math.abs(closing))} ریال</div></div>
      <div class="panel" data-csp-style="${CSP.style(`margin:0;padding:10px 14px;flex:1`)}"><div class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">حساب</div><div data-csp-style="${CSP.style(`font-weight:700`)}">${esc((dash?.account||d.account||{}).name||code)} <span class="mono muted">${esc(code)}</span></div></div>
    </div>
    ${last.length?`<div class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:6px`)}">آخرین اسناد</div>
    <div class="tbl-wrap" data-csp-style="${CSP.style(`margin-bottom:12px;max-height:180px;overflow:auto`)}"><table class="tbl"><thead><tr><th>تاریخ</th><th>شرح</th><th>بدهکار</th><th>بستانکار</th></tr></thead>
    <tbody>${last.map(x=>`<tr><td class="mono">${esc(x.entry_date||x.date||'-')}</td><td>${esc(x.description||'-')}</td>
      <td class="mono">${fmt(x.debit_rial||x.debit||0)}</td><td class="mono">${fmt(x.credit_rial||x.credit||0)}</td></tr>`).join('')}</tbody></table></div>`:''}
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>تاریخ</th><th>شرح</th><th>مرجع</th><th>بدهکار (ریال)</th><th>بستانکار (ریال)</th><th>مانده (ریال)</th>
    </tr></thead><tbody>${(d.lines||[]).map(l=>{
      const dr=l.debit_rial||l.debit||0, cr=l.credit_rial||l.credit||0;
      return `<tr>
      <td class="mono">${esc(l.entry_date||'-')}</td>
      <td>${esc(l.description||l.entry_description||'-')}${l.tafsili2_code?` <span class="tag" data-csp-style="${CSP.style(`font-size:10px`)}">تف۲:${esc(l.tafsili2_code)}</span>`:''}</td>
      <td class="mono muted">${esc(l.ref_type||'-')}${l.ref_id?'#'+l.ref_id:''}</td>
      <td class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${dr>0?fmt(dr):'-'}</td>
      <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${cr>0?fmt(cr):'-'}</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(Math.abs(l.running_balance||0))}</td>
    </tr>`;}).join('')||'<tr><td colspan="6" class="empty">تراکنشی ثبت نشده</td></tr>'}</tbody></table></div>
    <div data-csp-style="${CSP.style(`padding:12px 0;font-weight:700`)}">مانده نهایی: ${fmt(Math.abs(closing))} ریال${d.total!=null?` <span class="muted">· ${fmt(d.total)} ردیف</span>`:''}</div>`;
}

