/* ---- Accounting sub-modules (منوی کامل) ---- */
// Open the full product create form from inside the accounting shell. Accounting
// codes (کل/معین/تفصیلی) are generated automatically on the server (allocTafsili).
async function accNewProduct(){
  if(!CACHE.products) CACHE.products=CACHE.allProducts||await api('GET','/products')||[];
  window._accProdRefresh=()=>{ CACHE.allProducts=null; if(typeof accTab!=='undefined'&&accTab==='products') loadAccTab('products'); };
  await prodModal();
}
async function accEditProduct(id){
  window._accProdRefresh=()=>{ CACHE.allProducts=null; if(typeof accTab!=='undefined'&&accTab==='products') loadAccTab('products'); };
  await prodModal(id);
}
let PRODUCT_CAT_FILTER='';
let PRODUCT_ACC_SEARCH='';
let _accProdSearchTimer=null;
function filterAccProductCat(id){ PRODUCT_CAT_FILTER=id; loadAccTab('products'); }
async function deleteAccProduct(id){
  if(!confirm('این کالا حذف شود؟ این عمل برگشت‌پذیر نیست.')) return;
  try{
    await api('DELETE','/products/'+id);
    CACHE.allProducts=null; CACHE.products=null; CACHE._prodMetaLoaded=false;
    showToast('حذف شد'); loadAccTab('products');
  }catch(e){}
}
function _accProductsRowsHtml(rows, canMut){
  return rows.map(p=>`<tr data-id="${p.id}">
    <td class="mono" data-sort="${esc(p.code||'')}">${esc(p.code||'-')}</td>
    <td>${esc(p.name)}</td>
    <td class="muted">${esc(p.category_name||p.category||'-')}</td>
    <td class="mono" data-col-kind="qty" data-sort="${Number(p.stock)||0}">${fmt(p.stock||0)}</td>
    <td class="mono" data-col-kind="avg" data-sort="${Number(p.price)||0}">${fmt(p.price||0)}</td>
    <td class="mono" data-col-kind="avg" data-sort="${Number(p.cost)||0}">${fmt(p.cost||0)}</td>
    <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
      ${canMut?`<button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){accEditProduct((p.id))})}">✏️</button>
      <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteAccProduct((p.id))})}">🗑️</button>`:'—'}
    </td>
  </tr>`).join('')||emptyRow(7);
}
async function refreshAccProductsTableOnly(){
  const catFilter=PRODUCT_CAT_FILTER;
  const search=PRODUCT_ACC_SEARCH;
  let qp=['limit=500'];
  if(catFilter) qp.push('category_id='+encodeURIComponent(catFilter));
  if(search) qp.push('search='+encodeURIComponent(search));
  const resp=await api('GET','/products?'+qp.join('&'))||{};
  const rows=listRows(resp);
  CACHE.allProducts=rows;
  const canMut=isAdmin()||ME.role==='accounting';
  const tbl=el('accProductsTbl');
  const countEl=el('accProdCount');
  if(!tbl || !tbl.tBodies[0]){ return loadAccTab('products'); }
  // Reset enhance so footer/sort rebind after tbody swap
  delete tbl.dataset.enhanced;
  const oldBar=tbl._bulkBar; if(oldBar) oldBar.remove();
  tbl.tBodies[0].innerHTML=_accProductsRowsHtml(rows, canMut);
  if(countEl) countEl.textContent=fmt(rows.length)+' کالا';
  if(typeof enhanceDataTable==='function'){
    enhanceDataTable(tbl,{
      selectable:canMut,
      footer:true,
      bulkDelete:canMut && typeof tblInferBulkDelete==='function'?tblInferBulkDelete(tbl):null
    });
  }
  const ps=el('accProdSearch');
  if(ps && document.activeElement!==ps){
    const pos=ps.value.length;
    ps.focus();
    try{ ps.setSelectionRange(pos,pos); }catch(_){}
  }
}
