async function renderFxRatesTable(){
  const tbody=el('fxRatesBody'); if(!tbody) return;
  let rows=[];
  try{ rows=await api('GET','/fx/rates?limit=200')||[]; }catch(e){ rows=[]; }
  tbody.innerHTML=rows.map(r=>`<tr>
    <td class="mono">${escDate(r.date)}</td><td class="mono">${esc(r.currency)}</td>
    <td class="mono">${fmt(r.rate_rial)}</td><td class="muted">${esc(r.source||'دستی')}</td>
  </tr>`).join('')||emptyRow(4);
}
function fxRateModal(){
  openModal(`<div class="modal-head"><h3>ثبت نرخ ارز</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg"><label>تاریخ *</label><input id="fx-date" data-jdate value="${todayJalali()}"></div>
      <div class="fg"><label>ارز *</label><select id="fx-cur">${IR_CURRENCIES.filter(c=>c.code!=='IRR'&&c.code!=='IRT').map(c=>`<option value="${c.code}">${c.code} — ${c.name}</option>`).join('')}</select></div>
      <div class="fg"><label>نرخ به ریال *</label><input id="fx-rate" type="text" inputmode="numeric" class="money"></div>
      <div class="fg"><label>منبع</label><input id="fx-src" placeholder="بانک مرکزی / دستی"></div>
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveFxRate()})}">💾 ذخیره</button><button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  attachDatepickers(el('modalRoot'));
}
async function saveFxRate(){
  const date=el('fx-date').value, currency=el('fx-cur').value, rate=+(String(el('fx-rate').value).replace(/[^\d.]/g,''))||0;
  if(!date||!rate){ showToast('تاریخ و نرخ الزامی است','error'); return; }
  try{
    await api('POST','/fx/rates',{currency,date,rate_rial:Math.round(rate),source:el('fx-src').value||'manual'});
    closeModal(); showToast('نرخ ثبت شد'); await renderFxRatesTable();
  }catch(e){}
}
