/* ============================================================
   PETTY CASH (تنخواه گردان) — a cash box flagged as custodian-managed.
   Reuses Cash Boxes' own ledger account; "replenish" is just an Account
   Transfer into the box, "expense" reuses the general Expense Payment flow
   pre-locked to this specific box.
============================================================ */
async function renderPettyCashTab(body){
  const [boxes, balRows]=await Promise.all([
    api('GET','/cash-boxes')||[],
    api('GET','/cash-boxes/balances')||[]
  ]);
  CACHE.cashBoxes=boxes;
  if(!CACHE.banks) CACHE.banks=await api('GET','/banks')||[];
  const petty=boxes.filter(b=>b.is_petty_cash);
  const balMap={};
  (balRows||[]).forEach(b=>{ balMap[b.id]=b.balance; });
  if(!petty.length){
    body.innerHTML=`<div class="empty">هنوز صندوق تنخواه‌گردانی تعریف نشده — از صفحه «صندوق‌های نقدی»، یک صندوق بسازید و گزینه «تنخواه‌گردان» را فعال کنید.</div>`;
    return;
  }
  const pettyBalances=petty.map(b=>balMap[b.id]||0);
  body.innerHTML=`<div class="tbl-wrap"><table class="tbl"><thead><tr>
    <th>نام صندوق</th><th>مسئول</th><th>موجودی فعلی (ت)</th><th>عملیات</th>
  </tr></thead><tbody>${petty.map((b,i)=>`<tr>
    <td>${esc(b.name)}</td><td>${esc(b.custodian||'-')}</td>
    <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(pettyBalances[i]||0)}</td>
    <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
      <button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){pettyCashExpenseModal((b.id),`${String((CSP.htmlDecode(String(esc(b.name)))) ?? '')}`)})}">🧾 ثبت هزینه</button>
      <button class="btn sm orange" data-csp-click="${CSP.bind('click',function(event){pettyCashReplenishModal((b.id),`${String((CSP.htmlDecode(String(esc(b.name)))) ?? '')}`)})}">➕ افزایش تنخواه</button>
      <button class="btn sm blue" data-csp-click="${CSP.bind('click',function(event){viewCashBoxLedger((b.id))})}">📒 دفتر کل</button>
    </td>
  </tr>`).join('')}</tbody></table></div>`;
}
async function pettyCashExpenseModal(boxId,boxName){
  if(!CACHE.banks) CACHE.banks=await api('GET','/banks')||[];
  if(!CACHE.checkCategories) CACHE.checkCategories=await api('GET','/check-categories')||[];
  expensePaymentModal();
  // Lock the payment type/cash-box to this fund and clear/disable the bank
  // select — a petty cash expense is always a cash payment from this specific
  // fund (resolveCashAccount would otherwise prefer a selected bank over the
  // cash box).
  setTimeout(()=>{
    const pt=el('ex-paytype'); if(pt){ pt.value='cash'; pt.disabled=true; }
    const bank=el('ex-bank'); if(bank){ bank.value=''; bank.disabled=true; }
    const cb=el('ex-cashbox'); if(cb){ cb.value=boxId; cb.disabled=true; }
    const head=document.querySelector('#modalRoot .modal-head h3'); if(head) head.textContent='🧾 ثبت هزینه از تنخواه: '+boxName;
  },50);
}
function pettyCashReplenishModal(boxId,boxName){
  transferModal();
  setTimeout(()=>{
    el('tr-to-type').value='cash'; updateTransferSideOptions('to');
    el('tr-to-id').value=boxId;
    const fromType=el('tr-from-type'); if(fromType) fromType.value='bank';
    updateTransferSideOptions('from');
    const head=document.querySelector('#modalRoot .modal-head h3'); if(head) head.textContent='➕ افزایش تنخواه: '+boxName;
  },50);
}

/* ============================================================
   TRUST / GUARANTEE CHECKS (چک‌های امانی) — held as collateral, not yet
   posted to accounting. Actual cash movement (if realized) is recorded
   separately through Receipt/Payment Operations.
============================================================ */
const TC_STATUS_LABEL={held:'نزد ما / نزد طرف مقابل',returned:'مسترد شده',realized:'وصول/پرداخت شده',bounced:'برگشت خورده'};
const TC_STATUS_COLOR={held:'var(--orange)',returned:'var(--muted)',realized:'var(--green)',bounced:'var(--red)'};
async function renderTrustChecksTab(body){
  const dirFilter=el('tcDirFilter')?.value||'';
  const statusFilter=el('tcStatusFilter')?.value||'';
  const qp=[]; if(dirFilter) qp.push('direction='+dirFilter); if(statusFilter) qp.push('status='+statusFilter);
  const rows=await api('GET','/trust-checks'+(qp.length?'?'+qp.join('&'):''))||[];
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px;flex-wrap:wrap;gap:8px`)}">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){trustCheckModal()})}">➕ ثبت چک امانی</button>
      <select id="tcDirFilter" data-csp-change="${CSP.bind('change',function(event){loadAccTab('trust-checks')})}" data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;font-size:13px`)}">
        <option value="">همه جهت‌ها</option>
        <option value="in" ${dirFilter==='in'?'selected':''}>دریافتی</option>
        <option value="out" ${dirFilter==='out'?'selected':''}>پرداختی</option>
      </select>
      <select id="tcStatusFilter" data-csp-change="${CSP.bind('change',function(event){loadAccTab('trust-checks')})}" data-csp-style="${CSP.style(`padding:7px 10px;border:1.5px solid var(--border);border-radius:8px;font-size:13px`)}">
        <option value="">همه وضعیت‌ها</option>
        ${Object.entries(TC_STATUS_LABEL).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}
      </select>
    </div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>جهت</th><th>طرف حساب</th><th>بانک</th><th>شماره صیادی</th><th>مبلغ (ریال)</th><th>سررسید</th><th>وضعیت</th><th>عملیات</th>
    </tr></thead><tbody>${rows.map(r=>`<tr>
      <td>${r.direction==='in'?'⬇️ دریافتی':'⬆️ پرداختی'}</td>
      <td>${esc(r.party_name)}</td><td>${esc(r.bank_name||'-')}</td><td class="mono">${esc(r.sayadi||'-')}</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(r.amount)}</td><td class="mono">${escDate(r.due_date)}</td>
      <td><span class="tag" data-csp-style="${CSP.style(`background:${TC_STATUS_COLOR[r.status]};color:#fff`)}">${TC_STATUS_LABEL[r.status]||r.status}</span></td>
      <td data-csp-style="${CSP.style(`white-space:nowrap`)}">
        ${r.status==='held'?`
          <button class="btn sm green" data-csp-click="${CSP.bind('click',function(event){setTrustCheckStatus((r.id),'realized')})}">✅ وصول/پرداخت شد</button>
          <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){setTrustCheckStatus((r.id),'returned')})}">↩️ استرداد</button>
          <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){setTrustCheckStatus((r.id),'bounced')})}">❌ برگشت خورد</button>`:''}
        <button class="btn sm red icon" data-csp-click="${CSP.bind('click',function(event){deleteTrustCheck((r.id))})}">🗑️</button>
      </td>
    </tr>`).join('')||emptyRow(8)}</tbody></table></div>
    <div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:8px`)}">چک‌های امانی صرفاً برای پیگیری امانت هستند و در سند حسابداری ثبت نمی‌شوند — در صورت وصول/پرداخت واقعی، آن را جداگانه از «عملیات دریافت» یا «عملیات پرداخت» ثبت کنید.</div>`;
}
function trustCheckModal(){
  openModal(`
    <div class="modal-head"><h3>🔖 ثبت چک امانی</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg"><label>جهت چک *</label><select id="tc-direction">
        <option value="in">دریافتی (نزد ما امانت است)</option>
        <option value="out">پرداختی (نزد طرف مقابل امانت است)</option>
      </select></div>
      <div class="fg"><label>طرف حساب * ${hlp('نام مشتری، تأمین‌کننده یا شخصی که این چک را داده/گرفته است.')}</label><input id="tc-party"></div>
      <div class="fg"><label>تلفن طرف حساب</label><input id="tc-phone"></div>
      <div class="fg"><label>مبلغ (ریال) *</label><input id="tc-amount" type="number" min="1"></div>
      <div class="fg"><label>نام بانک</label><input id="tc-bank"></div>
      <div class="fg"><label>شماره صیادی</label><input id="tc-sayadi"></div>
      <div class="fg"><label>شماره چک</label><input id="tc-number"></div>
      <div class="fg"><label>شماره حساب</label><input id="tc-account"></div>
      <div class="fg"><label>نام صادرکننده</label><input id="tc-owner"></div>
      <div class="fg"><label>تاریخ سررسید *</label><input id="tc-due" data-jdate></div>
      <div class="fg full"><label>یادداشت</label><textarea id="tc-note"></textarea></div>
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveTrustCheck()})}">💾 ذخیره</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  attachDatepickers(el('modalRoot'));
}
async function saveTrustCheck(){
  const party_name=el('tc-party').value.trim();
  const amount=+el('tc-amount').value;
  if(!party_name){ showToast('نام طرف حساب الزامی است','error'); return; }
  if(!amount||amount<=0){ showToast('مبلغ معتبر وارد کنید','error'); return; }
  try{
    await api('POST','/trust-checks',{
      direction:el('tc-direction').value, party_name, party_phone:el('tc-phone').value,
      bank_name:el('tc-bank').value, sayadi:el('tc-sayadi').value, cheque_number:el('tc-number').value,
      account_number:el('tc-account').value, amount, owner_name:el('tc-owner').value,
      due_date:el('tc-due').value, note:el('tc-note').value
    });
    closeModal(); showToast('چک امانی ثبت شد'); loadAccTab('trust-checks');
  }catch(e){}
}
async function setTrustCheckStatus(id,status){
  const labels={realized:'وصول/پرداخت شد',returned:'مسترد شود',bounced:'برگشت خورد'};
  if(!confirm(`وضعیت این چک به «${labels[status]||status}» تغییر کند؟`)) return;
  try{ await api('PATCH','/trust-checks/'+id+'/status',{status}); showToast('وضعیت به‌روزرسانی شد'); loadAccTab('trust-checks'); }catch(e){}
}
async function deleteTrustCheck(id){
  if(!confirm('این چک امانی حذف شود؟')) return;
  try{ await api('DELETE','/trust-checks/'+id); showToast('حذف شد'); loadAccTab('trust-checks'); }catch(e){}
}

/* ============================================================
   ACCOUNT TRANSFERS (انتقال وجه) — internal movement between the company's
   own cash/bank accounts: cash<->cash, cash<->bank, bank<->bank.
============================================================ */
async function renderTransfersTab(body,dq){
  const [rows,boxes,banks]=await Promise.all([
    api('GET','/transfers'+dq)||[], api('GET','/cash-boxes')||[], api('GET','/banks')||[]
  ]);
  CACHE.cashBoxes=boxes; CACHE.banks=banks;
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){transferModal()})}">➕ انتقال جدید</button></div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr>
      <th>تاریخ</th><th>از</th><th>به</th><th>مبلغ (ریال)</th><th>شرح</th><th>ثبت‌کننده</th><th>عملیات</th>
    </tr></thead><tbody>${rows.map(t=>`<tr>
      <td class="mono">${escDate(t.date)}</td>
      <td>${esc(t.from_name)}</td>
      <td>${esc(t.to_name)}</td>
      <td class="mono" data-csp-style="${CSP.style(`font-weight:700`)}">${fmt(t.amount)}</td>
      <td>${esc(t.note||'-')}</td>
      <td class="muted">${esc(t.recorder||'-')}</td>
      <td><button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteTransfer((t.id))})}">🗑️</button></td>
    </tr>`).join('')||emptyRow(7)}</tbody></table></div>`;
}
function transferSideOptions(type,selectedId){
  const list = type==='bank' ? (CACHE.banks||[]) : (CACHE.cashBoxes||[]);
  return `<option value="">-- عمومی (بدون انتخاب مشخص) --</option>` +
    list.map(x=>`<option value="${x.id}" ${selectedId==x.id?'selected':''}>${esc(x.name)}</option>`).join('');
}
function transferModal(preferTo){
  openModal(`
    <div class="modal-head"><h3>انتقال بین بانک و صندوق</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg"><label>تاریخ</label><input id="tr-date" value="${todayJalali()}"></div>
      <div class="fg"><label>مبلغ (ریال) *</label><input id="tr-amount" type="text" inputmode="numeric" class="money" min="1"></div>
      <div class="fg"><label>از (مبدأ) *</label><select id="tr-from-type" data-csp-change="${CSP.bind('change',function(event){updateTransferSideOptions('from')})}"><option value="cash">صندوق نقدی</option><option value="bank">بانک</option></select></div>
      <div class="fg"><label>حساب مبدأ</label><select id="tr-from-id">${transferSideOptions('cash')}</select></div>
      <div class="fg"><label>به (مقصد) *</label><select id="tr-to-type" data-csp-change="${CSP.bind('change',function(event){updateTransferSideOptions('to')})}"><option value="cash">صندوق نقدی</option><option value="bank" selected>بانک</option></select></div>
      <div class="fg"><label>حساب مقصد</label><select id="tr-to-id">${transferSideOptions('bank')}</select></div>
      <div class="fg full"><label>شرح</label><input id="tr-note"></div>
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveTransfer()})}">💾 ثبت انتقال</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  el('tr-to-type').value=(preferTo==='cash'?'cash':'bank');
  updateTransferSideOptions('to');
}
function updateTransferSideOptions(side){
  const type=el('tr-'+side+'-type').value;
  el('tr-'+side+'-id').innerHTML=transferSideOptions(type);
}
async function saveTransfer(){
  const amount=moneyVal('tr-amount');
  if(!amount){ showToast('مبلغ الزامی است','error'); return; }
  const data={
    date:el('tr-date').value, amount,
    from_type:el('tr-from-type').value, from_id:el('tr-from-id').value||null,
    to_type:el('tr-to-type').value, to_id:el('tr-to-id').value||null,
    note:el('tr-note').value
  };
  try{
    await api('POST','/transfers',data);
    closeModal(); showToast('انتقال ثبت شد'); loadAccTab('transfers');
  }catch(e){}
}
async function deleteTransfer(id){
  if(!confirm('این انتقال حذف شود؟ سند حسابداری آن نیز ابطال می‌شود.')) return;
  try{ await api('DELETE','/transfers/'+id); showToast('حذف شد'); loadAccTab('transfers'); }catch(e){}
}

async function renderExpenseCategoriesTab(body){
  const rows=await api('GET','/expenses/categories')||[];
  CACHE.expenseCategories=rows;
  const byParent={};
  rows.forEach(r=>{ const k=r.parent_id||0; if(!byParent[k]) byParent[k]=[]; byParent[k].push(r); });
  function renderTree(parentId, depth){
    return (byParent[parentId]||[]).map(r=>{
      const pad='— '.repeat(depth);
      const coa=r.coa_code||r.account_code||'-';
      return `<tr>
        <td class="mono">${esc(r.code||'-')}</td>
        <td>${pad}${esc(r.name)} <span class="muted" data-csp-style="${CSP.style(`font-size:11px`)}">L${r.level||1}</span></td>
        <td class="mono">${esc(coa)}</td>
        <td>${r.parent_id?(CACHE.expenseCategories||[]).find(x=>x.id===r.parent_id)?.name||'-': '—'}</td>
        <td><button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){expenseCategoryModal((r.id))})}">✏️</button>
            <button class="btn sm red" data-csp-click="${CSP.bind('click',function(event){deleteExpenseCategory((r.id))})}">🗑️</button></td>
      </tr>`+renderTree(r.id, depth+1);
    }).join('');
  }
  body.innerHTML=`
    <div class="toolbar" data-csp-style="${CSP.style(`margin-bottom:12px`)}"><button class="btn" data-csp-click="${CSP.bind('click',function(event){expenseCategoryModal()})}">➕ دسته جدید</button></div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr><th>کد</th><th>نام</th><th>حساب (کل/معین)</th><th>والد</th><th>عملیات</th></tr></thead>
    <tbody>${renderTree(0,0)||emptyRow(5)}</tbody></table></div>`;
}
async function expenseCategoryModal(id){
  const rows=CACHE.expenseCategories||[];
  const row=id?rows.find(x=>x.id===id)||{}:{};
  openModal(`
    <div class="modal-head"><h3>${id?'ویرایش دسته هزینه':'دسته هزینه جدید'}</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg"><label>کد</label><input id="ec-code" value="${esc(row.code||'')}"></div>
      <div class="fg"><label>نام *</label><input id="ec-name" value="${esc(row.name||'')}"></div>
      <div class="fg full"><label>دسته والد ${hlp('برای سلسله‌مراتب: زیرمجموعه سطح قبلی. بدون والد = سطح ۱ (کل)')}</label>
        <select id="ec-parent"><option value="">— بدون والد (سطح کل) —</option>
          ${rows.filter(r=>r.id!==id).map(r=>`<option value="${r.id}" ${row.parent_id==r.id?'selected':''}>${'— '.repeat((r.level||1)-1)}${esc(r.name)}</option>`).join('')}
        </select></div>
      <div class="fg full"><label>کد حساب دفتر کل / معین ${hlp('باید زیرمجموعه سطح قبلی باشد و قابل رهگیری در دفتر کل')}</label>
        <input id="ec-account" dir="ltr" class="mono" value="${esc(row.coa_code||row.account_code||'')}" placeholder="مثال: 6102" list="ec-coa-list">
        <datalist id="ec-coa-list">${(CACHE.coa||[]).map(c=>`<option value="${esc(c.code)}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</datalist>
      </div>
    </div></div>
    <div class="modal-foot"><button class="btn" data-csp-click="${CSP.bind('click',function(event){saveExpenseCategory((id||0))})}">💾 ذخیره</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}
async function saveExpenseCategory(id){
  const name=el('ec-name').value.trim(); if(!name){ showToast('نام الزامی است','error'); return; }
  const coa=el('ec-account').value.trim();
  const data={name, code:el('ec-code').value.trim(), account_code:coa, coa_code:coa, parent_id:+el('ec-parent').value||null};
  try{
    if(id) await api('PUT','/expenses/categories/'+id,data); else await api('POST','/expenses/categories',data);
    closeModal(); showToast('ذخیره شد'); CACHE.expenseCategories=null; loadAccTab('expense-categories');
  }catch(e){}
}
async function deleteExpenseCategory(id){
  if(!confirm('این دسته حذف شود؟')) return;
  try{ await api('DELETE','/expenses/categories/'+id); showToast('حذف شد'); CACHE.expenseCategories=null; loadAccTab('expense-categories'); }catch(e){}
}

