async function personPaymentModal(){
  if(!CACHE.banks) CACHE.banks=await api('GET','/banks')||[];
  if(!CACHE.cashBoxes) CACHE.cashBoxes=await api('GET','/cash-boxes')||[];
  if(!CACHE.checkCategories) CACHE.checkCategories=await api('GET','/check-categories')||[];
  if(!CACHE.chartOfAccounts?.length) CACHE.chartOfAccounts=await api('GET','/accounting/chart-of-accounts')||[];
  const [partiesResp, reps]=await Promise.all([
    api('GET','/parties?limit=200')||{},
    api('GET','/accounting/commissions').catch(()=>[])||[]
  ]);
  const parties=(partiesResp.data||partiesResp||[]);
  const suppliers=parties.filter(p=>(p.party_roles||[]).includes('supplier')||p.party_type==='supplier'||p.party_type==='both');
  openModal(`
    <div class="modal-head"><h3>👤 پرداخت به شخص</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>نوع طرف حساب</label><select id="pp-kind" data-csp-change="${CSP.bind('change',function(event){ppKindChanged()})}">
        <option value="supplier">تأمین‌کننده</option>
        <option value="incentive">کارشناس / انگیزه فروش</option>
        <option value="party">سایر اشخاص</option>
      </select></div>
      <div class="fg full" id="pp-target-wrap"></div>
      ${moayanAcctHtml('pp','حساب معین طرف نقد/بانک در سند پرداخت — سطح معین کدینگ')}
      <div class="fg"><label>مبلغ (ریال) *</label><input id="pp-amount" type="text" inputmode="numeric" class="money"></div>
      <div class="fg"><label>نوع پرداخت</label><select id="pp-paytype" data-csp-change="${CSP.bind('change',function(event){toggleBankFields('pp')})}"><option value="cash">نقد</option><option value="cheque">چک</option><option value="bank">بانکی</option></select></div>
      <div class="fg"><label>پرداخت از بانک</label><select id="pp-bank" data-csp-change="${CSP.bind('change',function(event){updateCheckCategoryOptions('pp')})}">
        <option value="">—</option>${(CACHE.banks||[]).filter(b=>b.active).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}
      </select></div>
      <div class="fg"><label>پرداخت از صندوق</label><select id="pp-cashbox">
        <option value="">—</option>${(CACHE.cashBoxes||[]).filter(b=>b.active).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}
      </select></div>
      <div class="fg" id="pp-cc-wrap" data-csp-style="${CSP.style(`display:none`)}"><label>دسته چک</label><select id="pp-checkcat"><option value="">—</option></select></div>
      <div class="fg"><label>تاریخ</label><input id="pp-date" data-jdate value="${todayJalali()}"></div>
      <div class="fg full"><label>یادداشت</label><textarea id="pp-note"></textarea></div>
    </div></div>
    <div class="modal-foot"><button class="btn green" data-csp-click="${CSP.bind('click',function(event){savePersonPayment()})}">💾 ثبت پرداخت</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  window._ppSuppliers=suppliers; window._ppParties=parties; window._ppReps=reps||[];
  attachDatepickers(el('modalRoot'));
  ppKindChanged();
  toggleBankFields('pp');
}
function ppKindChanged(){
  const kind=el('pp-kind')?.value||'supplier';
  const wrap=el('pp-target-wrap'); if(!wrap) return;
  if(kind==='supplier'){
    wrap.innerHTML=`<label>تأمین‌کننده *</label><select id="pp-target"><option value="">— انتخاب —</option>${(window._ppSuppliers||[]).map(s=>{
      const sid=s.legacy_table==='suppliers'?s.legacy_id:s.id;
      return `<option value="${s.legacy_table==='suppliers'&&s.legacy_id?s.legacy_id:''}" data-party="${s.id}">${esc(s.full_name||s.biz||'-')}</option>`;
    }).join('')}</select><div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:4px`)}">اگر در لیست نبود، از اطلاعات اشخاص تأمین‌کننده بسازید.</div>`;
    // Prefer supplier legacy ids via API list
    api('GET','/suppliers').then(list=>{
      const sel=el('pp-target'); if(!sel) return;
      sel.innerHTML='<option value="">— انتخاب —</option>'+(list||[]).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
    }).catch(()=>{});
  } else if(kind==='incentive'){
    wrap.innerHTML=`<label>کارشناس *</label><select id="pp-target"><option value="">— انتخاب —</option>${(window._ppReps||[]).map(r=>`<option value="${r.id}" data-payable="${Math.round(r.payable||0)}">${esc(r.name)} — مانده: ${fmt(Math.round(r.payable||0))}</option>`).join('')}</select>`;
    if(!(window._ppReps||[]).length){
      api('GET','/accounting/commissions').then(d=>{
        const rows=d?.reps||d||[];
        const sel=el('pp-target'); if(!sel) return;
        sel.innerHTML='<option value="">— انتخاب —</option>'+rows.map(r=>`<option value="${r.id}" data-payable="${Math.round(r.payable||0)}">${esc(r.name)} — ${fmt(Math.round(r.payable||0))}</option>`).join('');
      }).catch(()=>{});
    }
  } else {
    wrap.innerHTML=`<label>شخص *</label><select id="pp-target"><option value="">— انتخاب —</option>${(window._ppParties||[]).map(p=>`<option value="${p.id}">${esc(p.full_name||p.biz||'-')}</option>`).join('')}</select>
      <div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:4px`)}">پرداخت سایر اشخاص به‌صورت هزینه ثبت می‌شود.</div>`;
  }
}
async function savePersonPayment(){
  const kind=el('pp-kind').value;
  const target=+el('pp-target')?.value||0;
  const amount=moneyVal('pp-amount');
  if(!target){ showToast('طرف حساب را انتخاب کنید','error'); return; }
  if(!amount||amount<=0){ showToast('مبلغ معتبر وارد کنید','error'); return; }
  const payload={
    amount:amount, pay_type:el('pp-paytype').value, date:el('pp-date').value, note:el('pp-note').value,
    bank_id:+el('pp-bank').value||null, cash_box_id:+el('pp-cashbox')?.value||null,
    check_category_id:+el('pp-checkcat')?.value||null,
    account_code:el('pp-account-code')?.value||''
  };
  try{
    if(kind==='supplier'){
      await api('POST','/purchases/payments',{...payload, supplier_id:target});
    } else if(kind==='incentive'){
      await api('POST','/accounting/incentive-payments',{...payload, rep_id:target});
    } else {
      const name=(el('pp-target').selectedOptions[0]?.textContent||'شخص').trim();
      await api('POST','/expenses',{...payload, category:'admin', title:'پرداخت به شخص: '+name, account_code:payload.account_code||null});
    }
    closeModal(); showToast('پرداخت ثبت شد'); loadAccTab('settlements');
  }catch(e){}
}
async function expensePaymentModal(){
  if(!CACHE.chartOfAccounts?.length) CACHE.chartOfAccounts=await api('GET','/accounting/chart-of-accounts')||[];
  if(!CACHE.expenseCategories) CACHE.expenseCategories=await api('GET','/expenses/categories').catch(()=>[])||[];
  const cats=CACHE.expenseCategories.length?CACHE.expenseCategories:[{code:'admin',name:'عمومی و اداری'},{code:'sales',name:'توزیع و فروش'}];
  openModal(`
    <div class="modal-head"><h3>🧾 ثبت پرداخت هزینه</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg"><label>دسته هزینه <button type="button" class="btn sm ghost" data-csp-style="${CSP.style(`padding:1px 8px;font-size:11px`)}" data-csp-click="${CSP.bind('click',function(event){exAddCategory()})}">➕ دستهٔ جدید</button></label><select id="ex-category">
        ${cats.map(c=>`<option value="${esc(c.code||c.id)}">${esc(c.name)}</option>`).join('')}
      </select></div>
      <div class="fg full"><label>حساب هزینه (معین) ${hlp('جستجو و انتخاب حساب معین از کدینگ — اگر خالی بماند از دسته پیش‌فرض استفاده می‌شود.')}</label>
        <input type="hidden" id="ex-account-code" value="">
        <input type="text" id="ex-account-search" class="search" placeholder="جستجوی حساب: کد یا نام..." autocomplete="off"
          data-csp-input="${CSP.bind('input',function(event){exAcctShow(this.value)})}" data-csp-focus="${CSP.bind('focus',function(event){exAcctShow(this.value)})}"
          data-csp-blur="${CSP.bind('blur',function(event){setTimeout(()=>{const d=el('ex-acct-drop');if(d)d.style.display='none'},200)})}">
        <div id="ex-acct-drop" class="cust-si-drop" data-csp-style="${CSP.style(`display:none;position:fixed;width:280px;max-height:220px`)}"></div>
      </div>
      <div class="fg full"><label>عنوان/بابت *</label><input id="ex-title" placeholder="مثال: اجاره دفتر، قبض برق، ..."></div>
      <div class="fg"><label>مبلغ (ریال) *</label><input id="ex-amount" type="text" inputmode="numeric" class="money" min="1"></div>
      <div class="fg"><label>فاکتور خرید مرتبط (اختیاری)</label><select id="ex-purchase"><option value="">— بدون ارتباط —</option></select></div>
      <div class="fg full"><label><input type="checkbox" id="ex-overhead" data-csp-style="${CSP.style(`width:auto;margin-left:6px`)}"> این هزینه سربار تولید است</label></div>
      <div class="fg"><label>نوع پرداخت</label><select id="ex-paytype" data-csp-change="${CSP.bind('change',function(event){toggleBankFields('ex')})}"><option value="cash">نقد</option><option value="cheque">چک</option><option value="bank">کارت به کارت / بانکی</option></select></div>
      <div class="fg"><label>پرداخت از بانک</label><select id="ex-bank" data-csp-change="${CSP.bind('change',function(event){updateCheckCategoryOptions('ex')})}">
        <option value="">— بدون بانک مشخص —</option>
        ${(CACHE.banks||[]).filter(b=>b.active).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}
      </select></div>
      <div class="fg"><label>پرداخت از صندوق</label><select id="ex-cashbox">
        <option value="">— بدون صندوق مشخص —</option>
        ${(CACHE.cashBoxes||[]).filter(b=>b.active).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}
      </select></div>
      <div class="fg" id="ex-cc-wrap" data-csp-style="${CSP.style(`display:none`)}"><label>دسته چک</label><select id="ex-checkcat"><option value="">— انتخاب نشده —</option></select></div>
      <div class="fg"><label>تاریخ</label><input id="ex-date" data-jdate value="${todayJalali()}"></div>
      <div class="fg full"><label>یادداشت</label><textarea id="ex-note"></textarea></div>
    </div></div>
    <div class="modal-foot"><button class="btn green" data-csp-click="${CSP.bind('click',function(event){saveExpensePayment()})}">💾 ثبت پرداخت</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
  attachDatepickers(el('modalRoot'));
  loadExpenseModalData();
}
async function exAddCategory(){
  const name=prompt('نام دستهٔ هزینهٔ جدید:'); if(!name||!name.trim()) return;
  try{
    const c=await api('POST','/expenses/categories',{name:name.trim()});
    CACHE.expenseCategories=await api('GET','/expenses/categories').catch(()=>[])||[];
    const sel=el('ex-category');
    if(sel){
      sel.innerHTML=(CACHE.expenseCategories||[]).map(x=>`<option value="${esc(x.code||x.id)}">${esc(x.name)}</option>`).join('');
      if(c) sel.value=String(c.code||c.id);
    }
    showToast('دستهٔ هزینه اضافه شد');
  }catch(e){}
}
async function loadExpenseModalData(){
  if(!CACHE.chartOfAccounts) CACHE.chartOfAccounts=await api('GET','/accounting/chart-of-accounts')||[];
  const purchases=await api('GET','/purchases')||[];
  const sel=el('ex-purchase');
  if(sel) sel.innerHTML='<option value="">— بدون ارتباط —</option>'+
    purchases.slice(0,100).map(p=>`<option value="${p.id}">${esc(p.num||'#'+p.id)} — ${esc(p.supplier_name||'-')} — ${fmt(p.final||p.total||0)} ریال</option>`).join('');
}
function exAcctShow(q){
  const drop=el('ex-acct-drop'), inp=el('ex-account-search'); if(!drop||!inp) return;
  const term=(q||'').trim().toLowerCase();
  let list=moayanAccounts().filter(a=>{
    const t=(a.type||'').toLowerCase();
    const code=String(a.code||'');
    return t==='expense'||t==='cogs'||code.startsWith('6')||code.startsWith('5')||!t;
  });
  if(term){ const words=term.split(/\s+/); list=list.filter(a=>{const hay=((a.code||'')+' '+(a.name||'')).toLowerCase(); return words.every(w=>hay.includes(w));}); }
  const rect=inp.getBoundingClientRect();
  drop.style.top=(rect.bottom+2)+'px'; drop.style.left=rect.left+'px'; drop.style.width=Math.max(rect.width,280)+'px'; drop.style.display='block'; drop.style.zIndex='9999';
  drop.innerHTML=list.slice(0,120).map(a=>`
    <div class="cust-si-item" data-csp-mousedown="${CSP.bind('mousedown',function(event){exAcctPick((a.code))})}">
      <span>${esc(a.name)}</span><span class="cust-si-meta">${esc(a.code)}</span>
    </div>`).join('')||'<div class="cust-si-empty">حساب معین یافت نشد — کدینگ را در اطلاعات پایه بررسی کنید</div>';
}
function exAcctPick(code){
  const a=(CACHE.chartOfAccounts||[]).find(x=>x.code===code);
  const hid=el('ex-account-code'), inp=el('ex-account-search');
  if(hid) hid.value=code;
  if(inp&&a) inp.value=a.code+' — '+a.name;
  const drop=el('ex-acct-drop'); if(drop) drop.style.display='none';
}
/** فهرست حساب‌های معین (سطح ۳ کدینگ) برای عملیات دریافت/پرداخت */
function moayanAccounts(){
  return filterCoaByMode(CACHE.chartOfAccounts||[], 'subsidiary-accounts').filter(a=>a._depth===2);
}
function moayanAcctHtml(prefix, help){
  return `<div class="fg full"><label>حساب معین (طرح حساب) ${hlp(help||'انتخاب حساب معین از کدینگ — اختیاری؛ در صورت خالی بودن از بانک/صندوق انتخاب‌شده استفاده می‌شود.')}</label>
    <input type="hidden" id="${prefix}-account-code" value="">
    <input type="text" id="${prefix}-account-search" class="search" placeholder="جستجوی حساب معین: کد یا نام..." autocomplete="off"
      data-csp-input="${CSP.bind('input',function(event){moayanAcctShow(`${String((prefix) ?? '')}`,this.value)})}" data-csp-focus="${CSP.bind('focus',function(event){moayanAcctShow(`${String((prefix) ?? '')}`,this.value)})}"
      data-csp-blur="${CSP.bind('blur',function(event){setTimeout(()=>{const d=el(`${String((prefix) ?? '')}-acct-drop`);if(d)d.style.display='none'},200)})}">
    <div id="${prefix}-acct-drop" class="cust-si-drop" data-csp-style="${CSP.style(`display:none;position:fixed;width:280px;max-height:220px`)}"></div>
  </div>`;
}
function moayanAcctShow(prefix, q){
  const drop=el(prefix+'-acct-drop'), inp=el(prefix+'-account-search'); if(!drop||!inp) return;
  const term=(q||'').trim().toLowerCase();
  let list=moayanAccounts();
  if(term){ const words=term.split(/\s+/); list=list.filter(a=>{const hay=((a.code||'')+' '+(a.name||'')).toLowerCase(); return words.every(w=>hay.includes(w));}); }
  const rect=inp.getBoundingClientRect();
  drop.style.top=(rect.bottom+2)+'px'; drop.style.left=rect.left+'px'; drop.style.width=Math.max(rect.width,280)+'px'; drop.style.display='block'; drop.style.zIndex='9999';
  drop.innerHTML=list.slice(0,120).map(a=>`
    <div class="cust-si-item" data-csp-mousedown="${CSP.bind('mousedown',function(event){moayanAcctPick((prefix),(a.code))})}">
      <span>${esc(a.name)}</span><span class="cust-si-meta">${esc(a.code)}</span>
    </div>`).join('')||'<div class="cust-si-empty">حساب معین یافت نشد — کدینگ را در اطلاعات پایه بررسی کنید</div>';
}
function moayanAcctPick(prefix, code){
  const a=(CACHE.chartOfAccounts||[]).find(x=>x.code===code);
  const hid=el(prefix+'-account-code'), inp=el(prefix+'-account-search');
  if(hid) hid.value=code;
  if(inp&&a) inp.value=a.code+' — '+a.name;
  const drop=el(prefix+'-acct-drop'); if(drop) drop.style.display='none';
}
async function saveExpensePayment(){
  const title=el('ex-title').value.trim();
  const amount=moneyVal('ex-amount');
  if(!title){ showToast('عنوان هزینه الزامی است','error'); return; }
  if(!amount||amount<=0){ showToast('مبلغ معتبر وارد کنید','error'); return; }
  try{
    await api('POST','/expenses',{
      category:el('ex-category').value, title, amount:amount,
      pay_type:el('ex-paytype').value, date:el('ex-date').value, note:el('ex-note').value,
      bank_id:+el('ex-bank').value||null, cash_box_id:+el('ex-cashbox')?.value||null,
      check_category_id:+el('ex-checkcat')?.value||null,
      account_code:el('ex-account-code')?.value||null,
      purchase_invoice_id:+el('ex-purchase')?.value||null,
      is_overhead:el('ex-overhead')?.checked||false
    });
    closeModal(); showToast('پرداخت هزینه ثبت شد'); loadAccTab('settlements');
  }catch(e){}
}
async function deletePaymentOp(kind,id){
  if(!confirm('این پرداخت حذف شود؟')) return;
  const endpoint = kind==='supplier' ? '/purchases/payments/'+id : kind==='incentive' ? '/accounting/incentive-payments/'+id : '/expenses/'+id;
  try{ await api('DELETE',endpoint); showToast('حذف شد'); loadAccTab('settlements'); }catch(e){}
}

function stmtQuery(){
  const p=[];
  if(accDateFrom) p.push('from='+encodeURIComponent(accDateFrom));
  if(accDateTo) p.push('to='+encodeURIComponent(accDateTo));
  if(stmtType) p.push('type='+encodeURIComponent(stmtType));
  return p.length?'?'+p.join('&'):'';
}

async function loadStatement(){
  const box=el('stmtBody'); if(!box||!stmtCustId) return;
  box.innerHTML='<div class="muted">در حال بارگذاری...</div>';
  const d=await api('GET','/accounting/statement/'+stmtCustId+stmtQuery());
  if(!d){ box.innerHTML='<div class="empty">خطا در دریافت صورت‌حساب</div>'; return; }
  const bal=v=>`${fmt(Math.abs(v||0))} ${(v||0)>0?'بد':'بس'}`;
  const mismatchBanner=d.books_mismatch?`<div class="panel" data-csp-style="${CSP.style(`margin-bottom:10px;border-color:#f59e0b`)}"><div class="panel-body" data-csp-style="${CSP.style(`color:#92400e;font-size:13px`)}">هشدار: مانده دفتر مشتری (${fmt(Math.abs(d.ledger_closing||0))}) با دفتر کل (${fmt(Math.abs(d.closing||0))}) یکی نیست. عدد اصلی و خروجی از دفتر کل است.</div></div>`:'';
  box.innerHTML=`
    ${mismatchBanner}
    <div class="panel">
      <div class="panel-head">
        <h4 data-csp-style="${CSP.style(`display:flex;align-items:center;gap:10px`)}"><img src="/logo-sm.png" data-csp-style="${CSP.style(`height:32px`)}" data-csp-error="${CSP.bind('error',function(event){this.style.display='none'})}"> صورت‌حساب: ${esc(d.customer.biz)} ${d.customer.owner?'— '+esc(d.customer.owner):''}</h4>
        <span class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">کارشناس: ${esc(d.customer.salesperson||'-')}</span>
      </div>
      <div class="panel-body tbl-wrap">
        <table class="tbl" data-csp-style="${CSP.style(`font-size:12px`)}"><thead><tr>
          <th>تاریخ</th><th>نوع تراکنش</th><th>شرح</th><th>بدهکار (ریال)</th><th>بستانکار (ریال)</th><th>مانده (ریال)</th><th>مرجع</th>
        </tr></thead><tbody>
        <tr data-csp-style="${CSP.style(`background:var(--purple-light);font-weight:600`)}">
          <td>-</td><td>مانده اول دوره</td><td>-</td><td>-</td><td>-</td>
          <td class="mono" data-csp-style="${CSP.style(`color:${(d.opening||0)>0?'var(--red)':'var(--green)'}`)}">${bal(d.opening)}</td><td>-</td>
        </tr>
        ${(d.entries||[]).map(e=>`<tr>
          <td class="mono">${esc(e.date||'-')}</td>
          <td>${esc(e.type_label||'-')}</td>
          <td>${esc(e.description||'-')}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${e.debit>0?fmt(e.debit):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${e.credit>0?fmt(e.credit):'-'}</td>
          <td class="mono" data-csp-style="${CSP.style(`font-weight:700;color:${(e.running_balance||0)>0?'var(--red)':'var(--green)'}`)}">${bal(e.running_balance)}</td>
          <td class="mono muted">${esc(e.reference||'-')}</td>
        </tr>`).join('')||'<tr><td colspan="7" class="empty">تراکنشی در این دوره ثبت نشده</td></tr>'}
        </tbody>
        <tfoot><tr data-csp-style="${CSP.style(`border-top:2px solid var(--border);background:var(--purple-light);font-weight:700`)}">
          <td colspan="3">جمع دوره</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--orange)`)}">${fmt(d.totalDebit||0)}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:var(--green)`)}">${fmt(d.totalCredit||0)}</td>
          <td class="mono" data-csp-style="${CSP.style(`color:${(d.closing||0)>0?'var(--red)':'var(--green)'}`)}">${bal(d.closing)}</td>
          <td></td>
        </tr></tfoot>
        </table>
      </div>
      <div data-csp-style="${CSP.style(`padding:12px 16px;border-top:1px solid var(--border);font-weight:700`)}">
        مانده نهایی (دفتر کل): <span data-csp-style="${CSP.style(`color:${(d.closing||0)>0?'var(--red)':'var(--green)'}`)}">${fmt(Math.abs(d.closing||0))} ریال ${(d.closing||0)>0?'(بدهکار)':'(بستانکار)'}</span>
        ${d.gl_account_code!=null?`<div class="muted" data-csp-style="${CSP.style(`font-weight:500;margin-top:6px;font-size:12px`)}">نمای دوم — مانده دفتر مشتری: ${fmt(Math.abs(d.ledger_closing||0))} ریال ${(d.ledger_closing||0)>0?'(بدهکار)':'(بستانکار)'} · حساب ${esc(d.gl_account_code)}</div>`:''}
      </div>
    </div>`;
}

function exportStatement(format){
  if(!stmtCustId){ showToast('ابتدا یک مشتری انتخاب کنید','error'); return; }
  const q=stmtQuery();
  const path='/accounting/statement/'+stmtCustId+'/export'+(q?q+'&':'?')+'format='+format;
  if(format==='pdf'){ openHtmlAuth('/api'+path); return; }
  downloadAuth(path, 'statement-'+stmtCustId+'.'+(format==='csv'?'csv':'xlsx'));
}

async function sendStatementImage(){
  if(!stmtCustId){ showToast('ابتدا مشتری انتخاب کنید','error'); return; }
  if(typeof html2canvas==='undefined'){ showToast('کتابخانه تولید تصویر بارگذاری نشده','error'); return; }
  if(!el('stmtBody')?.querySelector('.panel')){ showToast('ابتدا صورت‌حساب را نمایش دهید','error'); return; }
  let recipients=[];
  try{ recipients=await api('GET','/messages/users')||[]; }catch(e){}
  const opts=recipients.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');
  const broadcast=ME.role==='admin'?'<option value="">📢 همه کاربران</option>':'';
  const custName=(CACHE.customers.find(c=>String(c.id)===String(stmtCustId))||{}).biz||'';
  openModal(`
    <div class="modal-head"><h3>📤 ارسال صورت‌حساب به پیام‌رسان</h3><button class="x" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">×</button></div>
    <div class="modal-body"><div class="form-grid">
      <div class="fg full"><label>گیرنده</label><select id="si-to">${broadcast}${opts}</select></div>
      <div class="fg full"><label>توضیح (اختیاری)</label><textarea id="si-body" placeholder="متن همراه تصویر...">صورت‌حساب ${esc(custName)}</textarea></div>
    </div></div>
    <div class="modal-foot"><button class="btn green" data-csp-click="${CSP.bind('click',function(event){doSendStatementImage()})}">📤 ارسال</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){closeModal()})}">انصراف</button></div>`);
}

async function doSendStatementImage(){
  const to=el('si-to')?.value||'', body=el('si-body')?.value||'';
  const target=el('stmtBody')?.querySelector('.panel');
  if(!target){ showToast('صورت‌حساب یافت نشد','error'); return; }
  showToast('در حال تولید تصویر...');
  try{
    const canvas=await CSP.capture(target,{backgroundColor:'#ffffff',scale:2,useCORS:true});
    canvas.toBlob(async blob=>{
      if(!blob){ showToast('خطا در تولید تصویر','error'); return; }
      const fd=new FormData();
      fd.append('image',blob,'statement.png');
      if(to) fd.append('to_id',to);
      fd.append('body',body);
      try{
        await api('POST','/messages/with-image',fd,true);
        closeModal(); showToast('صورت‌حساب به پیام‌رسان ارسال شد');
        if(typeof refreshMsgBadge==='function') refreshMsgBadge();
      }catch(e){ showToast('خطا در ارسال','error'); }
    },'image/png');
  }catch(e){ showToast('خطا در تولید تصویر','error'); }
}

// Open an authenticated HTML page (e.g. printable PDF) in a new tab
async function openHtmlAuth(url){
  const token=localStorage.getItem('crm_token');
  try{
    const r=await fetch(url,{headers:{'Authorization':'Bearer '+token}});
    if(!r.ok){ showToast('خطا در دریافت','error'); return; }
    if(!await CSP.openVerifiedServerDocument(r)) showToast('مرورگر پنجره را مسدود کرد','error');
  }catch(e){ showToast('خطا','error'); }
}

async function deleteProductImage(imageId, productId){
  if(!confirm('این تصویر حذف شود؟')) return;
  try{
    await api('DELETE','/products/images/'+imageId);
    showToast('حذف شد');
    if(productId) prodModal(productId);
  }catch(e){}
}
async function approveInvoice(id){
  if(!confirm('این فاکتور تأیید و در محاسبه انگیزه فروش لحاظ شود؟')) return;
  try{
    const r = await api('POST','/accounting/invoices/'+id+'/approve',{});
    showToast('فاکتور با موفقیت تأیید شد');
    try{
      const blob=await captureInvoicePrintImage(id);
      if(blob){
        const fd=new FormData(); fd.append('image',blob,'invoice.png');
        await api('POST','/accounting/invoices/'+id+'/rubika',fd,true);
      }
    }catch(_){}
    if(r?.rubika?.ok) showToast('ارسال به روبیکا انجام شد');
    if(ROUTES[CURRENT_PAGE]) ROUTES[CURRENT_PAGE]();
  }catch(e){}
}

async function updateChequeStatus(id, status){
  if(!status) return;
  try{
    await api('PATCH','/accounting/cheques/'+id+'/status',{status});
    showToast('وضعیت چک بروز شد');
    loadAccTab('cheques');
  }catch(e){}
}

let stlRows = [];
