const AI_KIND_META = {
  churn_risk:   {icon:'⚠️', label:'ریسک ریزش', bg:'#fef2f2', color:'#dc2626'},
  opportunity:  {icon:'💡', label:'فرصت فروش', bg:'#f0fdf4', color:'#16a34a'},
  daily_action: {icon:'📌', label:'اقدام امروز', bg:'#eff6ff', color:'#1d4ed8'},
  weekly_summary:{icon:'📊', label:'خلاصه هفتگی', bg:'#faf5ff', color:'#7c3aed'},
};
ROUTES.ai = async function(){
  const isMgr=isManager();
  const isAcct=ME.role==='accounting';
  el('view').innerHTML=`<div class="muted" data-csp-style="${CSP.style(`padding:20px`)}">در حال بارگذاری...</div>`;
  let insights=[], summary=null, myStats=null;
  try{ insights = await api('GET','/ai/insights')||[]; }catch{}
  if(isMgr){ try{ summary = await api('GET','/ai/weekly-summary'); }catch{} }
  try{ myStats = await api('GET','/ai/my-summary'); }catch{}
  const isDeviceBuild = APP_INFO && APP_INFO.role==='device';
  const kinds=['churn_risk','opportunity','daily_action'];
  const byKind = k=>insights.filter(i=>i.kind===k);
  const card = i=>{
    const m = AI_KIND_META[i.kind]||{icon:'🤖',label:i.kind,bg:'#f9fafb',color:'#374151'};
    const ic=EMO_LU[m.icon]?lucide(EMO_LU[m.icon]):m.icon;
    return `<div data-csp-style="${CSP.style(`padding:12px 14px;border:1px solid var(--border);border-radius:12px;margin-bottom:8px;background:#fff`)}">
      <div data-csp-style="${CSP.style(`display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap`)}">
        <span class="tag" data-csp-style="${CSP.style(`background:${m.bg};color:${m.color};display:inline-flex;align-items:center;gap:4px`)}"><span class="ico" data-csp-style="${CSP.style(`width:14px;height:14px;display:inline-flex`)}">${ic}</span> ${m.label}</span>
        ${i.score!=null?`<span class="tag" data-csp-style="${CSP.style(`background:#f3f4f6;color:#374151`)}">${i.score}٪</span>`:''}
        <b data-csp-style="${CSP.style(`font-size:13px`)}">${esc(i.title||'')}</b>
      </div>
      <div data-csp-style="${CSP.style(`font-size:13px;line-height:1.9;color:#374151`)}">${esc(i.body||'')}</div>
      ${i.cust_biz?`<div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:4px`)}">مشتری: ${esc(i.cust_biz)}</div>`:''}
    </div>`;
  };
  const minePanel=`<div class="panel"><div class="panel-head"><h4>${lucide('bot')} دستیار شخصی من</h4></div>
    <div class="panel-body">
      <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:10px`)}">آمار و تحلیل فقط بر اساس داده‌های خود شماست.</p>
      ${myStats?`<div class="cards" data-csp-style="${CSP.style(`margin-bottom:12px`)}">
        ${statCard('g','💰',fmt(myStats.week_sales||0),'فروش هفته (ریال)')}
        ${statCard('b','🧾',fmt(myStats.week_invoices||0),'فاکتور هفته')}
        ${statCard('o','📅',fmt(myStats.month_sales||0),'فروش ماه (ریال)')}
        ${statCard('p','📞',fmt(myStats.open_followups||0),'پیگیری باز')}
      </div>`:'<div class="muted">آمار شخصی در دسترس نیست</div>'}
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){runMyAiSummary()})}">✨ تحلیل هوشمند عملکرد من</button>
      <div id="myAiBody" data-csp-style="${CSP.style(`margin-top:12px`)}"></div>
    </div></div>`;
  el('view').innerHTML=`
    ${minePanel}
    ${isMgr?`<div class="panel"><div class="panel-head"><h4>${lucide('briefcase')} مشاور کسب‌وکار (مدیر)</h4></div>
      <div class="panel-body">
        <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-bottom:10px`)}">سؤال خود را درباره فروش، مطالبات، موجودی یا استراتژی بپرسید — پاسخ بر اساس داده‌های تجمیع‌شده سیستم است.</p>
        <textarea id="aiConsultQ" rows="3" data-csp-style="${CSP.style(`width:100%;padding:10px;border:1.5px solid var(--border);border-radius:10px;font-family:inherit`)}" placeholder="مثال: کدام محصولات این ماه افت فروش داشته‌اند؟"></textarea>
        <button class="btn" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(event){runAiConsult()})}" ${isDeviceBuild?'disabled':''}>✨ پرسش از مشاور</button>
        <div id="aiConsultAns" data-csp-style="${CSP.style(`margin-top:12px;font-size:13.5px;line-height:2`)}"></div>
      </div></div>
    <div class="toolbar">
      <button class="btn" data-csp-click="${CSP.bind('click',function(event){runAiRefresh()})}" ${isDeviceBuild?'disabled title="فقط روی سرور مرکزی"':''}>🔄 تحلیل مجدد</button>
      <span class="muted" data-csp-style="${CSP.style(`font-size:12px`)}">تحلیل هر شب ساعت ۲ بامداد خودکار اجرا می‌شود.</span>
    </div>`:''}
    ${isAcct&&!isMgr?`<p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin:8px 0`)}">بینش‌های زیر برای نقش حسابداری (کل شرکت) است.</p>`:''}
    ${summary?`<div class="panel"><div class="panel-head"><h4>${lucide('chart')} خلاصه هفتگی</h4></div>
      <div class="panel-body" data-csp-style="${CSP.style(`font-size:13.5px;line-height:2.1`)}">${esc(summary.body||'')}</div></div>`:''}
    ${kinds.map(k=>{
      const rows=byKind(k); if(!rows.length) return '';
      const m=AI_KIND_META[k];
      return `<div class="panel"><div class="panel-head"><h4>${m.label} (${fmt(rows.length)})</h4></div>
        <div class="panel-body">${rows.map(card).join('')}</div></div>`;
    }).join('')||''}
    ${!insights.length&&!summary&&!myStats?`<div class="empty">هنوز تحلیلی تولید نشده است.${isMgr&&!isDeviceBuild?' روی «تحلیل مجدد» بزنید.':''}</div>`:''}`;
};
async function runAiConsult(){
  const q=el('aiConsultQ')?.value?.trim(); if(!q){ showToast('سؤال را بنویسید','error'); return; }
  const box=el('aiConsultAns'); if(box) box.innerHTML='<div class="muted">در حال تحلیل...</div>';
  try{
    const r=await api('POST','/ai/consult',{question:q});
    if(box) box.innerHTML=`<div data-csp-style="${CSP.style(`background:#faf5ff;border:1px solid #e9d5ff;border-radius:10px;padding:12px 14px`)}">${esc(r?.answer||'')}</div>`;
  }catch(e){ if(box) box.innerHTML='<div class="muted">خطا در دریافت پاسخ</div>'; }
}
async function runAiRefresh(){
  showToast('در حال اجرای تحلیل هوشمند...');
  const r = await api('POST','/ai/insights/refresh',{weekly:true});
  if(r && r.ok){ showToast('تحلیل هوشمند انجام شد'); CACHE.customers=[]; ROUTES.ai(); }
}
async function runMyAiSummary(){
  const box=el('myAiBody'); if(!box) return;
  box.innerHTML='<div class="muted">در حال تحلیل عملکرد شما...</div>';
  try{
    const r=await api('GET','/ai/my-summary?narrative=1');
    box.innerHTML=`<div data-csp-style="${CSP.style(`background:#faf5ff;border:1px solid #e9d5ff;border-radius:10px;padding:12px 14px`)}">✨ ${esc(r?.narrative||'تحلیلی تولید نشد')}</div>`;
  }catch(e){ box.innerHTML='<div class="muted">خطا در تولید تحلیل</div>'; }
}

