ROUTES.b2bOrders = async function(){
  if(!isAdmin()){ el('view').innerHTML='<div class="empty">فقط مدیران دسترسی دارند</div>'; return; }
  if(APP_INFO && APP_INFO.role==='device'){
    el('view').innerHTML='<div class="empty">پورتال مشتریان فقط روی سرور مرکزی (نسخه وب) فعال است.</div>'; return;
  }
  el('view').innerHTML='<div class="muted">در حال بارگذاری...</div>';
  let rows=[];
  try{ rows = await api('GET','/b2b/admin/orders')||[]; }catch(e){ el('view').innerHTML='<div class="empty">خطا در دریافت سفارشات</div>'; return; }
  const featureOff = !(CACHE.settings&&CACHE.settings.feature_b2b_portal==='1');
  el('view').innerHTML=`
    ${featureOff?`<div class="panel"><div class="panel-body" data-csp-style="${CSP.style(`background:#fffbeb;border-radius:12px`)}">
      ⚠️ پورتال مشتریان غیرفعال است — از <a href="#" data-csp-click="${CSP.bind('click',function(event){go('settings');return false})}" data-csp-style="${CSP.style(`color:var(--purple);font-weight:600`)}">تنظیمات</a> بخش «پورتال مشتریان» آن را فعال کنید.
    </div></div>`:''}
    <div class="panel"><div class="panel-head"><h4>🛒 ${T('سفارشات پورتال')}</h4>
      <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){ROUTES.b2bOrders()})}">🔄 ${T('بروزرسانی')}</button></div>
    <div class="panel-body tbl-wrap"><table class="tbl"><thead><tr>
      <th>#</th><th>مشتری</th><th>پیش‌فاکتور</th><th>اقلام</th><th>مبلغ</th><th>یادداشت</th><th>تاریخ ثبت</th><th>وضعیت فاکتور</th>
    </tr></thead><tbody>
      ${rows.map(o=>{
        const total=(o.rows||[]).reduce((a,r)=>a+(r.sum||0),0);
        return `<tr>
        <td>${o.id}</td><td>${esc(o.cust_biz||'-')}</td>
        <td>${o.invoice_num?`<a href="#" data-csp-click="${CSP.bind('click',function(event){go('invoices');return false})}" data-csp-style="${CSP.style(`color:var(--purple);font-weight:600`)}">${esc(o.invoice_num)}</a>`:'-'}</td>
        <td>${fmt((o.rows||[]).length)} قلم</td>
        <td class="mono">${fmt(total)} ریال</td>
        <td class="muted" data-csp-style="${CSP.style(`font-size:12px;max-width:200px`)}">${esc(o.note||'-')}</td>
        <td>${o.created_at?new Date(o.created_at*1000).toLocaleDateString('fa-IR'):'-'}</td>
        <td>${o.invoice_type==='final'?'<span class="tag t-done">تبدیل به فاکتور رسمی</span>':o.invoice_num?'<span class="tag t-pending">پیش‌فاکتور — در انتظار بررسی</span>':'-'}</td>
      </tr>`;}).join('')||emptyRow(8)}
    </tbody></table></div></div>
    <p class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:8px`)}">برای تأیید سفارش، پیش‌فاکتور مربوطه را از صفحه «فاکتور» باز کرده و به فاکتور رسمی تبدیل کنید — موجودی و حسابداری همان‌جا اعمال می‌شود.</p>`;
};

/* ============================================================
   B2B CUSTOMER PORTAL (client side)
============================================================ */
let B2B = { customer:null, tab:'catalog', cart:[], catalog:[] };

async function b2bApi(method, path, data){
  const opts={method,headers:{}};
  const token=localStorage.getItem('b2b_token');
  if(token) opts.headers['Authorization']='Bearer '+token;
  if(data){ opts.headers['Content-Type']='application/json'; opts.body=JSON.stringify(data); }
  const r=await fetch('/api/b2b'+path,opts);
  const j=await r.json().catch(()=>({}));
  if(r.status===401 && path.startsWith('/me')){ localStorage.removeItem('b2b_token'); renderB2BLogin(); throw new Error(j.error||'نشست منقضی شد'); }
  if(!r.ok) throw new Error(j.error||'خطا');
  return j;
}

function openB2BPortal(){
  el('login').style.display='none';
  el('app').style.display='none';
  el('b2bPortal').style.display='flex';
  location.hash='portal';
  const token=localStorage.getItem('b2b_token');
  if(token) b2bBoot().catch(()=>renderB2BLogin()); else renderB2BLogin();
}
function closeB2BPortal(){
  el('b2bPortal').style.display='none';
  el('login').style.display='flex';
  if(location.hash==='#portal') history.replaceState(null,'',location.pathname);
}
function b2bErr(msg){ const e=el('b2b-err'); if(e) e.textContent=msg||''; }
function renderB2BLogin(){
  B2B={customer:null,tab:'catalog',cart:[],catalog:[]};
  el('b2bContent').innerHTML=`
    <div class="b2b-head"><h2>🛒 پورتال مشتریان ترنم</h2><p class="muted">سفارش آنلاین · صورتحساب · تاریخچه فاکتور</p></div>
    <div class="form-grid">
      <div class="fg full"><label>شماره موبایل</label><input id="b2b-phone" placeholder="09123456789" dir="ltr" inputmode="tel"></div>
      <div class="fg full"><label>رمز عبور</label><input id="b2b-pass" type="password" autocomplete="current-password"></div>
    </div>
    <div data-csp-style="${CSP.style(`display:flex;gap:8px;margin-top:14px;flex-wrap:wrap`)}">
      <button class="btn green" data-csp-style="${CSP.style(`flex:1`)}" data-csp-click="${CSP.bind('click',function(event){b2bLogin()})}">ورود</button>
      <button class="btn ghost" data-csp-click="${CSP.bind('click',function(event){b2bRequestOtp()})}">ورود با کد پیامکی</button>
    </div>
    <div id="b2b-otp-box" data-csp-style="${CSP.style(`display:none;margin-top:12px`)}">
      <div class="fg full"><label>کد پیامک شده</label><input id="b2b-otp" dir="ltr" maxlength="6" inputmode="numeric"></div>
      <button class="btn" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(event){b2bVerifyOtp()})}">تأیید کد</button>
    </div>
    <div class="login-err" id="b2b-err"></div>
    <p data-csp-style="${CSP.style(`margin-top:16px;font-size:11px;color:var(--muted);line-height:1.8;text-align:right`)}">
      دسترسی به پورتال باید توسط مدیر فروش برای شما فعال شده باشد.
    </p>`;
}
async function b2bLogin(){
  b2bErr('');
  try{
    const r=await b2bApi('POST','/auth/login',{phone:el('b2b-phone').value,password:el('b2b-pass').value});
    localStorage.setItem('b2b_token',r.token);
    B2B.customer=r.customer;
    await b2bBoot();
  }catch(e){ b2bErr(e.message); }
}
async function b2bRequestOtp(){
  b2bErr('');
  try{
    await b2bApi('POST','/auth/otp',{phone:el('b2b-phone').value});
    el('b2b-otp-box').style.display='block';
    b2bErr('در صورت فعال بودن حساب، کد ورود پیامک شد');
  }catch(e){ b2bErr(e.message); }
}
async function b2bVerifyOtp(){
  b2bErr('');
  try{
    const r=await b2bApi('POST','/auth/otp/verify',{phone:el('b2b-phone').value,code:el('b2b-otp').value});
    localStorage.setItem('b2b_token',r.token);
    B2B.customer=r.customer;
    await b2bBoot();
  }catch(e){ b2bErr(e.message); }
}
function b2bLogout(){
  localStorage.removeItem('b2b_token');
  renderB2BLogin();
}
async function b2bBoot(){
  B2B.cart=[];
  el('b2bContent').innerHTML=`
    <div data-csp-style="${CSP.style(`display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px`)}">
      <div><strong>${esc(B2B.customer?.biz||'پورتال مشتریان')}</strong></div>
      <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){b2bLogout()})}">خروج</button>
    </div>
    <div class="b2b-tabs">
      <button class="active" data-csp-click="${CSP.bind('click',function(event){b2bTab('catalog')})}">🛍️ کاتالوگ و سفارش</button>
      <button data-csp-click="${CSP.bind('click',function(event){b2bTab('orders')})}">📦 سفارشات من</button>
      <button data-csp-click="${CSP.bind('click',function(event){b2bTab('statement')})}">💰 صورتحساب</button>
    </div>
    <div id="b2bTabBody"><div class="muted">بارگذاری...</div></div>`;
  await b2bTab('catalog');
}
async function b2bTab(tab){
  B2B.tab=tab;
  document.querySelectorAll('.b2b-tabs button').forEach((b,i)=>{
    b.classList.toggle('active',['catalog','orders','statement'][i]===tab);
  });
  const body=el('b2bTabBody');
  if(!body) return;
  body.innerHTML='<div class="muted">بارگذاری...</div>';
  try{
    if(tab==='catalog') await b2bRenderCatalog(body);
    else if(tab==='orders') await b2bRenderOrders(body);
    else await b2bRenderStatement(body);
  }catch(e){ body.innerHTML=`<div class="empty">${esc(e.message||'خطا')}</div>`; }
}
async function b2bRenderCatalog(body){
  if(!B2B.catalog.length) B2B.catalog=await b2bApi('GET','/me/catalog');
  const prods=B2B.catalog;
  body.innerHTML=`
    <div class="b2b-grid">${prods.map(p=>`
      <div class="b2b-prod ${p.available?'':'unavail'}">
        ${p.image?`<img src="${esc(p.image)}" loading="lazy" alt="">`:''}
        <div data-csp-style="${CSP.style(`font-weight:600;margin-bottom:2px`)}">${esc(p.name)}</div>
        <div class="muted">${esc(p.category||'')}</div>
        <div class="mono" data-csp-style="${CSP.style(`margin:6px 0`)}">${fmt(p.price)} ریال</div>
        ${p.available?`<button class="btn sm" data-csp-click="${CSP.bind('click',function(event){b2bAddCart((p.id))})}">➕ افزودن</button>`:'<span class="tag t-silent">ناموجود</span>'}
      </div>`).join('')||'<div class="empty">کالایی یافت نشد</div>'}
    </div>
    <div class="b2b-cart">
      <strong>🧺 سبد سفارش (<span id="b2bCartCount">${B2B.cart.length}</span>)</strong>
      <div id="b2bCartList" data-csp-style="${CSP.style(`margin:8px 0;font-size:13px`)}"></div>
      <textarea id="b2b-note" rows="2" placeholder="یادداشت سفارش (اختیاری)" data-csp-style="${CSP.style(`width:100%;padding:8px;border:1px solid var(--border);border-radius:8px;font-family:inherit`)}"></textarea>
      <button class="btn green" id="b2bSubmitBtn" data-csp-style="${CSP.style(`margin-top:8px`)}" data-csp-click="${CSP.bind('click',function(event){b2bSubmitOrder()})}" ${B2B.cart.length?'':'disabled'}>✅ ثبت سفارش</button>
    </div>`;
  b2bRenderCart();
}
function b2bAddCart(id){
  const ex=B2B.cart.find(x=>x.product_id===id);
  if(ex) ex.qty++; else B2B.cart.push({product_id:id,qty:1});
  b2bRenderCart();
}
function b2bSetQty(i,delta){
  const item=B2B.cart[i]; if(!item) return;
  item.qty+=delta;
  if(item.qty<=0) B2B.cart.splice(i,1);
  b2bRenderCart();
}
function b2bRenderCart(){
  const list=el('b2bCartList'); if(!list) return;
  const cnt=el('b2bCartCount'); if(cnt) cnt.textContent=fmt(B2B.cart.length);
  const btn=el('b2bSubmitBtn'); if(btn) btn.disabled=!B2B.cart.length;
  let total=0;
  list.innerHTML=B2B.cart.length?B2B.cart.map((c,i)=>{
    const p=B2B.catalog.find(x=>x.id===c.product_id)||{};
    total+=(p.price||0)*c.qty;
    return `<div data-csp-style="${CSP.style(`display:flex;align-items:center;gap:8px;padding:4px 0;border-bottom:1px dashed var(--border)`)}">
      <span data-csp-style="${CSP.style(`flex:1`)}">${esc(p.name||('#'+c.product_id))}</span>
      <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){b2bSetQty((i),-1)})}">−</button>
      <span class="mono">${fmt(c.qty)}</span>
      <button class="btn sm ghost" data-csp-click="${CSP.bind('click',function(event){b2bSetQty((i),1)})}">+</button>
      <span class="mono" data-csp-style="${CSP.style(`min-width:80px;text-align:left`)}">${fmt((p.price||0)*c.qty)} ریال</span>
    </div>`;
  }).join('')+`<div data-csp-style="${CSP.style(`text-align:left;font-weight:700;padding-top:6px`)}">جمع: ${fmt(total)} ریال</div>`
  :'<span class="muted">سبد خالی است — از کاتالوگ بالا محصول اضافه کنید</span>';
}
async function b2bSubmitOrder(){
  if(!B2B.cart.length) return;
  const btn=el('b2bSubmitBtn'); if(btn) btn.disabled=true;
  try{
    const r=await b2bApi('POST','/me/orders',{rows:B2B.cart,note:el('b2b-note')?.value||''});
    B2B.cart=[];
    showToast(`سفارش ثبت شد — پیش‌فاکتور ${r.invoiceNum||''}`);
    await b2bTab('orders');
  }catch(e){ if(btn) btn.disabled=false; showToast(e.message||'ثبت سفارش ناموفق بود','error'); }
}
async function b2bRenderOrders(body){
  const rows=await b2bApi('GET','/me/orders');
  body.innerHTML=`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>#</th><th>پیش‌فاکتور</th><th>اقلام</th><th>مبلغ</th><th>تاریخ</th><th>وضعیت</th></tr></thead><tbody>
    ${rows.map(o=>{
      const total=(o.rows||[]).reduce((a,r)=>a+(r.sum||0),0);
      return `<tr><td>${o.id}</td><td class="mono">${esc(o.invoice_num||'-')}</td>
      <td>${fmt((o.rows||[]).length)}</td><td class="mono">${fmt(total)} ریال</td>
      <td>${o.created_at?new Date(o.created_at*1000).toLocaleDateString('fa-IR'):'-'}</td>
      <td>${o.invoice_type==='final'?'<span class="tag t-done">تأیید شده</span>':'<span class="tag t-pending">در انتظار بررسی</span>'}</td></tr>`;
    }).join('')||emptyRow(6)}
  </tbody></table></div>`;
}
async function b2bRenderStatement(body){
  const data=await b2bApi('GET','/me/statement');
  const bal=data.closing??data.customer?.balance??0;
  body.innerHTML=`
    <div data-csp-style="${CSP.style(`padding:12px;background:${bal>0?'#fef2f2':'#f0fdf4'};border-radius:10px;margin-bottom:12px`)}">
      مانده حساب: <strong class="mono">${fmt(Math.abs(bal))} ریال ${bal>0?'(بدهکار)':bal<0?'(بستانکار)':''}</strong>
    </div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr><th>تاریخ</th><th>شرح</th><th>بدهکار</th><th>بستانکار</th><th>مانده</th></tr></thead><tbody>
      ${(data.entries||[]).slice(-50).reverse().map(r=>`<tr>
        <td>${escDate(r.date)}</td><td>${esc(r.description||r.type_label||'')}</td>
        <td class="mono">${r.debit?fmt(r.debit):'-'}</td>
        <td class="mono">${r.credit?fmt(r.credit):'-'}</td>
        <td class="mono">${r.running_balance!=null?fmt(r.running_balance):'-'}</td>
      </tr>`).join('')||emptyRow(5)}
    </tbody></table></div>`;
}

