      <div id="fy-status" class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-top:10px`)}">${curFy?`سال فعال: <b>${esc(curFy.label)}</b> (${esc(curFy.status||'open')}) — ${esc(curFy.start_date||'')} الی ${esc(curFy.end_date||'—')}`:''}</div>
