let _pwaPrompt = null;
window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  _pwaPrompt = e;
  if(!localStorage.getItem('pwa_dismissed')) el('installBanner').classList.add('show');
});
function doPWAInstall(){
  if(!_pwaPrompt) return;
  _pwaPrompt.prompt();
  _pwaPrompt.userChoice.then(r=>{ if(r.outcome==='accepted') dismissInstall(); });
}
function dismissInstall(){ el('installBanner').classList.remove('show'); localStorage.setItem('pwa_dismissed','1'); }

/* ============================================================
   APP UPDATE (desktop / android device builds)
============================================================ */
function detectClientPlatform(){
  const ua = navigator.userAgent || '';
  if(ua.includes('ERPTaranomAndroid') || ua.includes('CRMTaranomAndroid')) return 'android';
  if(ua.includes('Electron')) return 'desktop';
  return 'web';
}

async function initAppUpdate(){
  try{
    APP_INFO = await fetch('/api/system/app-info').then(r=>r.json());
    const platform = detectClientPlatform();
    if(platform==='desktop' && (APP_INFO?.role==='device' || isDesktopApp())){
      await initDesktopUpdate();
      setInterval(()=>checkAppUpdate(false), 6*60*60*1000);
      return;
    }
    if(platform==='android'){
      await checkAppUpdate(false);
      setInterval(()=>checkAppUpdate(false), 6*60*60*1000);
      return;
    }
    // وب مرکزی: پنل نسخه در تنظیمات؛ اعلان آپدیت برای اپ‌هاست
    renderAppUpdateUI();
  }catch(e){}
}

let DESKTOP_UPDATE = { status:'idle', currentVersion:'', latestVersion:null, percent:0, error:null, fallbackUrl:null };
let APP_UPDATE_UI = { status:'idle', currentVersion:'', latestVersion:null, notes:'', url:null, platform:'web' };

function appUpdatePanelHtml(){
  return `
    <div class="panel" id="desktopUpdatePanel" data-csp-style="${CSP.style(`margin-bottom:16px`)}">
      <div class="panel-head"><h4>⬆️ به‌روزرسانی نرم‌افزار</h4></div>
      <div class="panel-body">
        <p data-csp-style="${CSP.style(`margin-bottom:8px`)}">نسخه فعلی: <strong class="mono" id="du-current">—</strong>
          <span class="muted" data-csp-style="${CSP.style(`font-size:12px;margin-right:8px`)}" id="du-platform-label"></span></p>
        <p id="du-status-msg" class="muted" data-csp-style="${CSP.style(`font-size:13px;margin-bottom:12px`)}">برای بررسی نسخه جدید دکمه را بزنید.</p>
        <div id="du-progress-wrap" data-csp-style="${CSP.style(`display:none;margin-bottom:12px`)}">
          <div data-csp-style="${CSP.style(`height:8px;background:var(--border);border-radius:4px;overflow:hidden`)}">
            <div id="du-progress-bar" data-csp-style="${CSP.style(`height:100%;width:0;background:var(--purple);transition:width .3s`)}"></div>
          </div>
          <div class="muted" data-csp-style="${CSP.style(`font-size:11px;margin-top:4px`)}" id="du-progress-label"></div>
        </div>
        <div data-csp-style="${CSP.style(`display:flex;gap:8px;flex-wrap:wrap`)}">
          <button class="btn" id="du-main-btn" data-csp-click="${CSP.bind('click',function(event){appUpdateMainAction()})}">🔄 بررسی به‌روزرسانی</button>
        </div>
      </div>
    </div>`;
}
function desktopUpdatePanelHtml(){ return appUpdatePanelHtml(); }

let _lastNativeUpdateNotifVer = '';
async function registerUpdateNotification(u){
  if(!u || !u.update_available || !u.latest_version) return;
  try{
    await api('POST','/notifications/register-update',{
      platform: u.platform || detectClientPlatform(),
      version: u.latest_version,
      notes: u.notes || ''
    }, false, true);
    refreshPendingBadge();
  }catch{}
  // نوتیفیکیشن سیستمی اندروید (یک‌بار برای هر نسخه در همین نشست)
  try{
    const ver = String(u.latest_version);
    if(window.AndroidBridge && typeof AndroidBridge.notifyUpdate==='function' && _lastNativeUpdateNotifVer!==ver){
      _lastNativeUpdateNotifVer = ver;
      AndroidBridge.notifyUpdate(
        'به‌روزرسانی ERP ترنم '+ver,
        u.notes || 'نسخه جدید آماده است — از تنظیمات برنامه نصب کنید'
      );
    }
  }catch{}
}

// Human-readable download progress: "۴۵٫۲ از ۹۷٫۰ مگابایت — حدود ۲۵ ثانیه مانده"
function fmtDlProgress(transferred, total, bps){
  if(!total) return '';
  const mb=b=>(b/1048576).toFixed(1);
  let out=`${mb(transferred)} از ${mb(total)} مگابایت (${Math.round(transferred/total*100)}٪)`;
  if(bps>1024){
    const secs=Math.max(1,Math.round((total-transferred)/bps));
    const t = secs>=120 ? `حدود ${Math.round(secs/60)} دقیقه` : `حدود ${secs} ثانیه`;
    out+=` — ${t} مانده`;
  }
  return out;
}

function renderAppUpdateUI(){
  const cur=el('du-current'), msg=el('du-status-msg'), btn=el('du-main-btn');
  const progWrap=el('du-progress-wrap'), progBar=el('du-progress-bar'), progLabel=el('du-progress-label');
  const platLabel=el('du-platform-label');
  if(!cur) return;
  const plat = detectClientPlatform();
  if(platLabel) platLabel.textContent = plat==='android'?'(اندروید)':plat==='desktop'?'(ویندوز)':'(وب)';

  // دسکتاپ با Electron API
  if(plat==='desktop' && (window.desktopAPI || DESKTOP_UPDATE.status!=='idle' || APP_INFO?.role==='device')){
    const s=DESKTOP_UPDATE;
    cur.textContent = s.currentVersion || APP_INFO?.version || '—';
    if(progWrap) progWrap.style.display = s.status==='downloading'?'block':'none';
    if(progBar) progBar.style.width = (s.percent||0)+'%';
    if(progLabel) progLabel.textContent = fmtDlProgress(s.transferred||0, s.total||0, s.bps||0) || (s.percent?`دانلود: ${s.percent}٪`:'');
    let msgText='', btnLabel='🔄 بررسی به‌روزرسانی', btnDisabled=false, btnGreen=false;
    switch(s.status){
      case 'checking':
        msgText='در حال بررسی به‌روزرسانی...'; btnLabel='در حال بررسی...'; btnDisabled=true; break;
      case 'downloading':
        msgText=`نسخه ${s.latestVersion||''} در حال دانلود است — پس از پایان دانلود، دکمه به «نصب» تبدیل می‌شود.`;
        btnLabel='⬇️ در حال دانلود...'; btnDisabled=true; break;
      case 'ready':
        msgText=`نسخه ${s.latestVersion} دانلود شد و آماده نصب است.`;
        btnLabel=`🚀 نصب نسخه ${s.latestVersion} و راه‌اندازی مجدد`; btnGreen=true; break;
      case 'available-fallback':
        msgText=`نسخه ${s.latestVersion} موجود است.`;
        btnLabel=`⬇️ دانلود و نصب نسخه ${s.latestVersion}`; btnGreen=true; break;
      case 'uptodate':
        msgText='✅ شما از آخرین نسخه استفاده می‌کنید.'; break;
      case 'error':
        msgText='❌ '+(s.error||'خطا در به‌روزرسانی'); break;
      default:
        msgText='برای بررسی نسخه جدید، دکمه را بزنید.';
    }
    if(msg) msg.textContent=msgText;
    if(btn){ btn.disabled=btnDisabled; btn.textContent=btnLabel; btn.classList.toggle('green',btnGreen); btn.classList.toggle('ghost',!btnGreen&&!btnDisabled); }
    updateDesktopNavBadge();
    return;
  }

  // اندروید / وب
  const u=APP_UPDATE_UI;
  cur.textContent = u.currentVersion || APP_INFO?.version || (plat==='web'?(readManifestWebVersion?.()||'—'):'—');
  if(progWrap) progWrap.style.display='none';
  let msgText='برای بررسی نسخه جدید، دکمه را بزنید.', btnLabel='🔄 بررسی به‌روزرسانی', btnDisabled=false, btnGreen=false;
  if(u.status==='checking'){ msgText='در حال بررسی...'; btnLabel='در حال بررسی...'; btnDisabled=true; }
  else if(u.status==='available'){
    msgText=`نسخه ${u.latestVersion} موجود است.`+(u.notes?' — '+u.notes:'');
    if(u.url){ btnLabel=`⬇️ دانلود / نصب ${u.latestVersion}`; btnGreen=true; }
    else if(plat==='android'){ msgText+=' فایل APK را از مدیر سیستم دریافت و نصب کنید (نصب محلی).'; btnLabel='✅ متوجه شدم'; btnGreen=true; }
    else { btnLabel='🔄 بررسی مجدد'; }
  }
  else if(u.status==='uptodate'){ msgText='✅ شما از آخرین نسخه استفاده می‌کنید.'; }
  else if(u.status==='error'){ msgText='❌ '+(u.error||'خطا'); }
  else if(plat==='web'){ msgText='نسخه وب با بازخوانی صفحه (Ctrl+Shift+R) به‌روز می‌شود. برای اپ ویندوز/اندروید از همان دکمه روی دستگاه استفاده کنید.'; btnLabel='🔄 بازخوانی صفحه'; }
  if(msg) msg.textContent=msgText;
  if(btn){ btn.disabled=btnDisabled; btn.textContent=btnLabel; btn.classList.toggle('green',btnGreen); btn.classList.toggle('ghost',!btnGreen&&!btnDisabled); }
  updateDesktopNavBadge();
}
function renderDesktopUpdateUI(){ renderAppUpdateUI(); }
function readManifestWebVersion(){
  try{ return APP_INFO?.manifest?.web?.version || APP_INFO?.version; }catch{ return null; }
}

function appUpdateMainAction(){
  const plat=detectClientPlatform();
  if(plat==='desktop'){
    const s=DESKTOP_UPDATE.status;
    if(s==='ready'||s==='available-fallback') return desktopInstallUpdate();
    return desktopCheckUpdate();
  }
  if(plat==='android'){
    if(APP_UPDATE_UI.status==='available' && PENDING_UPDATE?.downloadable){ doAppUpdate(); return; }
    if(APP_UPDATE_UI.status==='available' && PENDING_UPDATE?.integrity_required && !PENDING_UPDATE?.integrity_valid){
      showToast('آپدیت به‌دلیل فقدان شناسه صحت قابل نصب نیست','error');
      return;
    }
    if(APP_UPDATE_UI.status==='available' && !APP_UPDATE_UI.url){
      showToast('نسخه جدید آماده است — APK را از مدیر دریافت و نصب کنید');
      return;
    }
    return checkAppUpdate(true);
  }
  // وب
  location.reload();
}
function desktopUpdateMainAction(){ return appUpdateMainAction(); }

function updateDesktopNavBadge(){
  const ready=DESKTOP_UPDATE.status==='ready'||DESKTOP_UPDATE.status==='available-fallback';
  document.querySelectorAll('[data-page="settings"],[data-page="desktop-settings"]').forEach(a=>{
    a.style.fontWeight = ready ? '700' : '';
  });
}

async function initDesktopUpdate(){
  if(!isDesktopApp()) return;
  if(APP_INFO?.version) DESKTOP_UPDATE.currentVersion=APP_INFO.version;
  if(window.desktopAPI){
    try{
      DESKTOP_UPDATE = await window.desktopAPI.getUpdateStatus();
      if(!DESKTOP_UPDATE.currentVersion) DESKTOP_UPDATE.currentVersion=APP_INFO?.version;
      window.desktopAPI.onUpdateStatus(st=>{
        DESKTOP_UPDATE=st;
        if(st && (st.status==='ready'||st.status==='available-fallback'||st.status==='downloading') && st.latestVersion){
          registerUpdateNotification({
            update_available:true,
            latest_version:st.latestVersion,
            notes:'نسخه جدید دسکتاپ آماده است',
            platform:'desktop',
            url:st.fallbackUrl||null
          });
        }
        if(st && st.status==='error'){
          // feed الکترون نبود — مسیر manifest
          desktopCheckUpdateFallback();
          return;
        }
        renderDesktopUpdateUI();
      });
      renderDesktopUpdateUI();
      await window.desktopAPI.checkForUpdates();
    }catch(e){ await desktopCheckUpdateFallback(); }
    return;
  }
  await desktopCheckUpdateFallback();
}

async function desktopCheckUpdateFallback(){
  if(!APP_INFO||APP_INFO.role!=='device') return;
  DESKTOP_UPDATE.status='checking';
  renderDesktopUpdateUI();
  try{
    const r=await fetch(`/api/system/app-update?platform=desktop&version=${encodeURIComponent(APP_INFO.version||'0')}`);
    if(!r.ok){ DESKTOP_UPDATE.status='error'; DESKTOP_UPDATE.error='خطا در ارتباط با سرور'; renderDesktopUpdateUI(); return; }
    const u=await r.json();
    if(u.update_available && u.downloadable && u.integrity_valid){
      DESKTOP_UPDATE={...DESKTOP_UPDATE, status:'available-fallback', latestVersion:u.latest_version, fallbackUrl:u.url, fallbackSha256:u.sha256, fallbackSize:u.size};
      await registerUpdateNotification({ update_available:true, latest_version:u.latest_version, notes:u.notes, platform:'desktop', url:u.url });
    }else if(u.update_available){
      DESKTOP_UPDATE={...DESKTOP_UPDATE, status:'error', latestVersion:u.latest_version, fallbackUrl:null, fallbackSha256:null, fallbackSize:null, error:'اطلاعات صحت‌سنجی آپدیت ناقص است'};
    }else{
      DESKTOP_UPDATE={...DESKTOP_UPDATE, status:'uptodate', latestVersion:null, fallbackUrl:null};
    }
    renderAppUpdateUI();
  }catch(e){ DESKTOP_UPDATE.status='error'; DESKTOP_UPDATE.error='خطا در بررسی'; renderAppUpdateUI(); }
}

async function desktopCheckUpdate(){
  if(window.desktopAPI){
    DESKTOP_UPDATE.status='checking';
    renderDesktopUpdateUI();
    DESKTOP_UPDATE=await window.desktopAPI.checkForUpdates();
    renderDesktopUpdateUI();
    return;
  }
  await desktopCheckUpdateFallback();
}

async function desktopInstallUpdate(){
  if(!window.desktopAPI){ showToast('نصب امن فقط از داخل برنامه دسکتاپ مجاز است','error'); return; }
  if(DESKTOP_UPDATE.status!=='ready'&&DESKTOP_UPDATE.status!=='available-fallback'){
    showToast('به‌روزرسانی هنوز آماده نیست','error'); return;
  }
  const fallback = DESKTOP_UPDATE.status==='available-fallback' ? {
    url: DESKTOP_UPDATE.fallbackUrl,
    sha256: DESKTOP_UPDATE.sha256||DESKTOP_UPDATE.fallbackSha256,
    size: DESKTOP_UPDATE.size||DESKTOP_UPDATE.fallbackSize
  } : null;
  const r=await window.desktopAPI.installUpdate(fallback);
  if(r&&!r.ok) showToast(r.error||'خطا در نصب','error');
}

async function checkAppUpdate(fromUi){
  const platform = detectClientPlatform();
  if(platform==='desktop' && window.desktopAPI && !fromUi){
    renderAppUpdateUI();
    return;
  }
  if(!APP_INFO){
    try{ APP_INFO = await fetch('/api/system/app-info').then(r=>r.json()); }catch{ return; }
  }
  if(platform==='web'){
    APP_UPDATE_UI = {
      status:'idle', platform:'web',
      currentVersion: APP_INFO.manifest?.web?.version || APP_INFO.version || '—',
      latestVersion:null, notes:'', url:null
    };
    if(fromUi || el('du-current')) renderAppUpdateUI();
    return;
  }
  const clientVer = APP_INFO.version || '0';
  APP_UPDATE_UI = { ...APP_UPDATE_UI, status:'checking', platform, currentVersion: clientVer||'—' };
  if(fromUi) renderAppUpdateUI();
  try{
    const r = await fetch(`/api/system/app-update?platform=${encodeURIComponent(platform)}&version=${encodeURIComponent(clientVer||'0')}`);
    if(!r.ok){ APP_UPDATE_UI.status='error'; APP_UPDATE_UI.error='خطا در ارتباط'; if(fromUi) renderAppUpdateUI(); return; }
    PENDING_UPDATE = await r.json();
    PENDING_UPDATE.platform = platform;
    APP_UPDATE_UI.currentVersion = PENDING_UPDATE.current || clientVer || '—';
    if(PENDING_UPDATE.update_available){
      APP_UPDATE_UI.status='available';
      APP_UPDATE_UI.latestVersion = PENDING_UPDATE.latest_version;
      APP_UPDATE_UI.notes = PENDING_UPDATE.notes || '';
      APP_UPDATE_UI.url = PENDING_UPDATE.downloadable ? (PENDING_UPDATE.url || null) : null;
      await registerUpdateNotification(PENDING_UPDATE);
      if(!localStorage.getItem('upd_dismiss_'+PENDING_UPDATE.latest_version)) showUpdateBanner();
    }else{
      APP_UPDATE_UI.status='uptodate';
      APP_UPDATE_UI.latestVersion = PENDING_UPDATE.latest_version || null;
    }
    if(fromUi || el('du-current')) renderAppUpdateUI();
  }catch(e){
    APP_UPDATE_UI.status='error'; APP_UPDATE_UI.error='خطا در بررسی';
    if(fromUi) renderAppUpdateUI();
  }
}

function showUpdateBanner(){
  const b = el('updateBanner'), t = el('updateBannerText');
  if(!b || !t || !PENDING_UPDATE) return;
  const plat = PENDING_UPDATE.platform || detectClientPlatform();
  const label = plat==='android' ? 'نسخه جدید اپ اندروید' : 'نسخه جدید دسکتاپ';
  t.textContent = `⬆️ ${label} (${PENDING_UPDATE.latest_version}) موجود است` + (PENDING_UPDATE.notes ? ' — '+PENDING_UPDATE.notes : '');
  b.style.display = 'flex';
}

function doAppUpdate(){
  if(!PENDING_UPDATE || !PENDING_UPDATE.url || !PENDING_UPDATE.downloadable){ showToast('لینک دانلود امن در دسترس نیست','error'); return; }
  const platform=PENDING_UPDATE.platform||detectClientPlatform();
  if(platform==='android'){
    if(!PENDING_UPDATE.integrity_valid || !/^[a-f0-9]{64}$/i.test(PENDING_UPDATE.sha256||'') || !Number.isSafeInteger(Number(PENDING_UPDATE.size)) || Number(PENDING_UPDATE.size)<=0){
      showToast('نصب متوقف شد: اطلاعات صحت‌سنجی APK ناقص است','error'); return;
    }
    if(!window.AndroidBridge || typeof AndroidBridge.downloadVerifiedApk!=='function'){
      showToast('نصب امن APK در این نسخه پشتیبانی نمی‌شود','error'); return;
    }
    let result;
    try{ result=JSON.parse(AndroidBridge.downloadVerifiedApk(PENDING_UPDATE.url,PENDING_UPDATE.sha256,Number(PENDING_UPDATE.size))||'{}'); }
    catch(e){ showToast('شروع دانلود امن ناموفق بود','error'); return; }
    if(!result.accepted){ showToast(result.error||'آدرس یا شناسه APK رد شد','error'); return; }
    APK_DL={t0:Date.now(),shown:true};
    const t=el('updateBannerText');
    if(t) t.textContent='⬇️ دانلود نسخه جدید شروع شد...';
    return;
  }
  showToast('نصب این آپدیت باید از مسیر امن پلتفرم انجام شود','error');
}

// Fed by the Android shell: bytes downloaded / total / 'downloading'|'done'|'failed'
let APK_DL=null;
window.onApkDownloadProgress=function(done,total,status){
  const b=el('updateBanner'), t=el('updateBannerText');
  if(!t){ return; }
  if(b) b.style.display='flex';
  if(status==='failed'){
    t.textContent='❌ دانلود ناموفق بود — دوباره تلاش کنید یا از مرورگر دانلود کنید.';
    APK_DL=null; return;
  }
  if(status==='done'){
    t.textContent='✅ دانلود کامل شد — نصب را در پنجره بازشده تأیید کنید.';
    APK_DL=null; return;
  }
  let label='⬇️ در حال دانلود نسخه جدید';
  if(total>0){
    const mb=x=>(x/1048576).toFixed(1);
    label+=`: ${mb(done)} از ${mb(total)} مگابایت (${Math.round(done/total*100)}٪)`;
    if(APK_DL&&APK_DL.t0&&done>0){
      const bps=done/Math.max(1,(Date.now()-APK_DL.t0)/1000);
      if(bps>1024){
        const secs=Math.max(1,Math.round((total-done)/bps));
        label+= secs>=120 ? ` — حدود ${Math.round(secs/60)} دقیقه مانده` : ` — حدود ${secs} ثانیه مانده`;
      }
    }
  }
  t.textContent=label;
};

function dismissAppUpdate(){
  el('updateBanner').style.display='none';
  if(PENDING_UPDATE) localStorage.setItem('upd_dismiss_'+PENDING_UPDATE.latest_version,'1');
}

/* ============================================================
   CLOCK + SW + INIT
============================================================ */
setInterval(()=>{
  const c=el('clock');
  if(c) c.textContent=_serverNow().toLocaleTimeString('fa-IR',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit'});
}, 1000);

window.addEventListener('resize', ()=>{ clearTimeout(window._rsz); window._rsz=setTimeout(fitStatNums,120); });
window.addEventListener('DOMContentLoaded', async ()=>{
  // Service worker breaks embedded Android WebView (stale cache / hung boot)
  const isAndroidApp = navigator.userAgent.includes('ERPTaranomAndroid') || navigator.userAgent.includes('CRMTaranomAndroid');
  if(isAndroidApp && 'serviceWorker' in navigator){
    try{
      const regs = await navigator.serviceWorker.getRegistrations();
      for(const r of regs) await r.unregister();
    }catch(e){}
  } else if('serviceWorker' in navigator){
    try{ navigator.serviceWorker.register(CSP.scriptUrl('/sw.js')); }catch(e){}
  }
  // Sync toggle-button labels + meta theme-color with the pre-paint theme
  applyTheme(currentTheme());
  // Sync server time first (no auth needed) so all date defaults are accurate
  await syncServerTime();
  // B2B portal deep link (#portal) — customers land here directly
  if(location.hash==='#portal'){ openB2BPortal(); return; }
  if(typeof maybeShowInviteAccept==='function' && maybeShowInviteAccept()) return;
  // Show the portal link on the staff login page only when the feature is
  // enabled on the central server (app-info is public, returns no secrets)
  fetch('/api/system/app-info').then(r=>r.json()).then(info=>{
    APP_INFO = APP_INFO || info;
    if(info && info.role==='central' && info.b2b_portal){ const l=el('b2bEntryLink'); if(l) l.style.display='block'; }
    if(info && info.role==='device'){ const d=el('deviceResetLink'); if(d) d.style.display='block'; }
  }).catch(()=>{});
  const token = localStorage.getItem('crm_token');
  if(token){
    try{ ME = JSON.parse(localStorage.getItem('crm_user')); await boot(); }
    catch(e){ logout(); }
  }
});

